async function resolveTeacherAcademicServerScope(activeUser: ActiveUserContext, assignmentId: string) {
  if (!['teacher','class_teacher','headmaster'].includes(activeUser.role)) throw new Error('Assigned teaching account required.');
  const comm: any = await loadTeacherCommunicationScopes(activeUser);
  const scope = (comm.scopes || []).find((row: any) => row.scopeType === 'subject' && (
    String(row.assignmentId || '') === assignmentId || String(row.id || '') === assignmentId || String(row.id || '') === `subject:${assignmentId}`
  ));
  if (!scope) throw new Error('This Academic scope is not part of your current Headmaster-assigned Subject Teacher mapping.');
  return { comm, scope };
}

function teacherAcademicRecordPayload(activeUser: ActiveUserContext, comm: any, scope: any, input: any) {
  const scopeSnapshot = {
    assignmentId: String(scope.assignmentId || input.assignmentId || ''),
    academicYearId: scope.academicYearId || null,
    academicYear: String(scope.academicYear || comm.academicYear || 'Current Academic Year'),
    classId: String(scope.classId || ''), className: String(scope.className || ''),
    divisionId: scope.divisionId ? String(scope.divisionId) : null, division: String(scope.division || ''),
    subjectId: String(scope.subjectId || ''), subjectName: String(scope.subjectName || ''),
    teacherRecordId: String(comm.teacherId || ''),
  };
  return {
    owner_teacher_id: activeUser.userId,
    teacher_record_id: comm.teacherId || null,
    school_id: activeUser.schoolId,
    academic_year_id: scope.academicYearId || null,
    academic_year: String(scope.academicYear || comm.academicYear || 'Current Academic Year'),
    assignment_id: scope.assignmentId || input.assignmentId,
    class_id: scope.classId || null,
    class_name: String(scope.className || ''),
    division_id: scope.divisionId || null,
    division_name: String(scope.division || ''),
    subject_id: scope.subjectId || null,
    subject_name: String(scope.subjectName || ''),
    kind: input.kind,
    title: input.title,
    status: input.status,
    content: input.content,
    metadata: { ...(input.metadata && typeof input.metadata === 'object' ? input.metadata : {}), scopeSnapshot },
    updated_at: new Date().toISOString(),
  };
}

