function edunixoSchoolDateKey(date = new Date(), timeZone = EDUNIXO_DEFAULT_SCHOOL_TIME_ZONE) {
  const parts = new Intl.DateTimeFormat('en-GB', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(date);
  const get = (type: 'year' | 'month' | 'day') => parts.find(part => part.type === type)?.value || '';
  const year = get('year'), month = get('month'), day = get('day');
  if (!year || !month || !day) throw new Error('School date could not be resolved.');
  return `${year}-${month}-${day}`;
}

