  app.post('/api/headmaster/result-curriculum-packs/:packId/decision', verifyAcademicAdminAuth, requireAcademicAdminModule('results'), async (req: AcademicAdminRequest, res) => {
    if(!req.academicAdmin||!supabaseAdmin)return res.status(503).json({error:'Curriculum Result Pack approval service is unavailable.'});
    if(req.academicAdmin.role!=='headmaster')return res.status(403).json({error:'Final Curriculum Result Pack approval is Headmaster-only.'});
    try{
      const packId=safePublicText(req.params.packId,120);const decision=safePublicText(req.body?.decision,30).toLowerCase();const note=safePublicText(req.body?.note,6000);
      if(!['approve','return'].includes(decision))return res.status(400).json({error:'Choose Approve or Return.'});
      const read=await supabaseAdmin.from('edunixo_result_templates').select('*').eq('id',packId).eq('school_id',req.academicAdmin.schoolId).eq('category',RESULT_CURRICULUM_PACK_CATEGORY).maybeSingle();
      if(read.error){if(clerkMissingRuntime(read.error.message))return res.status(503).json({error:'Result Master cloud table is not installed yet.'});throw read.error;}if(!read.data)return res.status(404).json({error:'Curriculum Result Pack was not found.'});
      const current:any=read.data.definition||{};
      const currentPlatformBoardId=safePublicText(current?.academicCoreSelection?.id,120);
      if(String(current.status||'')==='approved'&&decision==='approve'){
        if(currentPlatformBoardId) await activateSchoolAcademicProfileForPack(req.academicAdmin.schoolId,req.academicAdmin.userId,currentPlatformBoardId,current?.proposal||{});
        return res.json({success:true,pack:read.data,idempotent:true});
      }
      const now=new Date().toISOString();
      let verifiedAcademicCore:any=null;
      if(decision==='approve'){
        if(Number(current?.schemaVersion||0)>=3&&!currentPlatformBoardId)return res.status(409).json({error:'This Curriculum Pack has no locked Platform Board/State selection. Return it to Clerk and select the curriculum again.'});
        if(currentPlatformBoardId){
          verifiedAcademicCore=await resolvePlatformAcademicBoard(currentPlatformBoardId);
          if(!verifiedAcademicCore.rulesReady||!verifiedAcademicCore.rulesetId)return res.status(409).json({error:`${verifiedAcademicCore.boardName} is selected, but its verified Platform Rules Pack is not published yet. Super Admin must publish the official ruleset before Headmaster activation.`});
        }
        const systemState=await resultSystemStateForSchool(req.academicAdmin.schoolId,packId);
        if(systemState.configured)return res.status(409).json({error:'This school already has an operational Result System. A second curriculum cannot be activated from onboarding. Use the protected Result System Migration workflow for a future academic year.'});
        const others=await supabaseAdmin.from('edunixo_result_templates').select('id,definition,active').eq('school_id',req.academicAdmin.schoolId).eq('category',RESULT_CURRICULUM_PACK_CATEGORY).neq('id',packId);
        if(!others.error){for(const row of others.data||[]){const def:any=row.definition||{};if(String(def.status||'')==='approved'){await supabaseAdmin.from('edunixo_result_templates').update({active:false,updated_at:now,definition:{...def,activation:{...(def.activation||{}),isActive:false,deactivatedAt:now}}}).eq('id',row.id).eq('school_id',req.academicAdmin.schoolId);}}}
      }
      const definition={...current,status:decision==='approve'?'approved':'returned',approval:{decision,headmasterUserId:req.academicAdmin.userId,note,decidedAt:now},activation:{...(current.activation||{}),mode:'new_school_onboarding_only',legacyTemplatesPreserved:true,boardIsolation:Boolean(currentPlatformBoardId),platformRulesetId:verifiedAcademicCore?.rulesetId||current?.activation?.platformRulesetId||null,platformRulesetVersion:verifiedAcademicCore?.rulesetVersion||current?.activation?.platformRulesetVersion||null,isActive:decision==='approve',activatedAt:decision==='approve'?now:null}};
      const updated=await supabaseAdmin.from('edunixo_result_templates').update({definition,active:decision==='approve',updated_at:now}).eq('id',packId).eq('school_id',req.academicAdmin.schoolId).select('*').single();if(updated.error)throw updated.error;
      let academicProfile:any=null;
      if(decision==='approve'&&currentPlatformBoardId){
        academicProfile=await activateSchoolAcademicProfileForPack(req.academicAdmin.schoolId,req.academicAdmin.userId,currentPlatformBoardId,current?.proposal||{});
      }
      await supabaseAdmin.from('audit_logs').insert({school_id:req.academicAdmin.schoolId,actor_user_id:req.academicAdmin.userId,actor_kind:'school_user',action:decision==='approve'?'result.curriculum_pack.approved':'result.curriculum_pack.returned',entity_type:'result_template',entity_id:packId,summary:`Headmaster ${decision==='approve'?'approved and activated':'returned'} Curriculum Result Pack ${String(updated.data?.name||'')}.`,metadata:{note,legacy_templates_preserved:true,platform_board_id:academicProfile?.selected?.id||currentPlatformBoardId||null,platform_ruleset_id:academicProfile?.selected?.rulesetId||null,board_isolation:Boolean(currentPlatformBoardId)}});
      return res.json({success:true,pack:updated.data,academicProfile:academicProfile?.profile||null});
    }catch(error:any){return res.status(500).json({error:error?.message||'Curriculum Result Pack decision could not be saved.'});}
  });

