  app.put('/api/clerk/result-master-templates/:templateKey', verifyAcademicAdminAuth, requireAcademicAdminModule('results'), async (req: AcademicAdminRequest, res) => {
    if (!req.academicAdmin || !supabaseAdmin) return res.status(503).json({ error: 'Result Master service is unavailable.' });
    if (req.academicAdmin.role !== 'clerk') return res.status(403).json({ error: 'Result Master editing is Clerk-only.' });
    try {
      const templateKey = safePublicText(req.params.templateKey, 100);
      if (!RESULT_MASTER_TEMPLATE_KEYS.has(templateKey)) return res.status(400).json({ error: 'Choose a canonical Result Master template category.' });
      const definition = req.body?.definition;
      if (!definition || typeof definition !== 'object' || Array.isArray(definition)) return res.status(400).json({ error: 'A valid Result Master definition is required.' });
      const serialized = JSON.stringify(definition);
      if (serialized.length > 2_000_000) return res.status(413).json({ error: 'Result Master definition is too large.' });
      const patch:any = {
        name: safePublicText(req.body?.name, 240) || templateKey,
        category: safePublicText(req.body?.category, 160) || templateKey,
        description: safePublicText(req.body?.description, 3000) || '',
        definition,
        active: req.body?.active !== false,
        updated_at: new Date().toISOString()
      };
      const existing = await supabaseAdmin.from('edunixo_result_templates').select('id').eq('school_id', req.academicAdmin.schoolId).eq('template_key', templateKey).maybeSingle();
      if (existing.error && clerkMissingRuntime(existing.error.message)) return res.status(503).json({ error: 'Result Master cloud table is not installed yet.' });
      if (existing.error) throw existing.error;
      let row:any = null;
      if (existing.data?.id) {
        const updated = await supabaseAdmin.from('edunixo_result_templates').update(patch).eq('id', existing.data.id).eq('school_id', req.academicAdmin.schoolId).select('*').single();
        if (updated.error) throw updated.error;
        row = updated.data;
      } else {
        const inserted = await supabaseAdmin.from('edunixo_result_templates').insert({ school_id:req.academicAdmin.schoolId, template_key:templateKey, ...patch }).select('*').single();
        if (inserted.error) throw inserted.error;
        row = inserted.data;
      }
      await supabaseAdmin.from('audit_logs').insert({
        school_id:req.academicAdmin.schoolId, actor_user_id:req.academicAdmin.userId, actor_kind:'school_user',
        action:'result.master_template.saved', entity_type:'result_template', entity_id:String(row?.id || templateKey),
        summary:`Clerk saved canonical Result Master template ${templateKey}.`, metadata:{ template_key:templateKey }
      });
      return res.json({ success:true, template:row });
    } catch (error:any) {
      return res.status(500).json({ error:error?.message || 'Result Master template could not be saved.' });
    }
  });

