  app.get('/api/clerk/admissions/next-identifiers', verifyAcademicAdminAuth, requireAcademicAdminModule('admissions'), async (req: AcademicAdminRequest, res) => {
    res.setHeader('Cache-Control', 'no-store');
    if (!req.academicAdmin || !supabaseAdmin) return res.status(503).json({ error: 'Admission numbering service is unavailable.' });
    if (req.academicAdmin.role !== 'clerk') return res.status(403).json({ error: 'Admission intake numbering is Clerk-only.' });
    try {
      const year = String(new Date().getFullYear());
      const sequence = (value:any, prefix:string) => {
        let raw = String(value || '').trim().toUpperCase();
        if (!raw) return 0;
        raw = raw.replace(new RegExp(`^${prefix}`, 'i'), '');
        let digits = raw.replace(/\D/g, '');
        while (digits.startsWith(year) && digits.length > year.length) digits = digits.slice(year.length);
        const parsed = Number.parseInt(digits, 10);
        return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
      };
      const [students, applications, events] = await Promise.all([
        headmasterReadRows('students', req.academicAdmin.schoolId, '*', query => query.limit(10000)),
        supabaseAdmin.from('school_admission_applications').select('application_payload,status').eq('school_id', req.academicAdmin.schoolId).limit(10000),
        supabaseAdmin.from('school_admission_application_events').select('event_payload').eq('school_id', req.academicAdmin.schoolId).eq('event_type','admission_confirmed').limit(10000)
      ]);
      if (!students.available && students.error) throw new Error(students.error);
      if (applications.error) throw applications.error;
      if (events.error) throw events.error;
      let maxGr = 100, maxAdmission = 500;
      for (const row of students.rows || []) {
        maxGr = Math.max(maxGr, sequence((row as any).gr_number || (row as any).gr_no, 'GR'));
        maxAdmission = Math.max(maxAdmission, sequence((row as any).admission_number || (row as any).admission_no, 'ADM'));
      }
      for (const row of applications.data || []) {
        if (['rejected','cancelled','archived'].includes(String((row as any).status || '').toLowerCase())) continue;
        const office = (row as any)?.application_payload?.office || {};
        maxGr = Math.max(maxGr, sequence(office.proposedGrNumber, 'GR'));
        maxAdmission = Math.max(maxAdmission, sequence(office.proposedAdmissionNumber, 'ADM'));
      }
      for (const row of events.data || []) {
        const event = (row as any).event_payload || {};
        maxGr = Math.max(maxGr, sequence(event.grNumber, 'GR'));
        maxAdmission = Math.max(maxAdmission, sequence(event.admissionNumber || event.proposedAdmissionNumber, 'ADM'));
      }
      return res.json({ success:true, year, grNumber:`GR${year}${maxGr + 1}`, admissionNumber:`ADM${year}${maxAdmission + 1}` });
    } catch (error:any) {
      return res.status(500).json({ error:error?.message || 'Next Admission identifiers could not be calculated from cloud data.' });
    }
  });

