      const inserted=await supabaseAdmin.from('edunixo_fee_heads').insert({school_id:req.academicAdmin.schoolId,academic_year_id:year.id,name,amount,frequency,applicable_class_ids:classIds,due_date:safePublicText(req.body?.dueDate,20)||null,is_optional:Boolean(req.body?.isOptional),is_active:true,created_by_user_id:req.academicAdmin.userId}).select('*').single();
