      if(req.body?.frequency!==undefined){const f=safePublicText(req.body.frequency,40); if(!['One Time','Monthly','Quarterly','Half Yearly','Yearly'].includes(f)) return res.status(400).json({error:'Invalid fee frequency.'}); patch.frequency=f;}
      if(req.body?.applicableClassIds!==undefined) patch.applicable_class_ids=Array.from(new Set((Array.isArray(req.body.applicableClassIds)?req.body.applicableClassIds:[]).map((x:any)=>safePublicText(x,80)).filter(Boolean)));
      if(req.body?.dueDate!==undefined) patch.due_date=safePublicText(req.body.dueDate,20)||null;
