      await supabaseAdmin.from('audit_logs').insert({school_id:req.academicAdmin.schoolId,actor_user_id:req.academicAdmin.userId,actor_kind:'school_user',action:'fee.head.updated',entity_type:'fee_head',entity_id:headId,summary:`Clerk updated fee head ${String(updated.data.name||'')}.`,before_state:current.data,after_state:updated.data});
