  app.get('/api/admin/fee-approval-requests', verifyAcademicAdminAuth, requireAcademicAdminModule('fees'), async (req: AcademicAdminRequest, res) => {
    if (!supabaseAdmin || !req.academicAdmin) return res.status(503).json({ error: 'Fee approval workflow is unavailable.' });
    if (!['headmaster', 'clerk'].includes(req.academicAdmin.role)) return res.status(403).json({ error: 'Fee approval workflow is limited to authorized school administration.' });
    try {
      const schoolId = req.academicAdmin.schoolId;
      const actions = ['fee.concession.requested', 'fee.concession.decided', 'fee.receipt_cancellation.requested', 'fee.receipt_cancellation.decided'];
      const { data: rows, error } = await supabaseAdmin.from('audit_logs').select('*').eq('school_id', schoolId).in('action', actions).order('created_at', { ascending: false }).limit(2000);
      if (error) throw error;
      const allRows = rows || [];
      const decisionMap = new Map<string, any>();
      for (const row of allRows) {
        if (!String(row.action || '').endsWith('.decided')) continue;
        const requestId = String(row.metadata?.request_id || '');
        if (requestId && !decisionMap.has(requestId)) decisionMap.set(requestId, row);
      }
      const mapRequest = (row: any) => {
        const decision = decisionMap.get(String(row.id || ''));
        return {
          id: String(row.id || ''),
          createdAt: row.created_at || null,
          summary: row.summary || '',
          request: row.metadata?.request || {},
          status: decision ? String(decision.metadata?.decision || 'reject') : 'pending',
          decisionAt: decision?.created_at || null,
          decisionNote: decision?.metadata?.note || null,
          decidedByName: decision?.metadata?.decided_by_name || null
        };
      };
      return res.json({
        concessions: allRows.filter((row: any) => row.action === 'fee.concession.requested').map(mapRequest),
        cancellations: allRows.filter((row: any) => row.action === 'fee.receipt_cancellation.requested').map(mapRequest)
      });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Fee approval requests could not be loaded.' });
    }
  });

  app.post('/api/clerk/fee-concession-requests', verifyAcademicAdminAuth, requireAcademicAdminModule('fees'), async (req: AcademicAdminRequest, res) => {
    if (!supabaseAdmin || !req.academicAdmin) return res.status(503).json({ error: 'Fee concession workflow is unavailable.' });
    if (req.academicAdmin.role !== 'clerk') return res.status(403).json({ error: 'Fee concession preparation is Clerk-only.' });
    try {
      const grNumber = safePublicText(req.body?.grNumber, 80);
      const concessionType = safePublicText(req.body?.concessionType, 40);
      const value = Number(req.body?.value || 0);
      const remarks = safePublicText(req.body?.remarks, 1200);
      const allowedTypes = ['Fixed', 'Percentage', 'Scholarship', 'Staff Discount', 'Sibling', 'Custom'];
      if (!grNumber || !allowedTypes.includes(concessionType) || !Number.isFinite(value) || value <= 0) return res.status(400).json({ error: 'Choose a valid student, concession type and value.' });
      const studentMaster = await loadClerkStudentMaster(req.academicAdmin.schoolId);
      const student = studentMaster.students.find((row: any) => clerkNorm(row.grNumber) === clerkNorm(grNumber));
      if (!student) return res.status(404).json({ error: 'Student Master record was not found for this GR number.' });
      const { data: prior, error: priorError } = await supabaseAdmin.from('audit_logs').select('id').eq('school_id', req.academicAdmin.schoolId).eq('action', 'fee.concession.requested').eq('entity_id', String(student.id)).order('created_at', { ascending: false }).limit(100);
      if (priorError) throw priorError;
      const priorIds = (prior || []).map((row: any) => String(row.id || '')).filter(Boolean);
      const { data: decisions, error: decisionError } = priorIds.length
        ? await supabaseAdmin.from('audit_logs').select('metadata').eq('school_id', req.academicAdmin.schoolId).eq('action', 'fee.concession.decided')
        : { data: [], error: null } as any;
      if (decisionError) throw decisionError;
      const decided = new Set((decisions || []).map((row: any) => String(row.metadata?.request_id || '')).filter(Boolean));
      if (priorIds.some(id => !decided.has(id))) return res.status(409).json({ error: 'A fee concession request is already pending Headmaster decision for this student.' });
      const feeYear = await resolveClerkAcademicYear(req.academicAdmin.schoolId, safePublicText(req.body?.academicYearId, 100) || null);
      const request = {
        grNumber,
        studentName: safePublicText(student.name, 200),
        classId: String(student.classId || ''),
        academicYearId: feeYear.id,
        academicYear: feeYear.year,
        concessionType,
        value,
        remarks,
        requestedBy: 'Clerk'
      };
      const { data: inserted, error: insertError } = await supabaseAdmin.from('audit_logs').insert({
        actor_user_id: req.academicAdmin.userId,
        actor_kind: 'school_user',
        action: 'fee.concession.requested',
        entity_type: 'student',
        entity_id: String(student.id),
        school_id: req.academicAdmin.schoolId,
        summary: `Clerk requested ${concessionType} fee concession for GR ${grNumber}.`,
        before_state: null,
        after_state: null,
        metadata: { workflow: 'fee_concession', request_status: 'pending', request }
      }).select('id').single();
      if (insertError) throw insertError;
      return res.json({ success: true, requestId: String(inserted?.id || ''), request });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Fee concession request could not be sent.' });
    }
  });

  app.post('/api/headmaster/fee-concession-requests/:requestId/decision', verifyHeadmasterAuth, requireHeadmasterModule('fees'), async (req: HeadmasterRequest, res) => {
    if (!supabaseAdmin || !req.authenticatedHeadmaster) return res.status(503).json({ error: 'Fee concession workflow is unavailable.' });
    try {
      const schoolId = req.authenticatedHeadmaster.schoolId;
      const requestId = safePublicText(req.params.requestId, 100);
      const decision = safePublicText(req.body?.decision, 20).toLowerCase();
      if (!['approve', 'reject'].includes(decision)) return res.status(400).json({ error: 'Decision must be approve or reject.' });
      const { data: requestRow, error: requestError } = await supabaseAdmin.from('audit_logs').select('*').eq('id', requestId).eq('school_id', schoolId).eq('action', 'fee.concession.requested').maybeSingle();
      if (requestError) throw requestError;
      if (!requestRow) return res.status(404).json({ error: 'Fee concession request was not found.' });
      const { data: existing, error: existingError } = await supabaseAdmin.from('audit_logs').select('id').eq('school_id', schoolId).eq('action', 'fee.concession.decided').contains('metadata', { request_id: requestId }).maybeSingle();
      if (existingError) throw existingError;
      if (existing) return res.status(409).json({ error: 'This fee concession request has already been decided.' });
      const request = requestRow.metadata?.request || {};
      let approvedAdjustment: { academicYearId: string; amount: number; type: 'concession' | 'scholarship' } | null = null;
      if (decision === 'approve') {
        const snapshot = await buildClerkFeeSnapshot(schoolId, safePublicText(request.academicYearId, 100) || null);
        const profile = snapshot.profiles.find((row: any) => row.id === String(requestRow.entity_id || ''));
        if (!profile) return res.status(409).json({ error: 'Student fee profile could not be resolved for this concession.' });
        const rawValue = Number(request.value || 0);
        const amount = String(request.concessionType || '') === 'Percentage' ? Math.round((Number(profile.totalFee || 0) * rawValue) / 100) : rawValue;
        if (!Number.isFinite(amount) || amount <= 0) return res.status(409).json({ error: 'Approved concession amount could not be calculated.' });
        approvedAdjustment = { academicYearId: snapshot.academicYear.id, amount, type: String(request.concessionType || '') === 'Scholarship' ? 'scholarship' : 'concession' };
      }
      const { error: insertError } = await supabaseAdmin.from('audit_logs').insert({
        actor_user_id: req.authenticatedHeadmaster.userId,
        actor_kind: 'school_user',
        action: 'fee.concession.decided',
        entity_type: 'student',
        entity_id: String(requestRow.entity_id || ''),
        school_id: schoolId,
        summary: `Headmaster ${decision === 'approve' ? 'approved' : 'rejected'} fee concession for GR ${String(request.grNumber || '')}.`,
        before_state: null,
        after_state: null,
        metadata: { workflow: 'fee_concession', request_id: requestId, decision, note: safePublicText(req.body?.note, 1200) || null, decided_by_name: safePublicText(req.authenticatedHeadmaster.fullName || 'Headmaster', 200) }
      });
      if (insertError) throw insertError;
      if (decision === 'approve' && approvedAdjustment) {
        const projection = await supabaseAdmin.from('edunixo_fee_adjustments').upsert({
          school_id: schoolId, academic_year_id: approvedAdjustment.academicYearId, student_id: String(requestRow.entity_id || ''),
          adjustment_type: approvedAdjustment.type, amount: approvedAdjustment.amount, source_request_id: requestId,
          note: safePublicText(req.body?.note, 1200) || safePublicText(request.remarks, 1200) || `${String(request.concessionType || 'Fee')} approved by Headmaster`,
          status: 'active', approved_by_user_id: req.authenticatedHeadmaster.userId
        }, { onConflict: 'school_id,source_request_id' });
        if (projection.error) throw projection.error;
      }
      return res.json({ success: true, decision });
    } catch (error: any) {
      return res.status(String(error?.message || '').includes('setup is pending') ? 503 : 500).json({ error: error?.message || 'Fee concession decision could not be saved.' });
    }
  });

  app.post('/api/clerk/fee-receipt-cancellation-requests', verifyAcademicAdminAuth, requireAcademicAdminModule('fees'), async (req: AcademicAdminRequest, res) => {
    if (!supabaseAdmin || !req.academicAdmin) return res.status(503).json({ error: 'Receipt cancellation workflow is unavailable.' });
    if (req.academicAdmin.role !== 'clerk') return res.status(403).json({ error: 'Receipt cancellation preparation is Clerk-only.' });
    try {
      const input = req.body?.receipt && typeof req.body.receipt === 'object' ? req.body.receipt : {};
      const receiptNo = safePublicText(input.receiptNo, 120);
      const grNumber = safePublicText(input.grNumber, 80);
      const reason = safePublicText(req.body?.reason, 1200);
      const amountPaid = Number(input.amountPaid || 0);
      if (!receiptNo || !grNumber || !reason || !Number.isFinite(amountPaid) || amountPaid <= 0) return res.status(400).json({ error: 'Receipt, GR number, amount and cancellation reason are required.' });
      const studentMaster = await loadClerkStudentMaster(req.academicAdmin.schoolId);
      const student = studentMaster.students.find((row: any) => clerkNorm(row.grNumber) === clerkNorm(grNumber));
      if (!student) return res.status(404).json({ error: 'Student Master record was not found for this receipt GR number.' });
      const canonicalReceipt = await supabaseAdmin.from('edunixo_fee_transactions').select('*').eq('school_id', req.academicAdmin.schoolId).eq('receipt_no', receiptNo).eq('student_id', String(student.id)).maybeSingle();
      if (canonicalReceipt.error) { if (clerkMissingRuntime(canonicalReceipt.error.message)) return res.status(503).json({ error: clerkSetupPendingMessage }); throw canonicalReceipt.error; }
      if (!canonicalReceipt.data) return res.status(404).json({ error: 'Canonical fee receipt was not found. Legacy browser-only receipts cannot be cancelled as official cloud records.' });
      if (String(canonicalReceipt.data.status || '') === 'cancelled') return res.status(409).json({ error: 'This receipt is already cancelled.' });
      const { data: prior, error: priorError } = await supabaseAdmin.from('audit_logs').select('id,metadata').eq('school_id', req.academicAdmin.schoolId).eq('action', 'fee.receipt_cancellation.requested').order('created_at', { ascending: false }).limit(1000);
      if (priorError) throw priorError;
      const matching = (prior || []).filter((row: any) => String(row.metadata?.request?.receiptNo || '') === receiptNo);
      const matchingIds = matching.map((row: any) => String(row.id || '')).filter(Boolean);
      const { data: decisions, error: decisionError } = matchingIds.length
        ? await supabaseAdmin.from('audit_logs').select('metadata').eq('school_id', req.academicAdmin.schoolId).eq('action', 'fee.receipt_cancellation.decided')
        : { data: [], error: null } as any;
      if (decisionError) throw decisionError;
      const decided = new Set((decisions || []).map((row: any) => String(row.metadata?.request_id || '')).filter(Boolean));
      if (matchingIds.some(id => !decided.has(id))) return res.status(409).json({ error: 'A cancellation request is already pending Headmaster decision for this receipt.' });
      const request = {
        receiptNo,
        grNumber,
        studentName: safePublicText(input.studentName, 200) || safePublicText(student.name, 200),
        className: safePublicText(input.className, 120),
        division: safePublicText(input.division, 40),
        academicYear: safePublicText(input.academicYear, 40),
        amountPaid,
        paymentDate: safePublicText(input.paymentDate, 40),
        paymentMode: safePublicText(input.paymentMode, 40),
        reason,
        requestedBy: safePublicText(req.academicAdmin.fullName || 'Clerk', 200)
      };
      const { data: inserted, error: insertError } = await supabaseAdmin.from('audit_logs').insert({
        actor_user_id: req.academicAdmin.userId,
        actor_kind: 'school_user',
        action: 'fee.receipt_cancellation.requested',
        entity_type: 'student',
        entity_id: String(student.id),
        school_id: req.academicAdmin.schoolId,
        summary: `Clerk requested cancellation of receipt ${receiptNo} for GR ${grNumber}.`,
        before_state: null,
        after_state: null,
        metadata: { workflow: 'fee_receipt_cancellation', request_status: 'pending', request }
      }).select('id').single();
      if (insertError) throw insertError;
      const pending = await supabaseAdmin.from('edunixo_fee_transactions').update({ status: 'cancellation_pending', cancellation_reason: reason }).eq('school_id', req.academicAdmin.schoolId).eq('receipt_no', receiptNo).eq('student_id', String(student.id));
      if (pending.error) throw pending.error;
      return res.json({ success: true, requestId: String(inserted?.id || ''), request });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Receipt cancellation request could not be sent.' });
    }
  });

