      const ins=await supabaseAdmin.from('edunixo_communication_templates').insert({school_id:req.authenticatedHeadmaster.schoolId,name,channel,category:safePublicText(req.body?.category,80)||'General',subject:safePublicText(req.body?.subject,300)||null,body,target_roles:targetRoles,is_active:true,created_by_user_id:req.authenticatedHeadmaster.userId}).select('*').single();
      if(ins.error){if(headmasterCommunicationMissing(ins.error))return res.status(503).json({error:headmasterCommunicationSetupMessage});throw ins.error;}
      await supabaseAdmin.from('audit_logs').insert({school_id:req.authenticatedHeadmaster.schoolId,actor_user_id:req.authenticatedHeadmaster.userId,actor_kind:'school_user',action:'communication.template.headmaster_created',entity_type:'communication_template',entity_id:String(ins.data.id),summary:`Headmaster created communication template ${name}.`});
      return res.json({success:true,template:ins.data});
