  app.get('/api/admin/certificate-requests', verifyAcademicAdminAuth, requireAcademicAdminModule('administration'), async (req: AcademicAdminRequest, res) => {
    if (!supabaseAdmin || !req.academicAdmin) return res.status(503).json({ error: 'Certificate approval workflow is unavailable.' });
    if (!['headmaster', 'clerk'].includes(req.academicAdmin.role)) return res.status(403).json({ error: 'Certificate workflow access is limited to authorized school administration.' });
    try {
      const schoolId = req.academicAdmin.schoolId;
      const { data: requests, error: requestError } = await supabaseAdmin.from('audit_logs')
        .select('*').eq('school_id', schoolId).eq('action', 'certificate.issue.requested').order('created_at', { ascending: false }).limit(1000);
      if (requestError) throw requestError;
      const { data: decisions, error: decisionError } = await supabaseAdmin.from('audit_logs')
        .select('id,created_at,metadata,summary').eq('school_id', schoolId).eq('action', 'certificate.issue.decided').order('created_at', { ascending: false }).limit(1000);
      if (decisionError) throw decisionError;
      const { data: statusRows, error: statusError } = await supabaseAdmin.from('audit_logs')
        .select('created_at,metadata,summary').eq('school_id', schoolId).eq('action', 'certificate.status.changed').order('created_at', { ascending: false }).limit(2000);
      if (statusError) throw statusError;
      const { data: school, error: schoolError } = await supabaseAdmin.from('schools').select('id,name,school_code').eq('id', schoolId).maybeSingle();
      if (schoolError) throw schoolError;
      const decisionMap = new Map<string, any>();
      for (const row of decisions || []) {
        const requestId = String(row.metadata?.request_id || '');
        if (requestId && !decisionMap.has(requestId)) decisionMap.set(requestId, row);
      }
      const statusMap = new Map<string, any>();
      for (const row of statusRows || []) {
        const certificateNumber = String(row.metadata?.certificate_number || '');
        if (certificateNumber && !statusMap.has(certificateNumber)) statusMap.set(certificateNumber, row);
      }
      const todayKey = new Date().toISOString().slice(0, 10);
      return res.json({
        school: { id: schoolId, name: safePublicText(school?.name || 'School', 200), code: safePublicText(school?.school_code, 80) },
        requests: (requests || []).map((row: any) => {
          const requestId = String(row.id || '');
          const decision = decisionMap.get(requestId);
          const certificate = decision?.metadata?.certificate || row.metadata?.certificate || {};
          const certificateNumber = String(certificate?.certificateNumber || '');
          const latestStatus = certificateNumber ? statusMap.get(certificateNumber) : null;
          const expiryDate = safePublicText(latestStatus?.metadata?.expiry_date || certificate?.expiryDate, 30);
          const isExpired = Boolean(expiryDate && /^\d{4}-\d{2}-\d{2}$/.test(expiryDate) && expiryDate < todayKey);
          const certificateStatus = decision?.metadata?.decision === 'approve'
            ? (String(latestStatus?.metadata?.status || '').toLowerCase() === 'revoked' ? 'revoked' : isExpired ? 'expired' : 'valid')
            : null;
          return {
            id: requestId,
            studentId: String(row.entity_id || ''),
            createdAt: row.created_at || null,
            summary: row.summary || '',
            certificate,
            status: decision ? String(decision.metadata?.decision || 'rejected') : 'pending',
            decisionAt: decision?.created_at || null,
            decisionNote: decision?.metadata?.note || null,
            decidedByName: decision?.metadata?.decided_by_name || null,
            certificateStatus,
            statusChangedAt: latestStatus?.created_at || null,
            statusReason: latestStatus?.metadata?.reason || null,
            expiryDate: expiryDate || null
          };
        })
      });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Certificate requests could not be loaded.' });
    }
  });

  app.post('/api/clerk/certificate-requests', verifyAcademicAdminAuth, requireAcademicAdminModule('administration'), async (req: AcademicAdminRequest, res) => {
    if (!supabaseAdmin || !req.academicAdmin) return res.status(503).json({ error: 'Certificate approval workflow is unavailable.' });
    if (req.academicAdmin.role !== 'clerk') return res.status(403).json({ error: 'Certificate preparation requests are Clerk-only.' });
    try {
      const input = req.body?.certificate && typeof req.body.certificate === 'object' ? req.body.certificate : {};
      const grNumber = safePublicText(input.grNumber, 80);
      const studentName = safePublicText(input.studentName, 200);
      const certificateType = safePublicText(input.certificateType, 60).toLowerCase();
      const allowedTypes = ['bonafide', 'study', 'character', 'leaving', 'custom'];
      if (!grNumber || !studentName || !allowedTypes.includes(certificateType)) return res.status(400).json({ error: 'Choose a valid student and certificate type.' });
      const { data: student, error: studentError } = await supabaseAdmin.from('students').select('id,gr_number,full_name').eq('school_id', req.academicAdmin.schoolId).eq('gr_number', grNumber).maybeSingle();
      if (studentError) throw studentError;
      if (!student) return res.status(404).json({ error: 'Student Master record was not found for this GR number.' });
      const certificate = {
        grNumber,
        studentName: safePublicText(student.full_name, 200) || studentName,
        certificateType,
        certificateNumber: safePublicText(input.certificateNumber, 120),
        issueDate: safePublicText(input.issueDate, 30),
        purpose: safePublicText(input.purpose, 500),
        expiryDate: safePublicText(input.expiryDate, 30),
        language: ['en', 'mr', 'ur'].includes(String(input.language || '')) ? String(input.language) : 'en',
        remarks: safePublicText(input.remarks, 2000),
        preparedBy: safePublicText(input.preparedBy, 200),
        customTitle: safePublicText(input.customTitle, 300),
        customBody: safePublicText(input.customBody, 6000),
        lcFields: input.lcFields && typeof input.lcFields === 'object' ? Object.fromEntries(Object.entries(input.lcFields).slice(0, 40).map(([key, value]) => [safePublicText(key, 80), safePublicText(value, 1000)])) : null,
        signatures: input.signatures && typeof input.signatures === 'object' ? input.signatures : null,
        styleSettings: input.styleSettings && typeof input.styleSettings === 'object' ? input.styleSettings : null
      };
      const { data: previous, error: previousError } = await supabaseAdmin.from('audit_logs')
        .select('id,metadata').eq('school_id', req.academicAdmin.schoolId).eq('action', 'certificate.issue.requested').eq('entity_id', String(student.id)).order('created_at', { ascending: false }).limit(100);
      if (previousError) throw previousError;
      const previousIds = (previous || []).map((row: any) => String(row.id || '')).filter(Boolean);
      const { data: decisions, error: decisionError } = previousIds.length
        ? await supabaseAdmin.from('audit_logs').select('metadata').eq('school_id', req.academicAdmin.schoolId).eq('action', 'certificate.issue.decided')
        : { data: [], error: null } as any;
      if (decisionError) throw decisionError;
      const decided = new Set((decisions || []).map((row: any) => String(row.metadata?.request_id || '')).filter(Boolean));
      const duplicate = (previous || []).find((row: any) => !decided.has(String(row.id)) && String(row.metadata?.certificate?.certificateType || '') === certificateType);
      if (duplicate) return res.status(409).json({ error: `A ${certificateType} certificate request is already pending Headmaster decision for this student.` });
      const { data: inserted, error: insertError } = await supabaseAdmin.from('audit_logs').insert({
        actor_user_id: req.academicAdmin.userId,
        actor_kind: 'school_user',
        action: 'certificate.issue.requested',
        entity_type: 'student',
        entity_id: String(student.id),
        school_id: req.academicAdmin.schoolId,
        summary: `Clerk prepared ${certificateType} certificate ${certificate.certificateNumber || ''} for GR ${grNumber}.`,
        before_state: null,
        after_state: null,
        metadata: { workflow: 'certificate_issue', request_status: 'pending', certificate }
      }).select('id').single();
      if (insertError) throw insertError;
      return res.json({ success: true, requestId: String(inserted?.id || ''), certificate });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Certificate request could not be sent.' });
    }
  });

  app.post('/api/headmaster/certificate-requests/:requestId/decision', verifyHeadmasterAuth, requireHeadmasterModule('administration'), async (req: HeadmasterRequest, res) => {
    if (!supabaseAdmin || !req.authenticatedHeadmaster) return res.status(503).json({ error: 'Certificate approval workflow is unavailable.' });
    try {
      const schoolId = req.authenticatedHeadmaster.schoolId;
      const requestId = safePublicText(req.params.requestId, 100);
      const decision = safePublicText(req.body?.decision, 20).toLowerCase();
      if (!['approve', 'reject'].includes(decision)) return res.status(400).json({ error: 'Decision must be approve or reject.' });
      const { data: requestRow, error: requestError } = await supabaseAdmin.from('audit_logs').select('*').eq('id', requestId).eq('school_id', schoolId).eq('action', 'certificate.issue.requested').maybeSingle();
      if (requestError) throw requestError;
      if (!requestRow) return res.status(404).json({ error: 'Certificate request was not found.' });
      const { data: existingDecision, error: existingError } = await supabaseAdmin.from('audit_logs').select('id').eq('school_id', schoolId).eq('action', 'certificate.issue.decided').contains('metadata', { request_id: requestId }).maybeSingle();
      if (existingError) throw existingError;
      if (existingDecision) return res.status(409).json({ error: 'This certificate request has already been decided.' });
      const certificate = requestRow.metadata?.certificate || {};
      const requestedNumber = safePublicText(certificate.certificateNumber, 120);
      const finalCertificateNumber = decision === 'approve'
        ? (requestedNumber && !requestedNumber.startsWith('BULK-DRAFT/')
            ? requestedNumber
            : `CERT/${new Date().getFullYear()}/${String(requestId).replace(/[^A-Za-z0-9]/g, '').slice(-10).toUpperCase()}`)
        : requestedNumber;
      const certificateSnapshot = {
        ...certificate,
        certificateNumber: finalCertificateNumber,
        issueDate: decision === 'approve' ? new Date().toISOString().slice(0, 10) : safePublicText(certificate.issueDate, 30),
        approvedBy: decision === 'approve' ? safePublicText(req.authenticatedHeadmaster.fullName || 'Headmaster', 200) : '',
        officialMode: decision === 'approve'
      };
      const { error: insertError } = await supabaseAdmin.from('audit_logs').insert({
        actor_user_id: req.authenticatedHeadmaster.userId,
        actor_kind: 'school_user',
        action: 'certificate.issue.decided',
        entity_type: 'student',
        entity_id: String(requestRow.entity_id || ''),
        school_id: schoolId,
        summary: `Headmaster ${decision === 'approve' ? 'approved and issued' : 'rejected'} ${String(certificate.certificateType || 'certificate')} ${String(certificate.certificateNumber || '')}.`,
        before_state: null,
        after_state: null,
        metadata: {
          workflow: 'certificate_issue', request_id: requestId, decision,
          note: safePublicText(req.body?.note, 1200) || null,
          decided_by_name: safePublicText(req.authenticatedHeadmaster.fullName || 'Headmaster', 200),
          certificate: certificateSnapshot
        }
      });
      if (insertError) throw insertError;
      return res.json({ success: true, decision });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Certificate decision could not be saved.' });
    }
  });


  const loadPublicCertificateVerification = async (certificateIdRaw: unknown) => {
    if (!supabaseAdmin) throw new Error('Certificate verification service is unavailable.');
    const certificateId = safePublicText(certificateIdRaw, 160);
    if (!certificateId) return null;

    let decisionRow: any = null;
    const { data: directDecision, error: directError } = await supabaseAdmin.from('audit_logs')
      .select('id,school_id,created_at,metadata')
      .eq('action', 'certificate.issue.decided')
      .contains('metadata', { decision: 'approve', certificate: { certificateNumber: certificateId } })
      .order('created_at', { ascending: false })
      .limit(1)
      .maybeSingle();
    if (directError) throw directError;
    decisionRow = directDecision;

    if (!decisionRow) {
      const { data: requestRow, error: requestError } = await supabaseAdmin.from('audit_logs')
        .select('id,school_id,created_at,metadata')
        .eq('action', 'certificate.issue.requested')
        .contains('metadata', { certificate: { certificateNumber: certificateId } })
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle();
      if (requestError) throw requestError;
      if (!requestRow) return null;
      const { data: legacyDecision, error: legacyDecisionError } = await supabaseAdmin.from('audit_logs')
        .select('id,school_id,created_at,metadata')
        .eq('school_id', requestRow.school_id)
        .eq('action', 'certificate.issue.decided')
        .contains('metadata', { request_id: String(requestRow.id), decision: 'approve' })
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle();
      if (legacyDecisionError) throw legacyDecisionError;
      if (!legacyDecision) return null;
      decisionRow = { ...legacyDecision, metadata: { ...legacyDecision.metadata, certificate: legacyDecision.metadata?.certificate || requestRow.metadata?.certificate || {} } };
    }

    const certificate = decisionRow.metadata?.certificate || {};
    const schoolId = String(decisionRow.school_id || '');
    const { data: statusRows, error: statusError } = await supabaseAdmin.from('audit_logs')
      .select('created_at,metadata')
      .eq('school_id', schoolId)
      .eq('action', 'certificate.status.changed')
      .contains('metadata', { certificate_number: certificateId })
      .order('created_at', { ascending: false })
      .limit(1);
    if (statusError) throw statusError;
    const latestStatus = statusRows?.[0]?.metadata || null;
    const expiryDate = safePublicText(latestStatus?.expiry_date || certificate.expiryDate, 30);
    const isExpired = Boolean(expiryDate && /^\d{4}-\d{2}-\d{2}$/.test(expiryDate) && expiryDate < new Date().toISOString().slice(0, 10));
    const status = latestStatus?.status === 'revoked' ? 'REVOKED' : isExpired ? 'EXPIRED' : 'VALID';

    const { data: school } = await supabaseAdmin.from('schools').select('id,name,school_code').eq('id', schoolId).maybeSingle();
    return {
      certificateId,
      certificateNumber: certificateId,
      certificateType: safePublicText(certificate.certificateType, 60),
      issueDate: safePublicText(certificate.issueDate || decisionRow.created_at, 30).slice(0, 10),
      expiryDate: expiryDate || null,
      status,
      schoolName: safePublicText(school?.name || 'School', 200),
      _schoolId: schoolId,
      schoolCode: safePublicText(school?.school_code, 80),
      revokeReason: status === 'REVOKED' ? safePublicText(latestStatus?.reason, 500) : null
    };
  };

  app.get('/api/public/certificates/verify/:certificateId', async (req, res) => {
    try {
      const certificate = await loadPublicCertificateVerification(req.params.certificateId);
      if (!certificate) return res.status(404).json({ error: 'Certificate not found or not officially issued.' });
      const { _schoolId, ...publicCertificate } = certificate as any;
      return res.json({ certificate: publicCertificate });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Certificate verification failed.' });
    }
  });

  app.get('/verify-certificate/:certificateId', async (req, res) => {
    try {
      const certificate = await loadPublicCertificateVerification(req.params.certificateId);
      if (!certificate) return res.status(404).send('<!doctype html><html><body style="font-family:system-ui;padding:40px"><h1>Certificate not found</h1><p>This certificate ID is not recorded as officially issued.</p></body></html>');
      const statusColor = certificate.status === 'VALID' ? '#047857' : certificate.status === 'EXPIRED' ? '#b45309' : '#be123c';
      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      return res.send(`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Certificate Verification</title></head><body style="margin:0;background:#f8fafc;font-family:Inter,system-ui,sans-serif;color:#0f172a"><main style="max-width:680px;margin:48px auto;padding:0 18px"><section style="background:white;border:1px solid #e2e8f0;border-radius:24px;padding:28px;box-shadow:0 12px 40px rgba(15,23,42,.08)"><div style="font-size:12px;font-weight:800;letter-spacing:.12em;color:#64748b">Classtago CERTIFICATE VERIFICATION</div><h1 style="margin:8px 0 4px;font-size:28px">${escapePublicHtml(certificate.schoolName)}</h1><p style="margin:0 0 24px;color:#64748b">Official school certificate status</p><div style="display:inline-block;padding:9px 14px;border-radius:999px;background:${statusColor}15;color:${statusColor};font-weight:900">${escapePublicHtml(certificate.status)}</div><dl style="display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:26px"><div><dt style="font-size:11px;color:#64748b">Certificate ID</dt><dd style="margin:4px 0;font-family:monospace;font-weight:800">${escapePublicHtml(certificate.certificateId)}</dd></div><div><dt style="font-size:11px;color:#64748b">Type</dt><dd style="margin:4px 0;font-weight:800;text-transform:uppercase">${escapePublicHtml(certificate.certificateType)}</dd></div><div><dt style="font-size:11px;color:#64748b">Issue Date</dt><dd style="margin:4px 0;font-weight:800">${escapePublicHtml(certificate.issueDate)}</dd></div><div><dt style="font-size:11px;color:#64748b">Expiry</dt><dd style="margin:4px 0;font-weight:800">${escapePublicHtml(certificate.expiryDate || 'No expiry')}</dd></div></dl>${certificate.revokeReason ? `<div style="margin-top:20px;padding:12px;border-radius:12px;background:#fff1f2;color:#9f1239"><strong>Revocation reason:</strong> ${escapePublicHtml(certificate.revokeReason)}</div>` : ''}<p style="margin-top:28px;font-size:12px;color:#64748b">This page reveals only minimum verification information and does not expose the student's private school record.</p></section></main></body></html>`);
    } catch (error: any) {
      return res.status(500).send('Certificate verification service is temporarily unavailable.');
    }
  });

  app.post('/api/headmaster/certificates/:certificateId/status', verifyHeadmasterAuth, requireHeadmasterModule('administration'), async (req: HeadmasterRequest, res) => {
    if (!supabaseAdmin || !req.authenticatedHeadmaster) return res.status(503).json({ error: 'Certificate status service is unavailable.' });
    try {
      const certificateId = safePublicText(req.params.certificateId, 160);
      const status = safePublicText(req.body?.status, 20).toLowerCase();
      if (!certificateId || !['revoked', 'valid'].includes(status)) return res.status(400).json({ error: 'Choose a valid certificate status.' });
      const existing = await loadPublicCertificateVerification(certificateId);
      if (!existing || existing._schoolId !== req.authenticatedHeadmaster.schoolId) return res.status(404).json({ error: 'Officially issued certificate was not found for this school.' });
      const reason = safePublicText(req.body?.reason, 600);
      if (status === 'revoked' && !reason) return res.status(400).json({ error: 'Revocation reason is required.' });
      const { error: insertError } = await supabaseAdmin.from('audit_logs').insert({
        actor_user_id: req.authenticatedHeadmaster.userId,
        actor_kind: 'school_user',
        action: 'certificate.status.changed',
        entity_type: 'certificate',
        entity_id: certificateId,
        school_id: req.authenticatedHeadmaster.schoolId,
        summary: `Headmaster changed certificate ${certificateId} status to ${status}.`,
        before_state: null,
        after_state: null,
        metadata: {
          certificate_number: certificateId,
          status,
          reason: reason || null,
          expiry_date: safePublicText(req.body?.expiryDate, 30) || null
        }
      });
      if (insertError) throw insertError;
      return res.json({ success: true, status });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Certificate status could not be changed.' });
    }
  });

  app.post('/api/clerk/student-lifecycle-requests', verifyAcademicAdminAuth, requireAcademicAdminModule('master_data'), async (req: AcademicAdminRequest, res) => {
    if (!supabaseAdmin || !req.academicAdmin) return res.status(503).json({ error: 'Student Lifecycle request service is unavailable.' });
    if (req.academicAdmin.role !== 'clerk') return res.status(403).json({ error: 'This preparation route is Clerk-only.' });
    try {
      const studentId = safePublicText(req.body?.studentId, 100);
      const requestedAction = safePublicText(req.body?.requestedAction, 60).toLowerCase();
      const allowedActions = ['promotion_preparation', 'class_transfer', 'school_transfer', 'passout', 'leaving', 'archive'];
      if (!studentId || !allowedActions.includes(requestedAction)) return res.status(400).json({ error: 'Choose a valid student and lifecycle action.' });
      const { data: student, error: studentError } = await supabaseAdmin.from('students').select('*').eq('id', studentId).eq('school_id', req.academicAdmin.schoolId).maybeSingle();
      if (studentError) throw studentError;
      if (!student) return res.status(404).json({ error: 'Student record was not found in this school.' });
      const note = safePublicText(req.body?.note, 1200) || null;
      const targetClassId = safePublicText(req.body?.targetClassId, 100) || null;
      const targetDivisionId = safePublicText(req.body?.targetDivisionId, 100) || null;
      const targetAcademicYearId = safePublicText(req.body?.targetAcademicYearId, 100) || null;
      if (requestedAction === 'class_transfer') {
        if (!targetClassId) return res.status(400).json({ error: 'Choose a target class for the transfer request.' });
        const classRows = await firstAvailableSchoolTable(['school_classes', 'classes'], req.academicAdmin.schoolId, '*');
        if (!classRows.rows.some(row => String(row.id) === targetClassId)) return res.status(400).json({ error: 'Choose a valid target class.' });
        if (targetDivisionId) {
          const divisionRows = await firstAvailableSchoolTable(['school_divisions', 'divisions'], req.academicAdmin.schoolId, '*');
          const targetDivision = divisionRows.rows.find(row => String(row.id) === targetDivisionId);
          if (!targetDivision) return res.status(400).json({ error: 'Choose a valid target division.' });
          if (targetDivision.class_id && String(targetDivision.class_id) !== targetClassId) return res.status(400).json({ error: 'The target division does not belong to the target class.' });
        }
        if (targetAcademicYearId) {
          const yearRows = await firstAvailableSchoolTable(['academic_years', 'school_academic_years'], req.academicAdmin.schoolId, '*');
          if (!yearRows.rows.some(row => String(row.id) === targetAcademicYearId)) return res.status(400).json({ error: 'Choose a valid target academic year.' });
        }
      }
      const { data: previousRequests, error: previousRequestError } = await supabaseAdmin.from('audit_logs')
        .select('id,metadata').eq('school_id', req.academicAdmin.schoolId).eq('action', 'student.lifecycle.requested').eq('entity_id', studentId)
        .order('created_at', { ascending: false }).limit(100);
      if (previousRequestError) throw previousRequestError;
      const previousRequestIds = (previousRequests || []).map((row: any) => String(row.id || '')).filter(Boolean);
      const { data: previousDecisions, error: previousDecisionError } = previousRequestIds.length
        ? await supabaseAdmin.from('audit_logs').select('metadata').eq('school_id', req.academicAdmin.schoolId).eq('action', 'student.lifecycle.decided')
        : { data: [], error: null } as any;
      if (previousDecisionError) throw previousDecisionError;
      const decidedRequestIds = new Set((previousDecisions || []).map((row: any) => String(row.metadata?.request_id || '')).filter(Boolean));
      const duplicatePending = (previousRequests || []).find((row: any) => !decidedRequestIds.has(String(row.id)) && String(row.metadata?.requested_action || '') === requestedAction);
      if (duplicatePending) return res.status(409).json({ error: 'A matching lifecycle request is already pending Headmaster decision.' });

      const { data: requestAudit, error: auditError } = await supabaseAdmin.from('audit_logs').insert({
        actor_user_id: req.academicAdmin.userId,
        actor_kind: 'school_user',
        action: 'student.lifecycle.requested',
        entity_type: 'student',
        entity_id: studentId,
        school_id: req.academicAdmin.schoolId,
        summary: `Clerk requested ${requestedAction.replace(/_/g, ' ')} for ${student.full_name || student.name || studentId}.`,
        before_state: { status: student.status || null, is_active: student.is_active !== false, class_id: student.class_id || null, division_id: student.division_id || null },
        after_state: null,
        metadata: {
          workflow: 'student_lifecycle', request_status: 'pending', requested_action: requestedAction, note,
          target_class_id: targetClassId, target_division_id: targetDivisionId, target_academic_year_id: targetAcademicYearId
        }
      }).select('id').single();
      if (auditError) throw auditError;
      const requestId = String(requestAudit?.id || '');
      return res.json({ success: true, requestId, message: 'Lifecycle request sent to the Headmaster.' });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Student Lifecycle request could not be sent.' });
    }
  });

  app.get('/api/headmaster/student-lifecycle-requests', verifyHeadmasterAuth, requireHeadmasterModule('master_data'), async (req: HeadmasterRequest, res) => {
    if (!supabaseAdmin || !req.authenticatedHeadmaster) return res.status(503).json({ error: 'Student Lifecycle request service is unavailable.' });
    try {
      const schoolId = req.authenticatedHeadmaster.schoolId;
      const { data: requests, error: requestError } = await supabaseAdmin.from('audit_logs').select('*').eq('school_id', schoolId).eq('action', 'student.lifecycle.requested').order('created_at', { ascending: false }).limit(1000);
      if (requestError) throw requestError;
      const { data: decisions, error: decisionError } = await supabaseAdmin.from('audit_logs').select('id,created_at,metadata,summary').eq('school_id', schoolId).eq('action', 'student.lifecycle.decided').order('created_at', { ascending: false }).limit(1000);
      if (decisionError) throw decisionError;
      const decidedIds = new Set((decisions || []).map((row: any) => String(row.metadata?.request_id || '')).filter(Boolean));
      const pending = (requests || []).filter((row: any) => !decidedIds.has(String(row.id)));
      const studentIds = Array.from(new Set(pending.map((row: any) => String(row.entity_id || '')).filter(Boolean)));
      const { data: students, error: studentReadError } = studentIds.length ? await supabaseAdmin.from('students').select('*').eq('school_id', schoolId).in('id', studentIds) : { data: [], error: null } as any;
      if (studentReadError) throw studentReadError;
      const studentMap = new Map((students || []).map((row: any) => [String(row.id), row]));
      return res.json({
        requests: pending.map((row: any) => ({
          id: String(row.id), studentId: String(row.entity_id || ''), createdAt: row.created_at, summary: row.summary,
          requestedAction: String(row.metadata?.requested_action || ''), note: row.metadata?.note || null,
          targetClassId: row.metadata?.target_class_id || null, targetDivisionId: row.metadata?.target_division_id || null,
          targetAcademicYearId: row.metadata?.target_academic_year_id || null, student: studentMap.get(String(row.entity_id || '')) || null
        }))
      });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Student Lifecycle requests could not be loaded.' });
    }
  });

  app.post('/api/headmaster/student-lifecycle-requests/:requestId/decision', verifyHeadmasterAuth, requireHeadmasterModule('master_data'), async (req: HeadmasterRequest, res) => {
    if (!supabaseAdmin || !req.authenticatedHeadmaster) return res.status(503).json({ error: 'Student Lifecycle request service is unavailable.' });
    try {
      const requestId = safePublicText(req.params.requestId, 100);
      const decision = safePublicText(req.body?.decision, 20).toLowerCase();
      if (!['approve', 'reject'].includes(decision)) return res.status(400).json({ error: 'Decision must be approve or reject.' });
      const schoolId = req.authenticatedHeadmaster.schoolId;
      const { data: requestRow, error: requestError } = await supabaseAdmin.from('audit_logs').select('*').eq('id', requestId).eq('school_id', schoolId).eq('action', 'student.lifecycle.requested').maybeSingle();
      if (requestError) throw requestError;
      if (!requestRow) return res.status(404).json({ error: 'Lifecycle request was not found.' });
      const { data: existingDecision } = await supabaseAdmin.from('audit_logs').select('id').eq('school_id', schoolId).eq('action', 'student.lifecycle.decided').contains('metadata', { request_id: requestId }).maybeSingle();
      if (existingDecision) return res.status(409).json({ error: 'This lifecycle request has already been decided.' });
      const studentId = String(requestRow.entity_id || '');
      const { data: student, error: studentError } = await supabaseAdmin.from('students').select('*').eq('id', studentId).eq('school_id', schoolId).maybeSingle();
      if (studentError) throw studentError;
      if (!student) return res.status(404).json({ error: 'Student record was not found.' });
      const requestedAction = String(requestRow.metadata?.requested_action || '');
      const statusByAction: Record<string, string> = { school_transfer: 'Transferred', passout: 'Passout', leaving: 'Leaving', archive: 'Archived' };
      const lifecycleStatus = decision === 'approve' ? (statusByAction[requestedAction] || null) : null;
      let updatedStudent: any = student;
      let appliedPatch: Record<string, any> = {};
      if (decision === 'approve' && requestedAction !== 'promotion_preparation') {
        const patch: Record<string, any> = {};
        const has = (column: string) => Object.prototype.hasOwnProperty.call(student, column);
        if (requestedAction === 'class_transfer') {
          const classId = safePublicText(requestRow.metadata?.target_class_id, 100) || null;
          const divisionId = safePublicText(requestRow.metadata?.target_division_id, 100) || null;
          if (!classId) return res.status(400).json({ error: 'Class transfer request has no target class.' });
          const classRows = await firstAvailableSchoolTable(['school_classes', 'classes'], schoolId, '*');
          if (!classRows.rows.some(row => String(row.id) === classId)) return res.status(400).json({ error: 'Target class is no longer valid.' });
          if (divisionId) {
            const divisionRows = await firstAvailableSchoolTable(['school_divisions', 'divisions'], schoolId, '*');
            const targetDivision = divisionRows.rows.find(row => String(row.id) === divisionId);
            if (!targetDivision) return res.status(400).json({ error: 'Target division is no longer valid.' });
            if (targetDivision.class_id && String(targetDivision.class_id) !== classId) return res.status(400).json({ error: 'Target division no longer belongs to the requested class.' });
          }
          const targetAcademicYearId = safePublicText(requestRow.metadata?.target_academic_year_id, 100) || null;
          if (targetAcademicYearId) {
            const yearRows = await firstAvailableSchoolTable(['academic_years', 'school_academic_years'], schoolId, '*');
            if (!yearRows.rows.some(row => String(row.id) === targetAcademicYearId)) return res.status(400).json({ error: 'Target academic year is no longer valid.' });
          }
          if (has('class_id')) patch.class_id = classId;
          if (has('division_id')) patch.division_id = divisionId;
          else if (has('division')) {
            const divisionRows = divisionId ? await firstAvailableSchoolTable(['school_divisions', 'divisions'], schoolId, '*') : { rows: [] } as any;
            const targetDivision = divisionRows.rows.find((row: any) => String(row.id) === divisionId);
            patch.division = targetDivision ? String(targetDivision.division_name || targetDivision.name || '') || null : null;
          }
          if (has('academic_year_id') && targetAcademicYearId) patch.academic_year_id = targetAcademicYearId;
        } else {
          if (!lifecycleStatus) return res.status(400).json({ error: 'Unsupported lifecycle action.' });
          if (has('status')) patch.status = lifecycleStatus;
          if (has('is_active')) patch.is_active = false;
        }
        if (has('updated_at')) patch.updated_at = new Date().toISOString();
        if (Object.keys(patch).length) {
          const { data, error } = await supabaseAdmin.from('students').update(patch).eq('id', studentId).eq('school_id', schoolId).select('*').single();
          if (error) throw error;
          updatedStudent = data;
          appliedPatch = patch;
        }
      }
      const auditAfterState = decision === 'approve' && lifecycleStatus ? { ...updatedStudent, lifecycle_status: lifecycleStatus } : (decision === 'approve' ? updatedStudent : student);
      const { error: auditError } = await supabaseAdmin.from('audit_logs').insert({
        actor_user_id: req.authenticatedHeadmaster.userId, actor_kind: 'school_user', action: 'student.lifecycle.decided', entity_type: 'student', entity_id: studentId, school_id: schoolId,
        summary: `Headmaster ${decision === 'approve' ? 'approved' : 'rejected'} Clerk lifecycle request: ${requestedAction.replace(/_/g, ' ')}.`,
        before_state: student, after_state: auditAfterState,
        metadata: {
          workflow: 'student_lifecycle', request_id: requestId, decision, requested_action: requestedAction,
          lifecycle_status: lifecycleStatus,
          note: safePublicText(req.body?.note, 1200) || requestRow.metadata?.note || null
        }
      });
      if (auditError) {
        if (decision === 'approve' && Object.keys(appliedPatch).length) {
          const rollback: Record<string, any> = {};
          for (const key of Object.keys(appliedPatch)) {
            if (key === 'updated_at') continue;
            if (Object.prototype.hasOwnProperty.call(student, key)) rollback[key] = student[key];
          }
          if (Object.prototype.hasOwnProperty.call(student, 'updated_at')) rollback.updated_at = student.updated_at || new Date().toISOString();
          const rollbackResult = Object.keys(rollback).length
            ? await supabaseAdmin.from('students').update(rollback).eq('id', studentId).eq('school_id', schoolId)
            : { error: null } as any;
          if (rollbackResult.error) console.error('Lifecycle decision audit failed and Student rollback could not be verified.', rollbackResult.error);
        }
        return res.status(500).json({ error: 'Lifecycle decision was not committed because the mandatory audit trail could not be written.' });
      }
      return res.json({ success: true, decision, promotionHandoff: decision === 'approve' && requestedAction === 'promotion_preparation', student: lifecycleStatus ? { ...updatedStudent, status: lifecycleStatus } : updatedStudent });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Lifecycle request decision could not be saved.' });
    }
  });

  app.get('/api/headmaster/student-directory/:studentId/documents', verifyAcademicAdminAuth, requireAcademicAdminModule('master_data'), async (req: AcademicAdminRequest, res) => {
    if (!supabaseAdmin || !req.academicAdmin) return res.status(503).json({ error: 'Student document index is unavailable.' });
    if (!['headmaster', 'clerk'].includes(req.academicAdmin.role)) return res.status(403).json({ error: 'Student Document Index access is limited to authorized school administration.' });
    try {
      const studentId = safePublicText(req.params.studentId, 100);
      const events = await headmasterReadRows('school_admission_application_events', req.academicAdmin.schoolId, '*', query => query.eq('event_type', 'admission_confirmed').order('created_at', { ascending: false }).limit(2000));
      const event = events.rows.find(row => String(row.event_payload?.studentId || row.event_payload?.student_id || '') === studentId);
      if (!event?.application_id) return res.json({ documents: [] });
      const { data: rows, error } = await supabaseAdmin.from('school_admission_application_documents').select('*').eq('school_id', req.academicAdmin.schoolId).eq('application_id', event.application_id).order('created_at');
      if (error) throw error;
      const documents: any[] = [];
      for (const row of rows || []) {
        const signed = row.storage_bucket && row.storage_path
          ? await supabaseAdmin.storage.from(row.storage_bucket).createSignedUrl(row.storage_path, 15 * 60)
          : { data: null } as any;
        documents.push({
          id: String(row.id),
          type: String(row.document_type || 'document'),
          fileName: String(row.original_filename || row.file_name || 'Document'),
          status: String(row.verification_status || 'received'),
          previewUrl: signed.data?.signedUrl || null,
          createdAt: row.created_at || null
        });
      }
      return res.json({ documents });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Student document index could not be loaded.' });
    }
  });

