  app.post('/api/school-website/media/upload', verifyAcademicAdminAuth, requireAcademicAdminModule('school_setup'), async (req: AcademicAdminRequest, res) => {
    if (!req.academicAdmin || req.academicAdmin.role !== 'clerk') return res.status(403).json({ error: 'This Website Design / Campaign Setup action is Clerk-only.' });
    if (!supabaseAdmin || !req.academicAdmin) return res.status(503).json({ error: 'School media service is unavailable.' });
    let uploadedObjectPath: string | null = null;
    try {
      const kind = String(req.body?.kind || '').trim().toLowerCase();
      if (!['hero', 'gallery', 'logo', 'admission_campaign', 'document'].includes(kind)) return res.status(400).json({ error: 'Choose a valid school media type.' });
      const dataUrl = String(req.body?.dataUrl || '').trim();
      const match = dataUrl.match(/^data:(image\/(?:jpeg|png|webp)|application\/pdf);base64,([A-Za-z0-9+/=]+)$/);
      if (!match) return res.status(400).json({ error: 'Choose a valid JPG, PNG, WEBP or PDF file.' });
      const mimeType = match[1];
      const buffer = Buffer.from(match[2], 'base64');
      const maxBytes = kind === 'document' ? 8 * 1024 * 1024 : kind === 'hero' || kind === 'admission_campaign' ? 5 * 1024 * 1024 : 4 * 1024 * 1024;
      if (!buffer.length || buffer.length > maxBytes) {
        return res.status(413).json({ error: kind === 'document' ? 'Document must be 8 MB or smaller.' : kind === 'hero' || kind === 'admission_campaign' ? 'Optimized banner must be 5 MB or smaller.' : 'Optimized image must be 4 MB or smaller.' });
      }
      await ensureSchoolMediaBuckets();

      const checksum = createHash('sha256').update(buffer).digest('hex');
      const { data: duplicate, error: duplicateError } = await supabaseAdmin
        .from('school_media_assets')
        .select('*')
        .eq('school_id', req.academicAdmin.schoolId)
        .eq('asset_kind', kind)
        .eq('checksum_sha256', checksum)
        .in('status', ['draft', 'published'])
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle();
      if (duplicateError && duplicateError.code !== 'PGRST116') throw duplicateError;
      if (duplicate) {
        const shaped = schoolMediaAssetShape(duplicate, await schoolMediaPreviewUrl(duplicate));
        return res.json({ success: true, duplicate: true, asset: shaped, reference: shaped.reference });
      }

      const extension = mimeType === 'application/pdf' ? 'pdf' : mimeType === 'image/png' ? 'png' : mimeType === 'image/jpeg' ? 'jpg' : 'webp';
      const safeStem = String(req.body?.fileName || kind)
        .replace(/\.[^.]+$/, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 50) || kind;
      const now = new Date();
      const year = String(now.getUTCFullYear());
      const month = String(now.getUTCMonth() + 1).padStart(2, '0');
      const storageFilename = `${Date.now()}-${randomBytes(6).toString('hex')}-${safeStem}.${extension}`;
      uploadedObjectPath = `${req.academicAdmin.schoolId}/${kind}/${year}/${month}/${storageFilename}`;
      const { error: uploadError } = await supabaseAdmin.storage
        .from(SCHOOL_MEDIA_PRIVATE_BUCKET)
        .upload(uploadedObjectPath, buffer, { contentType: mimeType, upsert: false, cacheControl: '3600' });
      if (uploadError) throw uploadError;

      const width = Number(req.body?.width);
      const height = Number(req.body?.height);
      const defaultCategory = kind === 'hero' ? 'homepage-banner' : kind === 'logo' ? 'school-identity' : kind === 'admission_campaign' ? 'admission-campaign' : kind === 'document' ? 'school-document' : 'school-gallery';
      const { data: row, error: insertError } = await supabaseAdmin.from('school_media_assets').insert({
        school_id: req.academicAdmin.schoolId,
        asset_kind: kind,
        category: safePublicText(req.body?.category, 80) || defaultCategory,
        status: 'draft',
        private_bucket: SCHOOL_MEDIA_PRIVATE_BUCKET,
        private_path: uploadedObjectPath,
        original_filename: safePublicText(req.body?.fileName, 220) || storageFilename,
        storage_filename: storageFilename,
        mime_type: mimeType,
        size_bytes: buffer.length,
        width_px: Number.isFinite(width) && width > 0 ? Math.round(width) : null,
        height_px: Number.isFinite(height) && height > 0 ? Math.round(height) : null,
        checksum_sha256: checksum,
        caption: safePublicText(req.body?.caption, 500) || null,
        alt_text: safePublicText(req.body?.altText, 500) || null,
        created_by_user_id: req.academicAdmin.userId,
        updated_by_user_id: req.academicAdmin.userId,
        metadata: { optimizedBy: mimeType === 'application/pdf' ? 'Classtago secure file pipeline' : 'Classtago client image pipeline', originalMimeType: safePublicText(req.body?.originalMimeType, 100) || null }
      }).select('*').single();
      if (insertError) throw insertError;
      await recordSchoolMediaEvent(req.academicAdmin.schoolId, String(row.id), 'uploaded', req.academicAdmin.userId, { kind, checksum });
      const asset = schoolMediaAssetShape(row, await schoolMediaPreviewUrl(row));
      return res.json({ success: true, asset, reference: asset.reference });
    } catch (error: any) {
      if (uploadedObjectPath && supabaseAdmin) {
        await supabaseAdmin.storage.from(SCHOOL_MEDIA_PRIVATE_BUCKET).remove([uploadedObjectPath]).catch(() => undefined);
      }
      console.error('School media upload error:', error?.message || error);
      return res.status(500).json({ error: error?.message || 'School media could not be uploaded.' });
    }
  });

