  app.put('/api/push/native/tokens', verifyActiveUserAuth, async (req: ActiveUserRequest, res) => {
    res.setHeader('Cache-Control','no-store');
    if (!req.activeUser || !supabaseAdmin) return res.status(503).json({error:'Native push registration is unavailable.'});
    try {
      const token=safePublicText(req.body?.token,5000);
      const platform=safePublicText(req.body?.platform,20).toLowerCase();
      if (!token || platform !== 'android') return res.status(400).json({error:'A valid Android push token is required.'});
      const tokenHash=createHash('sha256').update(token).digest('hex');
      const now=new Date().toISOString();
      const saved=await supabaseAdmin.from('edunixo_native_push_tokens').upsert({
        school_id:req.activeUser.schoolId,user_id:req.activeUser.userId,platform:'android',token,token_hash:tokenHash,
        device_model:safePublicText(req.body?.deviceModel,1000)||null,active:true,last_seen_at:now,updated_at:now
      },{onConflict:'token_hash'}).select('id').single();
      if(saved.error) throw saved.error;
      return res.json({success:true});
    } catch(error:any){ return res.status(500).json({error:error?.message||'Native push token could not be saved.'}); }
  });

  app.delete('/api/push/native/tokens', verifyActiveUserAuth, async (req: ActiveUserRequest, res) => {
    res.setHeader('Cache-Control','no-store');
    if (!req.activeUser || !supabaseAdmin) return res.status(503).json({error:'Native push registration is unavailable.'});
    try {
      const token=safePublicText(req.body?.token,5000);
      if(!token) return res.status(400).json({error:'Push token is required.'});
      const tokenHash=createHash('sha256').update(token).digest('hex');
      const result=await supabaseAdmin.from('edunixo_native_push_tokens').update({active:false,updated_at:new Date().toISOString()})
        .eq('school_id',req.activeUser.schoolId).eq('user_id',req.activeUser.userId).eq('token_hash',tokenHash);
      if(result.error) throw result.error;
      return res.json({success:true});
    } catch(error:any){ return res.status(500).json({error:error?.message||'Native push token could not be disabled.'}); }
  });

