  app.post('/api/platform/institution-leads/:leadId/follow-up', verifyPlatformAdminAuth, async (req: PlatformAdminRequest, res) => {
    if (!supabaseAdmin || !req.platformAdmin) return res.status(503).json({ error: 'Platform lead service is unavailable.' });
    try {
      const leadId = safePublicText(req.params.leadId, 120);
      const status = safePublicText(req.body?.status, 30).toLowerCase();
      const note = safePublicText(req.body?.note, 3000);
      const nextRaw = safePublicText(req.body?.nextFollowUpAt, 80);
      const allowed = new Set(['new', 'contacted', 'follow_up', 'qualified', 'converted', 'closed']);
      if (!leadId) return res.status(400).json({ error: 'Lead id is required.' });
      if (!allowed.has(status)) return res.status(400).json({ error: 'Choose a valid follow-up status.' });
      let nextFollowUpAt: string | null = null;
      if (nextRaw) {
        const parsed = new Date(nextRaw);
        if (Number.isNaN(parsed.getTime())) return res.status(400).json({ error: 'Next follow-up date/time is invalid.' });
        nextFollowUpAt = parsed.toISOString();
      }
      const now = new Date().toISOString();
      const { data, error } = await supabaseAdmin.from('platform_institution_leads')
        .update({
          status,
          last_follow_up_note: note || null,
          last_follow_up_at: now,
          next_follow_up_at: status === 'closed' || status === 'converted' ? null : nextFollowUpAt,
          updated_by: req.platformAdmin.userId,
          updated_at: now
        })
        .eq('id', leadId)
        .select('id,reference_code,status,last_follow_up_note,last_follow_up_at,next_follow_up_at,updated_at')
        .maybeSingle();
      if (error) throw error;
      if (!data?.id) return res.status(404).json({ error: 'Demo lead was not found.' });
      return res.json({ success: true, lead: {
        id: String(data.id), referenceCode: data.reference_code, status: data.status,
        lastFollowUpNote: data.last_follow_up_note || null, lastFollowUpAt: data.last_follow_up_at || null,
        nextFollowUpAt: data.next_follow_up_at || null, updatedAt: data.updated_at || null
      }});
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Follow-up could not be saved.' });
    }
  });

