      const recordId=String(req.params.recordId||'').trim();
      const targetAssignmentId=String(req.body?.targetAssignmentId||'').trim();
      if(!recordId||!targetAssignmentId) return res.status(400).json({error:'Source record and target assigned scope are required.'});
      const source=await supabaseAdmin.from('edunixo_academic_records').select('*').eq('id',recordId).eq('owner_teacher_id',req.activeUser.userId).maybeSingle();
      if(source.error)throw source.error;if(!source.data)return res.status(404).json({error:'Source Academic record was not found for the current Teacher.'});
      if(String(source.data.kind)==='homework')return res.status(400).json({error:'Homework copy is handled by the dedicated Homework save flow.'});
      const {comm,scope}=await resolveTeacherAcademicServerScope(req.activeUser,targetAssignmentId);
      const payload=teacherAcademicRecordPayload(req.activeUser,comm,scope,{assignmentId:targetAssignmentId,kind:String(source.data.kind),title:String(source.data.title||''),status:String(source.data.status||'draft'),content:String(source.data.content||''),metadata:{...(source.data.metadata||{}),copiedFromRecordId:recordId}});
      const copied=await supabaseAdmin.from('edunixo_academic_records').insert({...payload,created_at:new Date().toISOString()}).select('id').single();
      if(copied.error)throw copied.error;
