      if(textbookRead.error)throw textbookRead.error;
      const materials:any[]=(textbookRead.data||[]).filter((m:any)=>String(m.extraction_status)==='ready'&&(String(m.subject_id||'')&&String(scope.subjectId||'')?String(m.subject_id)===String(scope.subjectId):norm(m.subject_name)===norm(scope.subjectName))&&(String(m.class_id||'')&&String(scope.classId||'')?String(m.class_id)===String(scope.classId):norm(m.class_name)===norm(scope.className))).slice(0,6);
      if(!materials.length)return res.status(409).json({engineBuild:'R33.8',error:`Textbook is not AI-ready for ${String(scope.subjectName||'this Subject')}.`});
      const metas:HomeworkFileMeta[]=[];for(const material of materials){const id=String(material.id),meta=await readHomeworkFileMeta(material);if(!meta){const warmError=homeworkFileWarmErrors.get(id);if(warmError)throw new Error(warmError);if(!homeworkFileWarmJobs.has(id))void scheduleHomeworkFileCache(material);return res.status(425).json({engineBuild:'R33.8',sourcePreparing:true,error:`Classtago is preparing the ${String(scope.subjectName||'Subject')} Textbook for Year Plan.`});}metas.push(meta);}
      const chapterRead=await supabaseAdmin.from('edunixo_study_material_segments').select('material_id,segment_no,chapter').in('material_id',materials.map((m:any)=>String(m.id))).gt('segment_no',0).not('chapter','is',null).order('material_id').order('segment_no').limit(2000);if(chapterRead.error)throw chapterRead.error;
      const chapterOrder:string[]=[];for(const row of chapterRead.data||[]){const label=String(row.chapter||'').trim();if(label&&!chapterOrder.some(x=>x.toLocaleLowerCase()===label.toLocaleLowerCase()))chapterOrder.push(label);}
      const activeYear=await supabaseAdmin.from('school_academic_years').select('id,year_code,starts_on,ends_on').eq('school_id',req.activeUser.schoolId).eq('is_active',true).limit(1).maybeSingle();const yearId=String((activeYear.data as any)?.id||scope.academicYearId||'');
      const [termsRead,holidaysRead,allocationRead]=await Promise.all([yearId?supabaseAdmin.from('school_academic_terms').select('term_name,starts_on,ends_on').eq('school_id',req.activeUser.schoolId).eq('academic_year_id',yearId).eq('is_active',true).order('sort_order'):Promise.resolve({data:[],error:null} as any),yearId?supabaseAdmin.from('school_holidays').select('holiday_name,starts_on,ends_on').eq('school_id',req.activeUser.schoolId).eq('academic_year_id',yearId).order('starts_on'):Promise.resolve({data:[],error:null} as any),supabaseAdmin.from('school_subject_teacher_assignments').select('weekly_periods').eq('school_id',req.activeUser.schoolId).eq('id',String(scope.assignmentId||assignmentId)).maybeSingle()]);
