  app.get('/api/teacher/academic/materials', verifyActiveUserAuth, async (req: ActiveUserRequest, res) => {
    if (!req.activeUser || !supabaseAdmin) return res.status(503).json({ error: 'Study Material service is unavailable.' });
    if (!['teacher','class_teacher','headmaster'].includes(req.activeUser.role)) return res.status(403).json({ error: 'Assigned Subject Teacher access is required.' });
    try {
      const result = await supabaseAdmin.from('edunixo_study_materials').select('*')
        .eq('school_id', req.activeUser.schoolId).eq('owner_teacher_id', req.activeUser.userId).eq('archived', false)
        .order('created_at', { ascending:false }).limit(1000);
      if (result.error) {
        const msg=String(result.error.message||'');
        if (/does not exist|schema cache|could not find|relation .* does not exist/i.test(msg)) return res.json({ materials:[], backendReady:false, error:'Teacher Academic Core is not installed yet. Run Classtago R27 Academic Core setup once.' });
        throw result.error;
      }
      const materials=(result.data||[]).map((row:any)=>({
        id:String(row.id), ownerTeacherId:String(row.owner_teacher_id||''), schoolId:String(row.school_id||''),
        academicYear:String(row.academic_year||''), className:String(row.class_name||''), division:String(row.division_name||row.division||'')||undefined,
        subjectId:String(row.subject_id||''), subjectName:String(row.subject_name||''), chapter:String(row.chapter||'')||undefined, unit:String(row.unit||'')||undefined,
        medium:String(row.medium||'School Medium'), title:String(row.title||'Study Material'), kind:String(row.kind||'notes'),
        category:String(row.category||'pdf_material'),
        sourceUrl:String(row.source_url||'')||undefined, storagePath:String(row.storage_path||'')||undefined,
        publishedToStudents:Boolean(row.published_to_students), archived:Boolean(row.archived), extractionStatus:String(row.extraction_status||'pending'), extractionError:String(row.extraction_error||'')||undefined, createdAt:String(row.created_at||'')
      }));
      // R33.2: do not pre-index every book in the school. File Search Free Tier
      // storage is a cache, so only the Teacher's currently selected Homework
      // Textbook is warmed by the Homework page itself.
      return res.json({ materials, backendReady:true });
    } catch (error:any) { return res.status(500).json({ error:error?.message || 'Study Material could not be loaded.' }); }
  });

