  // ---------------------------------------------------------------------------
  app.post(['/api/teacher/academic/generate-homework','/api/teacher/academic/generate-homework-r33-6'], verifyActiveUserAuth, async (req: ActiveUserRequest, res) => {
    res.setHeader('Cache-Control','no-store, no-cache, must-revalidate, proxy-revalidate');
    res.setHeader('Pragma','no-cache');
    res.setHeader('X-EDUNIXO-AI-Build','R33.6');
    if (!req.activeUser || !supabaseAdmin) return res.status(503).json({ error: 'AI Homework service is unavailable.' });
    if (!['teacher','class_teacher','headmaster'].includes(req.activeUser.role)) return res.status(403).json({ error: 'Assigned Subject Teacher access is required.' });
    if (!geminiApiKey || !ai) return res.status(503).json({ error: 'School AI service is not ready in this Preview yet. Restart Preview after AI service setup, then retry.' });

    try {
      const assignmentId = String(req.body?.assignmentId || '').trim();
      const requestedMaterialIds = [...new Set((Array.isArray(req.body?.materialIds) ? req.body.materialIds : []).map((v:any)=>String(v||'').trim()).filter(Boolean))].slice(0, 30); // compatibility only; server re-resolves Textbook source
      const chapterScope = [...new Set((Array.isArray(req.body?.chapterScope) ? req.body.chapterScope : []).map((v:any)=>String(v||'').trim()).filter(Boolean))].slice(0, 30);
      const structured = req.body?.structuredInputs && typeof req.body.structuredInputs === 'object' ? req.body.structuredInputs : {};
      const teacherInstruction = String(req.body?.prompt || '').trim().slice(0, 3000);
      if (!assignmentId) return res.status(400).json({ error: 'Select an assigned Class / Division / Subject.' });

      const comm = await loadTeacherCommunicationScopes(req.activeUser);
      const subjectScopes = (comm.scopes || []).filter((scope:any)=>scope.scopeType === 'subject');
      let scope:any = subjectScopes.find((row:any)=>String(row.assignmentId) === assignmentId || String(row.id) === assignmentId || String(row.id) === `subject:${assignmentId}`);

      // Compatibility fallback: older Teacher Academic rows may use their own
      // projection assignment id. It is accepted only if it belongs to this login
      // and can be matched back to a current canonical Subject Teacher scope.
      let projection:any = null;
      if (!scope) {
        const projectionRead = await supabaseAdmin.from('edunixo_teacher_assignments').select('*').eq('id', assignmentId).eq('teacher_id', req.activeUser.userId).eq('school_id', req.activeUser.schoolId).eq('active', true).maybeSingle();
        if (!projectionRead.error && projectionRead.data) {
          projection = projectionRead.data;
          const norm = (v:any)=>String(v||'').trim().toLowerCase().replace(/^class\s+/,'').replace(/\s+/g,' ');
          scope = subjectScopes.find((row:any)=>
            (String(row.subjectId||'') === String(projection.subject_id||'') || norm(row.subjectName) === norm(projection.subject_name)) &&
            (String(row.classId||'') === String(projection.class_id||'') || norm(row.className) === norm(projection.class_name)) &&
            (!row.divisionId || !projection.division_id || String(row.divisionId) === String(projection.division_id) || norm(row.division) === norm(projection.division))
          );
        }
      }
      if (!scope) return res.status(403).json({ error: 'This AI Homework scope is not part of your current Headmaster-assigned Subject Teacher mapping.' });

      // R29: Homework source is server-owned and automatic. Client material IDs are never trusted
      // to choose the source. Only this Teacher's Textbook category for the selected Class + Subject is eligible.
      const textbookRead = await supabaseAdmin.from('edunixo_study_materials')
        .select('id,title,chapter,unit,extraction_status,assignment_id,owner_teacher_id,school_id,class_id,class_name,division,subject_id,subject_name,medium,category,kind,storage_path,source_url')
        .eq('owner_teacher_id', req.activeUser.userId).eq('school_id', req.activeUser.schoolId).eq('category','textbook').eq('archived', false)
        .order('created_at',{ascending:true}).limit(100);
      if (textbookRead.error) throw textbookRead.error;
      const norm = (v:any)=>String(v||'').trim().toLowerCase().replace(/^class\s+/,'').replace(/\s+/g,' ');
      const allTextbooks:any[] = (textbookRead.data || []).filter((m:any)=>
        (String(m.subject_id||'') && String(scope.subjectId||'') ? String(m.subject_id)===String(scope.subjectId) : norm(m.subject_name)===norm(scope.subjectName)) &&
        (String(m.class_id||'') && String(scope.classId||'') ? String(m.class_id)===String(scope.classId) : norm(m.class_name)===norm(scope.className))
      );
      if (!allTextbooks.length) return res.status(409).json({ error: 'Textbook not uploaded for this subject. Open Study Material → Class → Subject → Textbook and upload it first.' });
      const materials:any[] = allTextbooks.filter((m:any)=>String(m.extraction_status)==='ready');
      if (!materials.length) return res.status(409).json({ error: 'Textbook is uploaded but its chapter list is not ready yet. Open Study Material and use Prepare chapters now, then generate Homework.' });
      const materialIds = materials.map((m:any)=>String(m.id));

      const warnings:string[] = [];
      const sections = (Array.isArray(structured.homeworkSections) ? structured.homeworkSections : [])
        .map((row:any)=>({ label:String(row?.label||row?.key||'').trim().slice(0,100), count:Math.max(1,Math.min(30,Number(row?.count)||1)) }))
        .filter((row:any)=>row.label).slice(0, 12);
      if (!sections.length) return res.status(400).json({ error: 'Select at least one Homework section type.' });
      const outputLanguage = String(structured.outputLanguage || scope.medium || 'School Medium').trim().slice(0,80);
      const difficulty = String(structured.difficulty || 'Balanced').trim().slice(0,40);
      const targetMinutes = Math.max(5, Math.min(180, Number(structured.targetMinutes) || 30));
      const dueDate = String(structured.dueDate || '').trim().slice(0,20);
      const sectionInstruction = sections.map((row:any,index:number)=>`${index+1}. ${row.label}: exactly ${row.count} item(s)`).join('\n');
      const systemInstruction = `You are Classtago's AI Homework Builder. Generate school-ready Homework using ONLY the authorized Teacher Textbook source(s) supplied through Classtago for the selected Class + Subject. Never use Videos, Images, extra PDF Material, Notes, Worksheets, Links, browsing, outside facts, or invented textbook content. Scope: ${scope.className}${scope.division && scope.division !== 'All' ? `-${scope.division}` : ''}, ${scope.subjectName}. Output language: ${outputLanguage}. Difficulty: ${difficulty}. Target completion time: about ${targetMinutes} minutes. Requested chapters: ${chapterScope.length ? chapterScope.join(', ') : 'whole textbook'}. Follow the requested section types and quantities exactly. LANGUAGE & SCRIPT RULES: write all student-facing content in the native Unicode script and natural grammar/punctuation of the requested language; never Romanize/transliterate unless the Teacher explicitly asks. If Output language is a generic School Medium label, infer the textbook's dominant language/script and use it consistently. Urdu/Kashmiri/Sindhi output must be natural right-to-left Nastaliq-friendly text, with native sentence flow and punctuation; avoid ASCII hyphen bullets that visually break RTL lines. For Hindi/Marathi/Devanagari, Bengali/Assamese, Gujarati, Gurmukhi, Kannada, Malayalam, Odia, Tamil, Telugu, Meetei Mayek and Ol Chiki, keep the correct native script rather than Latin transliteration. Do not include answer keys unless the Teacher explicitly asks for them. Classtago renders the document heading, Class, Subject, Chapter, Homework Date and Due Date separately, so do not repeat those metadata lines inside content. Write section headings in the requested language/script; avoid unnecessary English labels or Roman transliteration except unavoidable proper nouns/standard abbreviations. If the requested chapter/content cannot be found in the textbook, say so briefly instead of inventing. Return ONLY the final student-ready Homework text. Do not wrap it in JSON, Markdown code fences, explanations, metadata, answer keys, or developer commentary.`;
      const retrievalFocus = chapterScope.length
        ? `RETRIEVAL TARGET: Retrieve content ONLY from these selected Textbook chapters/lessons and their directly associated examples/exercises: ${chapterScope.join(', ')}. Do not retrieve or summarize unrelated chapters. Retrieve just enough grounded context to create the requested Homework.`
        : 'RETRIEVAL TARGET: Use the relevant Textbook chunks needed for the requested Homework. Do not summarize or re-read the entire book when a smaller relevant context is sufficient.';
      const prompt = `HOMEWORK SECTIONS\n${sectionInstruction}\n\nHomework date: ${String(structured.date||'')}\nDue date: ${dueDate}\nTeacher instruction: ${teacherInstruction || 'None — generate automatically.'}\n\n${retrievalFocus}`;

      let raw='';
      let generationMethod='file_search_or_files_cache';
      const activeMaterials=materials.slice(0,6);

      // R33.40 fast path: a persistent File Search store is queried first. This
      // avoids attaching the full Textbook PDF to each Homework generation. The
      // short wait only gives a background accelerator a chance to finish; it
      // never turns into a long Teacher-facing loading screen.
      const acceleratorMetas=await Promise.all(activeMaterials.map(material=>getHomeworkAccelerator(material,900)));
      const acceleratorsReady=acceleratorMetas.length===activeMaterials.length&&acceleratorMetas.every(Boolean);
      if(acceleratorsReady){
        const storeNames=acceleratorMetas.map(meta=>String(meta!.storeName));
        let searchError:any=null;
        try{
          const result=await runFileSearchHomeworkInteraction(storeNames,{model:geminiGenerationModel,prompt,systemInstruction,maxOutputTokens:8192,timeoutMs:30000});
          raw=normalizeHomeworkText(result?.text||'');
          if(raw)generationMethod=`file_search:${geminiGenerationModel}:chapter_first`;
        }catch(error:any){
          searchError=error;
          console.warn('R33.40 Homework File Search fast path unavailable; using cached-file fallback:',String(error?.message||error||''));
          if(fileSearchStoreMissingError(error))await invalidateFileSearchAccelerators(activeMaterials);
        }
        // One independent Free Tier model fallback is still cheaper than sending
        // the whole PDF again, but do not retry File Search repeatedly.
        if(!raw&&searchError&&transientAiError(searchError)){
          try{
            const result=await runFileSearchHomeworkInteraction(storeNames,{model:geminiSecondaryModel,prompt,systemInstruction,maxOutputTokens:9000,timeoutMs:30000});
            raw=normalizeHomeworkText(result?.text||'');
            if(raw)generationMethod=`file_search:${geminiSecondaryModel}:chapter_first_fallback`;
          }catch(error:any){
            console.warn('R33.40 Homework File Search secondary unavailable; using cached-file fallback:',String(error?.message||error||''));
            if(fileSearchStoreMissingError(error))await invalidateFileSearchAccelerators(activeMaterials);
          }
        }
      }

      // Safe fallback: reuse the existing temporary provider file cache. This is
      // required for >100 MB source PDFs and protects current working behavior if
      // File Search is unavailable. No original R2/Supabase textbook is changed.
      let primaryError:any=null;
      if(!raw){
        const usableMetas:HomeworkFileMeta[]=[];
        for(const material of activeMaterials){
          const id=String(material.id);
          const meta=await readHomeworkFileMeta(material);
          if(!meta){
            const warmError=homeworkFileWarmErrors.get(id);
            if(warmError&&!fileSearchWarmJobs.has(id))throw new Error(warmError);
            if(!homeworkFileWarmJobs.has(id))void scheduleHomeworkFileCache(material);
            void scheduleFileSearchAccelerator(material);
            return res.status(425).json({engineBuild:'R33.6',speedBuild:'R33.40',stage:'textbook_preparation',sourcePreparing:true,error:'Classtago is preparing a fast Textbook source once. Generation will retry automatically when either chapter retrieval or the safe PDF cache is ready.'});
          }
          usableMetas.push(meta);
        }

        try{
          raw=normalizeHomeworkText(await withTransientAiRetry(
            'R33.40 cached Textbook Homework primary',
            ()=>generateHomeworkFromCachedFiles(usableMetas,{model:geminiGenerationModel,prompt,systemInstruction,maxOutputTokens:8192}),
            2
          ));
          if(raw)generationMethod=`files_cache:${geminiGenerationModel}:fallback`;
        }catch(error:any){
          primaryError=error;
          console.warn('R33.40 cached Textbook primary unavailable:',String(error?.message||error||''));
        }

        if(!raw&&primaryError&&providerFileMissingError(primaryError)){
          for(const material of activeMaterials){
            await removeHomeworkFileMeta(String(material.id));
            void scheduleHomeworkFileCache(material);
          }
          return res.status(425).json({engineBuild:'R33.6',speedBuild:'R33.40',stage:'textbook_refresh',sourcePreparing:true,error:'The temporary AI copy of this Textbook expired. Classtago is refreshing it automatically.'});
        }

        if(!raw){
          try{
            raw=normalizeHomeworkText(await withTransientAiRetry(
              'R33.40 cached Textbook Homework secondary',
              ()=>generateHomeworkFromCachedFiles(usableMetas,{model:geminiSecondaryModel,prompt,systemInstruction,maxOutputTokens:10000}),
              2
            ));
            if(raw)generationMethod=`files_cache:${geminiSecondaryModel}:fallback`;
          }catch(error:any){
            if(providerFileMissingError(error)){
              for(const material of activeMaterials){
                await removeHomeworkFileMeta(String(material.id));
                void scheduleHomeworkFileCache(material);
              }
              return res.status(425).json({engineBuild:'R33.6',speedBuild:'R33.40',stage:'textbook_refresh',sourcePreparing:true,error:'The temporary AI copy of this Textbook expired. Classtago is refreshing it automatically.'});
            }
            if(primaryError)console.warn('R33.40 cached primary diagnostic:',String(primaryError?.message||primaryError||''));
            throw error;
          }
        }
      }

      if(!raw&&primaryError)throw primaryError;
      if (!raw) throw new Error('Gemini returned an empty Homework response.');
      const content = normalizeHomeworkText(raw);
      if (!content) throw new Error('Gemini returned an empty Homework draft.');
      return res.json({
        engineBuild:'R33.6',
        speedBuild:'R33.40',
        jobId: randomUUID(),
        generationMethod,
        content,
        warnings,
        citations: materials.map((m:any)=>({ materialId:String(m.id), materialTitle:String(m.title||'Textbook'), chapter:String(m.chapter||m.unit||'')||undefined })),
        scopeValidated: true
      });
    } catch (error:any) {
      console.error('AI Homework generation failed:', error?.message || error);
      return res.status(transientAiError(error) ? 503 : 500).json({ error: freeAiErrorMessage(error) || 'AI Homework could not be generated.' });
    }
  });

  app.post('/api/teacher/academic/save-homework', verifyActiveUserAuth, async (req: ActiveUserRequest, res) => {
    if (!req.activeUser || !supabaseAdmin) return res.status(503).json({ error: 'Homework save service is unavailable.' });
    if (!['teacher','class_teacher','headmaster'].includes(req.activeUser.role)) return res.status(403).json({ error: 'Assigned Subject Teacher access is required.' });
    try {
      const assignmentId = String(req.body?.assignmentId || '').trim();
      const recordId = String(req.body?.id || '').trim();
      const title = String(req.body?.title || '').trim().slice(0, 300);
      const content = String(req.body?.content || '').trim().slice(0, 30000);
      const status = String(req.body?.status || 'draft').trim().toLowerCase();
      const metadata = req.body?.metadata && typeof req.body.metadata === 'object' ? req.body.metadata : {};
      const copyTargetAssignmentId = String(req.body?.copyTargetAssignmentId || '').trim();
      if (!assignmentId || !title || !content) return res.status(400).json({ error: 'Assigned scope, Homework title and content are required.' });
      if (!['draft','published'].includes(status)) return res.status(400).json({ error: 'Homework can be saved only as Draft or Published.' });

      const comm:any = await loadTeacherCommunicationScopes(req.activeUser);
      const subjectScopes = (comm.scopes || []).filter((scope:any)=>scope.scopeType === 'subject');
      const resolveScope = (id:string) => subjectScopes.find((row:any)=>String(row.assignmentId)===id || String(row.id)===id || String(row.id)===`subject:${id}`);

      const scope:any = resolveScope(assignmentId);
      if (!scope) return res.status(403).json({ error: 'This Homework scope is not part of your current Headmaster-assigned Subject Teacher mapping.' });
      const scopeSnapshot = {
        assignmentId:String(scope.assignmentId||assignmentId), academicYearId:scope.academicYearId||null, academicYear:String(scope.academicYear||comm.academicYear||'Current Academic Year'),
        classId:String(scope.classId||''), className:String(scope.className||''), divisionId:scope.divisionId?String(scope.divisionId):null, division:String(scope.division||''),
        subjectId:String(scope.subjectId||''), subjectName:String(scope.subjectName||''), teacherRecordId:String(comm.teacherId||'')
      };

      const payload:any = {
        owner_teacher_id: req.activeUser.userId,
        teacher_record_id: comm.teacherId || null,
        school_id: req.activeUser.schoolId,
        academic_year_id: scope.academicYearId || null,
        academic_year: String(scope.academicYear || comm.academicYear || 'Current Academic Year'),
        assignment_id: scope.assignmentId || assignmentId,
        class_id: scope.classId || null,
        class_name: String(scope.className || ''),
        division_id: scope.divisionId || null,
        division_name: String(scope.division || ''),
        subject_id: scope.subjectId || null,
        subject_name: String(scope.subjectName || ''),
        kind: 'homework',
        title,
        status,
        content,
        metadata: { ...metadata, scopeSnapshot },
        updated_at: new Date().toISOString(),
      };
      let saved:any;
      if (recordId) {
        const current = await supabaseAdmin.from('edunixo_academic_records').select('id,owner_teacher_id,kind').eq('id',recordId).eq('owner_teacher_id',req.activeUser.userId).maybeSingle();
        if (current.error) throw current.error;
        if (!current.data || String(current.data.kind) !== 'homework') return res.status(404).json({ error: 'This Homework draft was not found for the current Teacher.' });
        const update = await supabaseAdmin.from('edunixo_academic_records').update(payload).eq('id',recordId).eq('owner_teacher_id',req.activeUser.userId).select('id').single();
        if (update.error) throw update.error; saved = update.data;
      } else {
        const created = await supabaseAdmin.from('edunixo_academic_records').insert(payload).select('id').single();
        if (created.error) throw created.error; saved = created.data;
      }

      const syncPublication = async (recordIdToSync:string, rowScope:any, rowMetadata:any, rowTitle:string, rowContent:string, rowStatus:string) => {
        const publication:any = {
          source_record_id:recordIdToSync, school_id:req.activeUser!.schoolId, academic_year_id:rowScope.academicYearId||null, academic_year:String(rowScope.academicYear||comm.academicYear||''),
          teacher_record_id:String(comm.teacherId||'')||null, teacher_user_id:req.activeUser!.userId, assignment_id:String(rowScope.assignmentId||''),
          class_id:String(rowScope.classId||'')||null, class_name:String(rowScope.className||''), division_id:rowScope.divisionId?String(rowScope.divisionId):null, division_name:String(rowScope.division||''),
          subject_id:String(rowScope.subjectId||'')||null, subject_name:String(rowScope.subjectName||''), title:rowTitle, content:rowContent,
          homework_date:rowMetadata?.structuredInputs?.date||null, due_date:rowMetadata?.structuredInputs?.dueDate||null, status:rowStatus, metadata:rowMetadata||{},
          published_at:rowStatus==='published'?new Date().toISOString():null, updated_at:new Date().toISOString()
        };
        const bridge=await supabaseAdmin.from('edunixo_published_homework').upsert(publication,{onConflict:'source_record_id'});
        if(bridge.error && !/does not exist|schema cache|could not find/i.test(String(bridge.error.message||''))) throw bridge.error;
      };
      await syncPublication(String(saved.id), scope, payload.metadata, title, content, status);

      let copyId:string|undefined;
      if (copyTargetAssignmentId) {
        const targetScope:any = resolveScope(copyTargetAssignmentId);
        if (!targetScope) return res.status(403).json({ error: 'The requested copy-to Division/Subject is not assigned to this Teacher.' });
        const targetSnapshot={assignmentId:String(targetScope.assignmentId||copyTargetAssignmentId),academicYearId:targetScope.academicYearId||null,academicYear:String(targetScope.academicYear||comm.academicYear||''),classId:String(targetScope.classId||''),className:String(targetScope.className||''),divisionId:targetScope.divisionId?String(targetScope.divisionId):null,division:String(targetScope.division||''),subjectId:String(targetScope.subjectId||''),subjectName:String(targetScope.subjectName||''),teacherRecordId:String(comm.teacherId||'')};
        const copiedPayload:any={...payload,assignment_id:targetScope.assignmentId||copyTargetAssignmentId,academic_year_id:targetScope.academicYearId||null,academic_year:String(targetScope.academicYear||comm.academicYear||''),class_id:targetScope.classId||null,class_name:String(targetScope.className||''),division_id:targetScope.divisionId||null,division_name:String(targetScope.division||''),subject_id:targetScope.subjectId||null,subject_name:String(targetScope.subjectName||''),metadata:{...metadata,copiedFromRecordId:saved.id,scopeSnapshot:targetSnapshot},created_at:new Date().toISOString()};
        const copied = await supabaseAdmin.from('edunixo_academic_records').insert(copiedPayload).select('id').single();
        if (copied.error) throw copied.error;
        copyId = String(copied.data.id);
        await syncPublication(copyId,targetScope,copiedPayload.metadata,title,content,status);
      }

      return res.json({ success:true, id:String(saved.id), copyId });
    } catch (error:any) {
      console.error('Homework save failed:', error?.message || error);
      const message = error?.message || 'Homework could not be saved.';
      const statusCode = /not synced|does not exist|schema cache|could not find/i.test(message) ? 503 : /required|assigned|Draft|Published/i.test(message) ? 400 : 500;
      return res.status(statusCode).json({ error: message });
    }
  });


  // R33.1 — Homework history / attachment management. These routes use the
  // service role only after exact owner + kind validation, so no broader delete
  // grant or destructive migration is required.
  app.post('/api/teacher/academic/homework/:recordId/attachments/upload-ticket', verifyActiveUserAuth, async (req: ActiveUserRequest, res) => {
    if (!req.activeUser || !supabaseAdmin) return res.status(503).json({ error: 'Homework attachment upload service is unavailable.' });
    if (!['teacher','class_teacher','headmaster'].includes(req.activeUser.role)) return res.status(403).json({ error: 'Assigned Subject Teacher access is required.' });
    try {
      const recordId = safePublicText(req.params.recordId, 120);
      const fileName = safePublicText(req.body?.fileName, 300);
      const mimeType = safePublicText(req.body?.mimeType, 160) || 'application/octet-stream';
      const sizeBytes = Number(req.body?.sizeBytes || 0);
      if (!recordId || !fileName || !Number.isFinite(sizeBytes) || sizeBytes <= 0 || sizeBytes > 45 * 1024 * 1024) return res.status(400).json({ error: 'Enter a valid Homework attachment (maximum 45 MB).' });
      const record = await supabaseAdmin.from('edunixo_academic_records').select('id,owner_teacher_id,kind,school_id,assignment_id').eq('id', recordId).eq('owner_teacher_id', req.activeUser.userId).maybeSingle();
      if (record.error) throw record.error;
      if (!record.data || String(record.data.kind) !== 'homework' || (record.data.school_id && String(record.data.school_id) !== req.activeUser.schoolId)) return res.status(404).json({ error: 'This Homework was not found for the current Teacher.' });
      if (record.data.assignment_id) await resolveTeacherAcademicServerScope(req.activeUser, String(record.data.assignment_id));
      const safeName = fileName.replace(/[^a-zA-Z0-9._-]+/g, '-').replace(/^-+|-+$/g, '').slice(-180) || 'attachment';
      const storagePath = `${req.activeUser.userId}/${recordId}/${randomUUID()}-${safeName}`;
      const ticket = await supabaseAdmin.storage.from('teacher-academic-attachments').createSignedUploadUrl(storagePath, { upsert:false });
      if (ticket.error || !ticket.data?.token) throw ticket.error || new Error('Secure upload ticket could not be created.');
      return res.json({ success:true, storagePath, token:ticket.data.token, mimeType, maxBytes:45 * 1024 * 1024 });
    } catch (error:any) {
      const message = error?.message || 'Homework attachment upload ticket could not be created.';
      return res.status(/outside|assigned|Teacher account/i.test(message) ? 403 : 500).json({ error:message });
    }
  });

  app.post('/api/teacher/academic/homework/:recordId/attachments/register', verifyActiveUserAuth, async (req: ActiveUserRequest, res) => {
    if (!req.activeUser || !supabaseAdmin) return res.status(503).json({ error: 'Homework attachment service is unavailable.' });
    try {
      const recordId = safePublicText(req.params.recordId, 120);
      const fileName = safePublicText(req.body?.fileName, 300);
      const storagePath = safePublicText(req.body?.storagePath, 1000);
      const mimeType = safePublicText(req.body?.mimeType, 160) || null;
      const sizeBytes = Number(req.body?.sizeBytes || 0);
      if (!recordId || !fileName || !storagePath || !Number.isFinite(sizeBytes) || sizeBytes <= 0 || sizeBytes > 45 * 1024 * 1024) return res.status(400).json({ error: 'Enter a valid Homework attachment (maximum 45 MB).' });
      const expectedPrefix = `${req.activeUser.userId}/${recordId}/`;
      if (!storagePath.startsWith(expectedPrefix)) return res.status(403).json({ error: 'Attachment storage path does not belong to this Teacher/Homework.' });
      const record = await supabaseAdmin.from('edunixo_academic_records').select('id,owner_teacher_id,kind,school_id').eq('id', recordId).eq('owner_teacher_id', req.activeUser.userId).maybeSingle();
      if (record.error) throw record.error;
      if (!record.data || String(record.data.kind) !== 'homework' || (record.data.school_id && String(record.data.school_id) !== req.activeUser.schoolId)) return res.status(404).json({ error: 'This Homework was not found for the current Teacher.' });
      const objectCheck = await supabaseAdmin.storage.from('teacher-academic-attachments').createSignedUrl(storagePath, 60);
      if (objectCheck.error || !objectCheck.data?.signedUrl) return res.status(400).json({ error: 'Uploaded attachment could not be verified in secure storage.' });
      const saved = await supabaseAdmin.from('edunixo_academic_record_attachments').insert({ academic_record_id: recordId, owner_teacher_id: req.activeUser.userId, file_name: fileName, storage_path: storagePath, mime_type: mimeType, size_bytes: Math.round(sizeBytes) }).select('id').single();
      if (saved.error) {
        await supabaseAdmin.storage.from('teacher-academic-attachments').remove([storagePath]).catch(() => undefined);
        throw saved.error;
      }
      return res.json({ success: true, id: String(saved.data.id) });
    } catch (error: any) { return res.status(500).json({ error: error?.message || 'Homework attachment could not be registered.' }); }
  });

