  app.patch('/api/teacher/academic/submissions/:submissionId/review', verifyActiveUserAuth, async (req: ActiveUserRequest, res) => {
    if (!req.activeUser || !supabaseAdmin) return res.status(503).json({ error: 'Assignment review service is unavailable.' });
    if (!['teacher','class_teacher','headmaster'].includes(req.activeUser.role)) return res.status(403).json({ error: 'Assigned Subject Teacher access is required.' });
    try {
      const submissionId = safePublicText(req.params.submissionId, 120);
      const submission = await supabaseAdmin.from('edunixo_assignment_submissions').select('id,academic_record_id').eq('id', submissionId).maybeSingle();
      if (submission.error) throw submission.error;
      if (!submission.data) return res.status(404).json({ error: 'Assignment submission was not found.' });
      const record = await supabaseAdmin.from('edunixo_academic_records').select('id,owner_teacher_id,kind,school_id,assignment_id').eq('id', submission.data.academic_record_id).eq('owner_teacher_id', req.activeUser.userId).maybeSingle();
      if (record.error) throw record.error;
      if (!record.data || String(record.data.kind) !== 'classwork-assignment' || (record.data.school_id && String(record.data.school_id) !== req.activeUser.schoolId)) return res.status(403).json({ error: 'This submission is outside the current Teacher assignment scope.' });
      if (record.data.assignment_id) await resolveTeacherAcademicServerScope(req.activeUser, String(record.data.assignment_id));
      const checked = req.body?.checked === true;
      const marksRaw = req.body?.marks;
      const marks = marksRaw === '' || marksRaw === null || marksRaw === undefined ? null : Number(marksRaw);
      if (marks !== null && (!Number.isFinite(marks) || marks < 0 || marks > 10000)) return res.status(400).json({ error: 'Enter valid marks.' });
      const patch = { remarks: safePublicText(req.body?.remarks, 2000) || null, marks, grade: safePublicText(req.body?.grade, 80) || null, status: checked ? 'checked' : 'submitted', checked_at: checked ? new Date().toISOString() : null };
      const updated = await supabaseAdmin.from('edunixo_assignment_submissions').update(patch).eq('id', submissionId).eq('academic_record_id', record.data.id).select('id').single();
      if (updated.error) throw updated.error;
      return res.json({ success: true });
    } catch (error: any) {
      const message = error?.message || 'Assignment submission could not be reviewed.';
      return res.status(/outside|assigned|Teacher account/i.test(message) ? 403 : /valid marks/i.test(message) ? 400 : 500).json({ error: message });
    }
  });

