  app.get('/api/parent/portal/leave-applications', verifyActiveUserAuth, async (req: ActiveUserRequest, res) => {
    if (!req.activeUser || !supabaseAdmin) return res.status(503).json({ error: 'Parent leave workflow is unavailable.' });
    if (String(req.activeUser.role || '').toLowerCase() !== 'parent') return res.status(403).json({ error: 'Parent account required.' });
    try {
      const ctx = await resolveStudentPortalContext(req.activeUser, safePublicText(req.query.studentId, 120) || null);
      const [requests, decisions, cancellations] = await Promise.all([
        supabaseAdmin.from('audit_logs').select('*').eq('school_id', ctx.schoolId).eq('actor_user_id', ctx.userId).eq('entity_id', ctx.studentId).eq('action', 'leave.application.requested').order('created_at', { ascending: false }).limit(500),
        supabaseAdmin.from('audit_logs').select('*').eq('school_id', ctx.schoolId).eq('action', 'leave.application.decided').order('created_at', { ascending: false }).limit(1000),
        supabaseAdmin.from('audit_logs').select('*').eq('school_id', ctx.schoolId).eq('action', 'leave.application.cancelled').order('created_at', { ascending: false }).limit(1000)
      ]);
      if (requests.error) throw requests.error;
      if (decisions.error) throw decisions.error;
      if (cancellations.error) throw cancellations.error;
      const byRequest = (rows: any[]) => { const map = new Map<string, any>(); for (const row of rows || []) { const id = String(row.metadata?.request_id || ''); if (id && !map.has(id)) map.set(id, row); } return map; };
      const decisionMap = byRequest(decisions.data || []);
      const cancelMap = byRequest(cancellations.data || []);
      const applications = (requests.data || []).map((row: any) => {
        const base = row.metadata?.application && typeof row.metadata.application === 'object' ? row.metadata.application : {};
        const decision = decisionMap.get(String(row.id));
        const cancel = cancelMap.get(String(row.id));
        const status = cancel && !decision ? 'Cancelled' : decision ? (String(decision.metadata?.decision || '').toLowerCase() === 'approve' ? 'Approved' : 'Rejected') : 'Pending';
        return { ...base, id: String(row.id), status, reviewedAt: decision?.created_at || cancel?.created_at || null, remarks: decision?.metadata?.remarks || base.remarks || '' };
      });
      return res.json({ applications });
    } catch (error: any) { return res.status(500).json({ error: error?.message || 'Child leave applications could not be loaded.' }); }
  });

