      if (resolution.length < 2) return res.status(400).json({ error: 'A short resolution/remark is required.' });
      const requestRead = await supabaseAdmin.from('audit_logs').select('*').eq('id',requestId).eq('school_id',req.academicAdmin.schoolId).eq('action','student.service.requested').maybeSingle();
      if (requestRead.error) throw requestRead.error;
