  app.post('/api/admin/subjects', verifyHeadmasterAuth, requireHeadmasterModule('master_data'), async (req: HeadmasterRequest, res) => {
    if (!supabaseAdmin) return res.status(503).json({ error: 'Subject service is unavailable.' });
    const headmaster = req.authenticatedHeadmaster!;
    const subjectName = String(req.body.subjectName ?? '').trim();
    const subjectType = String(req.body.subjectType ?? 'Core').trim() || 'Core';
    if (!subjectName || subjectName.length > 150) return res.status(400).json({ error: 'A valid subject name is required.' });

    const { data: duplicate, error: duplicateError } = await supabaseAdmin
      .from('subjects')
      .select('id')
      .eq('school_id', headmaster.schoolId)
      .ilike('subject_name', subjectName)
      .limit(1);
    if (duplicateError) return res.status(500).json({ error: duplicateError.message || 'Subject duplicate check failed.' });
    if (duplicate?.length) return res.status(409).json({ error: 'A subject with this name already exists.' });

    try {
      const subjectCode = await makeSubjectCode(headmaster.schoolId, subjectName);
      const { data, error } = await supabaseAdmin
        .from('subjects')
        .insert({
          school_id: headmaster.schoolId,
          subject_name: subjectName,
          subject_code: subjectCode,
          subject_type: subjectType,
          is_active: true
        })
        .select('id, subject_name, subject_code, subject_type, is_active, created_at, updated_at')
        .single();
      if (error || !data) return res.status(500).json({ error: error?.message || 'Subject could not be created.' });
      return res.status(201).json({ success: true, subject: data });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Subject could not be created.' });
    }
  });

