  app.put('/api/admin/role-permissions', verifyHeadmasterAuth, requireHeadmasterModule('user_access'), async (req: HeadmasterRequest, res) => {
    if (!supabaseAdmin) return res.status(503).json({ error: 'Permissions service is unavailable.' });
    const headmaster = req.authenticatedHeadmaster!;
    const permissions = Array.isArray(req.body.permissions) ? req.body.permissions : [];
    if (!permissions.length) return res.status(400).json({ error: 'At least one permission entry is required.' });

    const sanitized = permissions.map((entry: any) => ({
      role_name: String(entry.roleName ?? '').trim().toLowerCase(),
      module_key: String(entry.moduleKey ?? '').trim().toLowerCase(),
      allowed: entry.allowed === true
    }));
    if (sanitized.some((entry: any) =>
      !PERMISSION_ROLES.includes(entry.role_name as any) ||
      !PERMISSION_MODULES.includes(entry.module_key as any)
    )) {
      return res.status(400).json({ error: 'One or more permission entries contain an invalid role or module.' });
    }

    // Headmaster access is never removable from the permission editor.
    sanitized.forEach((entry: any) => {
      if (entry.role_name === 'headmaster') entry.allowed = true;
    });

    const now = new Date().toISOString();
    const rows = sanitized.map((entry: any) => ({
      school_id: headmaster.schoolId,
      role_name: entry.role_name,
      module_key: entry.module_key,
      allowed: entry.allowed,
      updated_by: headmaster.userId,
      updated_at: now
    }));
    const { error } = await supabaseAdmin
      .from('role_permissions')
      .upsert(rows, { onConflict: 'school_id,role_name,module_key' });
    if (error) return res.status(500).json({ error: 'Role permissions could not be saved.' });

    await supabaseAdmin.from('staff_provisioning_audits').insert({
      school_id: headmaster.schoolId,
      staff_user_id: null,
      performed_by_user_id: headmaster.userId,
      action: 'ROLE_PERMISSIONS_UPDATED',
      details: `Updated ${rows.length} role/module permission entries.`
    });
    return res.json({ success: true, permissions: sanitized });
  });

  // R2.5.47 Phase 3 — canonical per-user Effective Access summary.
  // Read-only: evaluates the same server-side access matrix used by runtime guards.
  app.get('/api/admin/staff-effective-access', verifyHeadmasterAuth, requireHeadmasterModule('user_access'), async (req: HeadmasterRequest, res) => {
    res.setHeader('Cache-Control', 'no-store');
    if (!supabaseAdmin) return res.status(503).json({ error: 'Effective Access service is unavailable.' });
    const headmaster = req.authenticatedHeadmaster!;
    try {
      const { data: memberships, error: membershipError } = await supabaseAdmin
        .from('user_school_memberships')
        .select('user_id, role_in_school, is_active')
        .eq('school_id', headmaster.schoolId)
        .in('role_in_school', ALLOWED_STAFF_ROLES);
      if (membershipError) throw membershipError;

      const activeIds = (memberships || []).filter((row: any) => row.is_active !== false).map((row: any) => String(row.user_id)).filter(Boolean);
      const access: any[] = [];
      const batchSize = 8;
      for (let offset = 0; offset < activeIds.length; offset += batchSize) {
        const batch = activeIds.slice(offset, offset + batchSize);
        const rows = await Promise.all(batch.map(async (userId) => {
          const { data, error } = await supabaseAdmin!.rpc('platform_user_module_access_matrix', {
            target_school_id: headmaster.schoolId,
            target_user_id: userId
          });
          if (error) return { userId, available: false, error: 'Canonical access matrix could not be evaluated.' };
          const matrix: any = data || {};
          const subscription: any = matrix.subscription || {};
          return {
            userId,
            available: true,
            role: String(matrix.role || ''),
            allowedModuleKeys: Array.isArray(matrix.allowed_module_keys) ? matrix.allowed_module_keys.map(String) : [],
            accessState: String(subscription.access_state || 'restricted'),
            restrictionReason: subscription.restriction_reason || null
          };
        }));
        access.push(...rows);
      }
      return res.json({ success: true, access });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Effective Access summary could not be loaded.' });
    }
  });

