  // R4.9 — Cloud-backed Leave Management workflow
  // Uses the existing school-scoped audit_logs foundation so no new SQL/table is
  // required. Operational leave decisions are reconstructed from immutable request,
  // Clerk verification, Headmaster/Clerk decision and cancellation events.
  // ---------------------------------------------------------------------------
  // R4.9.6: authenticated multilingual leave-reason generator.
  // Gemini is server-side only. When the key is not configured, the client-provided
  // deterministic localized fallback is returned so Preview remains fully usable.
  // Headmaster Leave calendar/policy — canonical cloud state.
  // Holiday dates are shared with Academic Setup; leave counting policy lives in
  // school_academic_settings.configuration so every device uses the same rule.
  app.get('/api/headmaster/leave-settings', verifyHeadmasterAuth, requireHeadmasterModule('leave_management'), async (req: HeadmasterRequest, res) => {
    if (!supabaseAdmin || !req.authenticatedHeadmaster) return res.status(503).json({ error: 'Leave settings service is unavailable.' });
    try {
      const schoolId = req.authenticatedHeadmaster.schoolId;
      const [settings, years, holidays] = await Promise.all([
        supabaseAdmin.from('school_academic_settings').select('configuration').eq('school_id', schoolId).maybeSingle(),
        supabaseAdmin.from('school_academic_years').select('id,year_code,is_active').eq('school_id', schoolId).order('sort_order').order('year_code'),
        supabaseAdmin.from('school_holidays').select('*').eq('school_id', schoolId).eq('is_active', true).order('starts_on')
      ]);
      if (settings.error) throw settings.error; if (years.error) throw years.error; if (holidays.error) throw holidays.error;
      const activeYear = (years.data || []).find((row:any)=>row.is_active) || (years.data || [])[0] || null;
      const config:any = settings.data?.configuration || {};
      const leaveRule = ['Rule A','Rule B','Rule C'].includes(String(config.leaveRule)) ? String(config.leaveRule) : 'Rule A';
      return res.json({
        leaveRule,
        activeAcademicYear: activeYear ? { id: activeYear.id, year: activeYear.year_code } : null,
        holidays: (holidays.data || []).map((row:any)=>({
          id: row.id, name: row.holiday_name, type: row.metadata?.leave_type || row.holiday_type || 'School Holiday',
          startDate: row.starts_on, endDate: row.ends_on, applicableClasses: row.metadata?.applicable_classes || 'All',
          remarks: row.description || '', academicYear: (years.data || []).find((year:any)=>year.id===row.academic_year_id)?.year_code || activeYear?.year_code || '',
          reminderEnabled: row.metadata?.reminder_enabled !== false,
          notificationChannels: row.metadata?.notification_channels || { website:true,email:true,sms:false,whatsapp:true }
        }))
      });
    } catch (error:any) { return res.status(500).json({ error: error?.message || 'Leave settings could not be loaded.' }); }
  });

