      const payload:any={school_id:schoolId,academic_year_id:yearId,holiday_name:name,starts_on:start,ends_on:end,holiday_type:safePublicText(h.type,80)||'School',description:safePublicText(h.remarks,1500)||null,is_active:true,metadata:{leave_type:safePublicText(h.type,80)||'School Holiday',applicable_classes:safePublicText(h.applicableClasses,500)||'All',reminder_enabled:h.reminderEnabled!==false,notification_channels:h.notificationChannels||{website:true,email:true,sms:false,whatsapp:true}},updated_by:actor,updated_at:new Date().toISOString()};
      let result:any;
