  app.post('/api/leave-management/generate-reason', verifyActiveUserAuth, async (req: ActiveUserRequest, res) => {
    const leaveType = String(req.body?.leaveType || '').trim().slice(0, 120);
    const startDate = String(req.body?.startDate || '').trim().slice(0, 20);
    const endDate = String(req.body?.endDate || '').trim().slice(0, 20);
    const halfDayOption = String(req.body?.halfDayOption || '').trim().slice(0, 40);
    const language = String(req.body?.language || 'English').trim().slice(0, 80);
    const fallbackText = String(req.body?.fallbackText || '').trim().slice(0, 1500);

    if (!leaveType || !startDate || !endDate || !fallbackText) {
      return res.status(400).json({ error: 'Leave type, dates and fallback reason are required.' });
    }

    if (!geminiApiKey || !ai) {
      return res.json({ text: fallbackText, source: 'smart-template', isSimulated: true });
    }

    try {
      const prompt = `Write one concise, formal school staff leave-application reason in ${language}.
`
        + `Leave type: ${leaveType}. From: ${startDate}. To: ${endDate}.`
        + (halfDayOption ? ` Half-day session: ${halfDayOption}.` : '')
        + `
Use this already-localized draft as the factual baseline and do not invent new facts: ${fallbackText}
`
        + `Return only the final reason text, no heading, bullets, quotation marks or explanation.`;

      const response = await ai.models.generateContent({
        model: geminiGenerationModel,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: {
          systemInstruction: 'You generate factual, concise school leave-application reasons. Preserve dates and leave purpose exactly. Never invent medical diagnoses, emergencies or personal facts.'
        }
      });
      const text = String(response.text || '').trim();
      return res.json({ text: text || fallbackText, source: text ? 'gemini' : 'smart-template', isSimulated: !text });
    } catch (error: any) {
      console.error('Leave reason generation failed; returning localized fallback.', error);
      return res.json({ text: fallbackText, source: 'smart-template', isSimulated: true });
    }
  });


