  app.post('/api/leave-management/applications/:requestId/decision', verifyAcademicAdminAuth, async (req: AcademicAdminRequest, res) => {
    if (!supabaseAdmin || !req.academicAdmin) return res.status(503).json({ error: 'Leave Management cloud workflow is unavailable.' });
    try {
      const requestId = safePublicText(req.params.requestId, 120);
      const decision = safePublicText(req.body?.decision, 20).toLowerCase();
      if (!['approve', 'reject'].includes(decision)) return res.status(400).json({ error: 'Decision must be approve or reject.' });
      const { data: requestRow, error: requestError } = await supabaseAdmin.from('audit_logs').select('*').eq('id', requestId).eq('school_id', req.academicAdmin.schoolId).eq('action', 'leave.application.requested').maybeSingle();
      if (requestError) throw requestError;
      if (!requestRow) return res.status(404).json({ error: 'Leave application was not found.' });
      const application = requestRow.metadata?.application || {};
      const applicantRole = String(application.applicantRole || 'staff');
      if (req.academicAdmin.role !== 'headmaster') {
        return res.status(403).json({ error: 'Final leave approval is Headmaster-only.' });
      }
      const { data: existing, error: existingError } = await supabaseAdmin.from('audit_logs').select('id').eq('school_id', req.academicAdmin.schoolId).eq('action', 'leave.application.decided').contains('metadata', { request_id: requestId }).maybeSingle();
      if (existingError) throw existingError;
      if (existing) return res.status(409).json({ error: 'This leave application has already been decided.' });
      const { error: insertError } = await supabaseAdmin.from('audit_logs').insert({
        actor_user_id: req.academicAdmin.userId,
        actor_kind: 'school_user',
        action: 'leave.application.decided',
        entity_type: 'leave_application',
        entity_id: String(requestRow.entity_id || ''),
        school_id: req.academicAdmin.schoolId,
        summary: `${req.academicAdmin.role === 'headmaster' ? 'Headmaster' : 'Clerk'} ${decision === 'approve' ? 'approved' : 'rejected'} ${applicantRole} leave ${requestId}.`,
        before_state: null,
        after_state: null,
        metadata: { workflow: 'leave_management', request_id: requestId, decision, remarks: safePublicText(req.body?.remarks, 3000), reviewed_by_name: safePublicText(req.body?.reviewedByName, 200) || (req.academicAdmin.role === 'headmaster' ? 'Headmaster' : 'Clerk') },
      });
      if (insertError) throw insertError;
      try {
        const applicantUserId = String(requestRow.actor_user_id || '').trim();
        if (applicantUserId) {
          const statusLabel = decision === 'approve' ? 'Approved' : 'Rejected';
          const remarks = safePublicText(req.body?.remarks, 3000);
          await supabaseAdmin.from('edunixo_user_notifications').upsert({
            school_id: req.academicAdmin.schoolId,
            recipient_user_id: applicantUserId,
            recipient_student_id: applicantRole.toLowerCase() === 'student' || applicantRole.toLowerCase() === 'parent' ? String(requestRow.entity_id || '') : null,
            title: `Leave Application ${statusLabel}`,
            body: `Your leave application from ${String(application.startDate || '—')} to ${String(application.endDate || '—')} was ${statusLabel.toLowerCase()} by the Headmaster.${remarks ? ` Remarks: ${remarks}` : ''}`,
            notification_type: 'leave_decision',
            source_key: `leave-decision:${req.academicAdmin.schoolId}:${requestId}`,
            is_read: false
          }, { onConflict: 'source_key' });
        }
      } catch { /* leave decision remains canonical even if an older notification table is unavailable */ }
      return res.json({ success: true, status: decision === 'approve' ? 'Approved' : 'Rejected' });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Leave decision could not be saved.' });
    }
  });

