  app.post('/api/notifications/holiday-reminder', verifyAcademicAdminAuth, requireAcademicAdminModule('communication'), async (req: AcademicAdminRequest, res) => {
    try {
      if (!supabaseAdmin || !req.academicAdmin) return res.status(503).json({ error: 'Notification service is unavailable.' });
      const holiday = req.body?.holiday || {};
      const channels = req.body?.channels || {};
      const message = String(req.body?.message || '').trim();
      if (!holiday.id || !holiday.name || !message) return res.status(400).json({ error: 'Holiday reminder payload is incomplete.' });

      const { data: memberships, error: membershipError } = await supabaseAdmin
        .from('user_school_memberships')
        .select('user_id')
        .eq('school_id', req.academicAdmin.schoolId)
        .eq('is_active', true);
      if (membershipError) return res.status(500).json({ error: 'Unable to resolve school recipients.' });
      const userIds = Array.from(new Set((memberships || []).map((item: any) => item.user_id).filter(Boolean)));
      const { data: users, error: usersError } = userIds.length
        ? await supabaseAdmin.from('users').select('id, full_name, email, phone_number').in('id', userIds).eq('is_active', true).eq('status', 'Active')
        : { data: [], error: null } as any;
      if (usersError) return res.status(500).json({ error: 'Unable to load notification recipients.' });

      const results: Record<string, any> = {};
      const activeUsers = users || [];
      const emails = activeUsers.map((item: any) => item.email).filter(Boolean);
      const phones = activeUsers.map((item: any) => item.phone_number).filter(Boolean);

      if (channels.email) {
        const apiKey = process.env.RESEND_API_KEY;
        const from = process.env.HOLIDAY_EMAIL_FROM;
        if (!apiKey || !from) {
          results.email = { status: 'not_configured', recipients: emails.length };
        } else if (emails.length === 0) {
          results.email = { status: 'no_recipients', recipients: 0 };
        } else {
          const response = await fetch('https://api.resend.com/emails', {
            method: 'POST',
            headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
            body: JSON.stringify({ from, to: emails, subject: `Holiday Reminder: ${holiday.name}`, text: message })
          });
          results.email = { status: response.ok ? 'sent' : 'failed', recipients: emails.length, httpStatus: response.status };
        }
      }

      const sendWebhook = async (channel: 'sms' | 'whatsapp', url?: string, token?: string) => {
        if (!url) return { status: 'not_configured', recipients: phones.length };
        if (phones.length === 0) return { status: 'no_recipients', recipients: 0 };
        const response = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
          body: JSON.stringify({ schoolId: req.academicAdmin?.schoolId, holiday, message, recipients: phones, channel })
        });
        return { status: response.ok ? 'sent' : 'failed', recipients: phones.length, httpStatus: response.status };
      };

      if (channels.sms) results.sms = { status: 'skipped_policy', recipients: phones.length, reason: 'SMS is reserved for OTP, account security and critical/emergency workflows.' };
      if (channels.whatsapp) results.whatsapp = await sendWebhook('whatsapp', process.env.WHATSAPP_WEBHOOK_URL, process.env.WHATSAPP_WEBHOOK_TOKEN);

      return res.json({ success: true, holidayId: holiday.id, results });
    } catch (error: any) {
      return res.status(500).json({ error: error?.message || 'Holiday reminders could not be dispatched.' });
    }
  });

