  // ---------------------------------------------------------------------------
  // R2.5.36 — Peon Operations + Headmaster-controlled Bell Timing
  // Least-privilege operational role. Gate passes remain Headmaster-issued;
  // Peon may only record visitors/returns and delivery status.
  // Bell configuration is stored additively inside school_academic_settings.configuration.
  // ---------------------------------------------------------------------------
  const assertPeon = (req: ActiveUserRequest, res: express.Response) => {
    if (!req.activeUser || req.activeUser.role !== 'peon') {
      res.status(403).json({ error: 'Peon operational account required.' });
      return null;
    }
    return req.activeUser;
  };

  const bellWeekdays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const normalizeBellTime = (value:any) => {
    const text=safePublicText(value,10);
    const match=/^(\d{1,2}):(\d{2})/.exec(text);
    if(!match)return '';
    const h=Number(match[1]),m=Number(match[2]);
    return h>=0&&h<=23&&m>=0&&m<=59?`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`:'';
  };
  const bellConfigShape = (raw:any) => {
    const b=raw&&typeof raw==='object'?raw:{};
    const mode=b.mode==='manual'?'manual':'timetable';
    const manual=b.manualSchedule&&typeof b.manualSchedule==='object'?b.manualSchedule:{};
    const days=Array.isArray(manual.days)?manual.days.filter((d:any)=>bellWeekdays.includes(String(d))):['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
    const events=(Array.isArray(manual.events)?manual.events:[]).map((e:any,index:number)=>({
      id:safePublicText(e?.id,120)||`manual-${index+1}`,
      label:safePublicText(e?.label,160)||`Bell ${index+1}`,
      time:normalizeBellTime(e?.time),
      kind:['assembly','period','break','closing','custom'].includes(String(e?.kind||''))?String(e.kind):'custom',
      enabled:e?.enabled!==false
    })).filter((e:any)=>e.time);
    return {
      mode,
      revision:Math.max(1,Math.floor(Number(b.revision||1))),
      updatedAt:safePublicText(b.updatedAt,80)||null,
      manualSchedule:{
        name:safePublicText(manual.name,160)||'Manual Bell Schedule',
        effectiveFrom:/^\d{4}-\d{2}-\d{2}$/.test(String(manual.effectiveFrom||''))?String(manual.effectiveFrom):null,
        effectiveTo:/^\d{4}-\d{2}-\d{2}$/.test(String(manual.effectiveTo||''))?String(manual.effectiveTo):null,
        days:days.length?days:['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'],
        events
      }
    };
  };
  const loadBellPeriods = async (schoolId:string) => {
    if(!supabaseAdmin)throw new Error('Bell schedule service unavailable.');
    const years=await supabaseAdmin.from('school_academic_years').select('id,is_active').eq('school_id',schoolId).order('sort_order');
    if(years.error)throw years.error;
    const active=(years.data||[]).find((r:any)=>r.is_active)||(years.data||[])[0];
    let query=supabaseAdmin.from('school_periods').select('id,period_name,period_number,starts_at,ends_at,period_type,sort_order,is_active').eq('school_id',schoolId).eq('is_active',true).order('sort_order').order('period_number');
    if(active?.id)query=query.eq('academic_year_id',active.id);
    const periods=await query;if(periods.error)throw periods.error;
    const rows=periods.data||[];
    const byTime=new Map<string,any>();
    for(const p of rows){const time=normalizeBellTime(p.starts_at);if(!time||byTime.has(time))continue;byTime.set(time,{id:`period-start:${p.id}`,label:String(p.period_name||`Period ${p.period_number||''}`).trim(),time,kind:String(p.period_type||'').toLowerCase()==='break'?'break':String(p.period_type||'').toLowerCase()==='assembly'?'assembly':'period'});}
    const last=[...rows].filter((p:any)=>normalizeBellTime(p.ends_at)).sort((a:any,b:any)=>String(a.ends_at).localeCompare(String(b.ends_at))).pop();
    if(last){const time=normalizeBellTime(last.ends_at);if(time&&!byTime.has(time))byTime.set(time,{id:`school-close:${last.id}`,label:'School Closing Bell',time,kind:'closing'});}
    return Array.from(byTime.values()).sort((a:any,b:any)=>a.time.localeCompare(b.time));
  };
  const bellDateRange = (days:number) => {
    const today=edunixoSchoolDateKey();
    const [year,month,day]=today.split('-').map(Number);
    return Array.from({length:days},(_,i)=>{
      const calendarDate=new Date(Date.UTC(year,month-1,day+i));
      const dateKey=calendarDate.toISOString().slice(0,10);
      return { dateKey, weekday: bellWeekdays[calendarDate.getUTCDay()] };
    });
  };
  const schoolLocalEpochMs = (dateKey:string,time:string,timeZone=EDUNIXO_DEFAULT_SCHOOL_TIME_ZONE) => {
    const dm=/^(\d{4})-(\d{2})-(\d{2})$/.exec(dateKey),tm=/^(\d{2}):(\d{2})$/.exec(time);
    if(!dm||!tm)return null;
    const target=[Number(dm[1]),Number(dm[2]),Number(dm[3]),Number(tm[1]),Number(tm[2])];
    if(target.some(v=>!Number.isFinite(v))||target[1]<1||target[1]>12||target[2]<1||target[2]>31||target[3]<0||target[3]>23||target[4]<0||target[4]>59)return null;
    const targetUtc=Date.UTC(target[0],target[1]-1,target[2],target[3],target[4],0,0);
    let epoch=targetUtc;
    const formatter=new Intl.DateTimeFormat('en-CA',{timeZone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});
    for(let attempt=0;attempt<3;attempt++){
      const parts=formatter.formatToParts(new Date(epoch));
      const read=(type:string)=>Number(parts.find(part=>part.type===type)?.value||0);
      const representedUtc=Date.UTC(read('year'),read('month')-1,read('day'),read('hour'),read('minute'),read('second'),0);
      const delta=targetUtc-representedUtc;
      epoch+=delta;
      if(Math.abs(delta)<1000)break;
    }
    return epoch;
  };

  app.get('/api/headmaster/bell-timing', verifyHeadmasterAuth, requireHeadmasterModule('timetable'), async(req:HeadmasterRequest,res)=>{
    if(!supabaseAdmin||!req.authenticatedHeadmaster)return res.status(503).json({error:'Bell Timing service is unavailable.'});
    try{const schoolId=req.authenticatedHeadmaster.schoolId;const [settings,periodEvents]=await Promise.all([supabaseAdmin.from('school_academic_settings').select('configuration').eq('school_id',schoolId).maybeSingle(),loadBellPeriods(schoolId)]);if(settings.error)throw settings.error;const config:any=settings.data?.configuration||{};return res.json({bellTiming:bellConfigShape(config.bellTiming),timetableEvents:periodEvents,timeZone:EDUNIXO_DEFAULT_SCHOOL_TIME_ZONE});}catch(error:any){return res.status(500).json({error:error?.message||'Bell Timing could not be loaded.'});}
  });

  app.put('/api/headmaster/bell-timing', verifyHeadmasterAuth, requireHeadmasterModule('timetable'), async(req:HeadmasterRequest,res)=>{
    if(!supabaseAdmin||!req.authenticatedHeadmaster)return res.status(503).json({error:'Bell Timing service is unavailable.'});
    try{const schoolId=req.authenticatedHeadmaster.schoolId,userId=req.authenticatedHeadmaster.userId;const current=await supabaseAdmin.from('school_academic_settings').select('configuration').eq('school_id',schoolId).maybeSingle();if(current.error)throw current.error;if(!current.data)return res.status(409).json({error:'Academic Setup must be initialized before Bell Timing can be configured.'});const requested=bellConfigShape(req.body?.bellTiming||{});if(requested.mode==='manual'&&!requested.manualSchedule.events.length)return res.status(400).json({error:'Manual Bell Schedule requires at least one valid bell time.'});const existing=bellConfigShape((current.data.configuration||{}).bellTiming);const saved={...requested,revision:existing.revision+1,updatedAt:new Date().toISOString()};const configuration={...(current.data.configuration||{}),bellTiming:saved};const write=await supabaseAdmin.from('school_academic_settings').update({configuration,updated_by:userId,updated_at:new Date().toISOString()}).eq('school_id',schoolId);if(write.error)throw write.error;await supabaseAdmin.from('audit_logs').insert({school_id:schoolId,actor_user_id:userId,actor_kind:'school_user',action:'bell.schedule.updated',entity_type:'bell_schedule',entity_id:schoolId,summary:`Headmaster activated ${saved.mode==='manual'?'Manual':'Timetable'} Bell Schedule.`,metadata:{mode:saved.mode,revision:saved.revision,manualSchedule:saved.mode==='manual'?saved.manualSchedule:null}});return res.json({success:true,bellTiming:saved});}catch(error:any){return res.status(500).json({error:error?.message||'Bell Timing could not be saved.'});}
  });

  const loadApprovedBellLeaveRanges = async (schoolId:string, userId:string) => {
    if(!supabaseAdmin)return [] as any[];
    const [requests,decisions]=await Promise.all([
      supabaseAdmin.from('audit_logs').select('id,actor_user_id,metadata,created_at').eq('school_id',schoolId).eq('actor_user_id',userId).eq('action','leave.application.requested').order('created_at',{ascending:false}).limit(500),
      supabaseAdmin.from('audit_logs').select('metadata,created_at').eq('school_id',schoolId).eq('action','leave.application.decided').order('created_at',{ascending:false}).limit(1000)
    ]);
    if(requests.error)throw requests.error;if(decisions.error)throw decisions.error;
    const approved=new Set<string>();
    for(const row of decisions.data||[]){const requestId=String(row.metadata?.request_id||'');if(requestId&&!approved.has(requestId)&&String(row.metadata?.decision||'').toLowerCase()==='approve')approved.add(requestId);}
    return (requests.data||[]).filter((row:any)=>approved.has(String(row.id||''))).map((row:any)=>{
      const a=row.metadata?.application&&typeof row.metadata.application==='object'?row.metadata.application:{};
      const startDate=/^\d{4}-\d{2}-\d{2}$/.test(String(a.startDate||''))?String(a.startDate):'';
      const endDate=/^\d{4}-\d{2}-\d{2}$/.test(String(a.endDate||''))?String(a.endDate):startDate;
      return {requestId:String(row.id||''),startDate,endDate,isHalfDay:Boolean(a.isHalfDay),halfDayOption:['Morning Session','Afternoon Session'].includes(String(a.halfDayOption||''))?String(a.halfDayOption):null};
    }).filter((r:any)=>r.startDate&&r.endDate&&r.startDate<=r.endDate);
  };
  const bellMinutes=(time:string)=>{const m=/^(\d{2}):(\d{2})$/.exec(String(time||''));return m?Number(m[1])*60+Number(m[2]):0;};
  const isBellSuppressedByLeave=(dateKey:string,time:string,dayEvents:any[],leaveRanges:any[])=>{
    const matching=leaveRanges.filter((r:any)=>dateKey>=r.startDate&&dateKey<=r.endDate);
    if(!matching.length)return false;
    if(matching.some((r:any)=>!r.isHalfDay||!r.halfDayOption))return true;
    const times=(dayEvents||[]).map((e:any)=>bellMinutes(String(e.time||''))).filter((n:number)=>Number.isFinite(n)&&n>=0).sort((a:number,b:number)=>a-b);
    if(!times.length)return true;
    const boundary=(times[0]+times[times.length-1])/2;
    const current=bellMinutes(time);
    return matching.some((r:any)=>r.halfDayOption==='Morning Session'?current<=boundary:r.halfDayOption==='Afternoon Session'?current>boundary:false);
  };

  app.get('/api/peon/bell-schedule', verifyActiveUserAuth, async(req:ActiveUserRequest,res)=>{
    if(!supabaseAdmin)return res.status(503).json({error:'Bell schedule service unavailable.'});const actor=assertPeon(req,res);if(!actor)return;
    try{const [settings,periodEvents,holidays,approvedLeaveRanges]=await Promise.all([supabaseAdmin.from('school_academic_settings').select('configuration').eq('school_id',actor.schoolId).maybeSingle(),loadBellPeriods(actor.schoolId),supabaseAdmin.from('school_holidays').select('starts_on,ends_on').eq('school_id',actor.schoolId).eq('is_active',true),loadApprovedBellLeaveRanges(actor.schoolId,actor.userId)]);if(settings.error)throw settings.error;if(holidays.error)throw holidays.error;const bell=bellConfigShape((settings.data?.configuration||{}).bellTiming);const holidayRanges=(holidays.data||[]).map((h:any)=>[String(h.starts_on||''),String(h.ends_on||h.starts_on||'')]);const schedule:any[]=[];for(const {dateKey,weekday} of bellDateRange(14)){if(holidayRanges.some(([a,b])=>a&&b&&dateKey>=a&&dateKey<=b))continue;let events:any[]=periodEvents;if(bell.mode==='manual'){const m=bell.manualSchedule;if(!m.days.includes(weekday))continue;if(m.effectiveFrom&&dateKey<m.effectiveFrom)continue;if(m.effectiveTo&&dateKey>m.effectiveTo)continue;events=m.events.filter((e:any)=>e.enabled!==false);}else if(weekday==='Sunday')continue;for(const e of events){if(isBellSuppressedByLeave(dateKey,e.time,events,approvedLeaveRanges))continue;const epochMs=schoolLocalEpochMs(dateKey,e.time);if(epochMs==null)continue;schedule.push({id:`${actor.schoolId}:${bell.revision}:${dateKey}:${e.time}:${e.id}`,localDate:dateKey,time:e.time,label:e.label,kind:e.kind||'period',epochMs});}}
      const today=edunixoSchoolDateKey();const todaysLeave=approvedLeaveRanges.filter((r:any)=>today>=r.startDate&&today<=r.endDate);return res.json({source:bell.mode,revision:bell.revision,timeZone:EDUNIXO_DEFAULT_SCHOOL_TIME_ZONE,schedule,todayEvents:schedule.filter((e:any)=>e.localDate===today),leaveSuppression:{activeToday:todaysLeave.length>0,ranges:approvedLeaveRanges}});
    }catch(error:any){return res.status(500).json({error:error?.message||'Bell schedule could not be loaded.'});}
  });

  app.get('/api/peon/operations/snapshot', verifyActiveUserAuth, async(req:ActiveUserRequest,res)=>{
    if(!supabaseAdmin)return res.status(503).json({error:'Peon Operations service unavailable.'});const actor=assertPeon(req,res);if(!actor)return;
    try{const [visitors,students,staff,dispatches,deliveryLogs,notifications]=await Promise.all([
      supabaseAdmin.from('edunixo_visitor_register_entries').select('*').eq('school_id',actor.schoolId).order('created_at',{ascending:false}).limit(500),
      supabaseAdmin.from('edunixo_student_gate_passes').select('*').eq('school_id',actor.schoolId).order('created_at',{ascending:false}).limit(500),
      supabaseAdmin.from('edunixo_staff_gate_passes').select('*').eq('school_id',actor.schoolId).order('created_at',{ascending:false}).limit(500),
      supabaseAdmin.from('edunixo_office_dispatch_records').select('*').eq('school_id',actor.schoolId).eq('direction','outgoing').order('dispatch_date',{ascending:false}).limit(500),
      supabaseAdmin.from('audit_logs').select('*').eq('school_id',actor.schoolId).eq('action','peon.dispatch.status').order('created_at',{ascending:false}).limit(1000),
      supabaseAdmin.from('edunixo_user_notifications').select('id,title,body,notification_type,is_read,created_at').eq('school_id',actor.schoolId).eq('recipient_user_id',actor.userId).order('created_at',{ascending:false}).limit(100)
    ]);const errs=[visitors.error,students.error,staff.error,dispatches.error,deliveryLogs.error,notifications.error].filter(Boolean) as any[];if(errs.length)return res.status(503).json({error:'One or more Peon operational cloud owners are not installed for this school.',details:errs[0]?.message});const deliveryMap=new Map<string,any>();for(const log of deliveryLogs.data||[]){const id=String(log.metadata?.dispatch_id||'');if(id&&!deliveryMap.has(id))deliveryMap.set(id,log);}return res.json({
      visitors:(visitors.data||[]).map((v:any)=>({id:String(v.id),visitDate:v.visit_date,visitorName:v.visitor_name,organization:v.organization,purpose:v.purpose,contactNumber:v.contact_number,inTime:v.in_time,outTime:v.out_time,metWith:v.met_with})),
      studentPasses:(students.data||[]).map((p:any)=>({id:String(p.id),passNo:p.pass_no,studentName:p.student_name,grNumber:p.gr_number,className:p.class_name,divisionName:p.division_name,reason:p.reason,timeOut:p.time_out,expectedReturn:p.expected_return,actualReturn:p.actual_return,status:p.status})),
      staffPasses:(staff.data||[]).map((p:any)=>({id:String(p.id),passNo:p.pass_no,staffName:p.staff_name,employeeCode:p.employee_code,reason:p.reason,timeOut:p.time_out,expectedReturn:p.expected_return,actualReturn:p.actual_return,status:p.status})),
      dispatches:(dispatches.data||[]).map((d:any)=>{const latest=deliveryMap.get(String(d.id));return{id:String(d.id),dispatchNo:d.dispatch_no,dispatchDate:d.dispatch_date,subject:d.subject,partyName:d.party_name,deliveryMode:d.delivery_mode,status:latest?.metadata?.status||d.status||'recorded',deliveryRemarks:latest?.metadata?.remarks||null,deliveryUpdatedAt:latest?.created_at||null};}),
      notifications:(notifications.data||[]).map((n:any)=>({id:String(n.id),title:n.title,body:n.body,type:n.notification_type,isRead:Boolean(n.is_read),createdAt:n.created_at})),
      summary:{visitorsInside:(visitors.data||[]).filter((v:any)=>!v.out_time).length,studentsOut:(students.data||[]).filter((p:any)=>p.status==='out').length,staffOut:(staff.data||[]).filter((p:any)=>p.status==='out').length,pendingDispatch:(dispatches.data||[]).filter((d:any)=>!['delivered','returned'].includes(String(deliveryMap.get(String(d.id))?.metadata?.status||d.status||''))).length,unreadNotices:(notifications.data||[]).filter((n:any)=>!n.is_read).length}
    });}catch(error:any){return res.status(500).json({error:error?.message||'Peon Operations could not be loaded.'});}
  });

