  const mariaAcademicNorm = (value: unknown) => String(value ?? '').trim().toLowerCase()
    .replace(/^class\s+/, '').replace(/[^a-z0-9\u0900-\u097f\u0600-\u06ff]+/g, ' ').replace(/\s+/g, ' ').trim();

  async function resolveMariaAssignedSubject(activeUser: ActiveUserContext, args: any = {}) {
    if (!['teacher','class_teacher','headmaster'].includes(activeUser.role)) {
      return { status:'forbidden', message:'This Maria academic action is available only to an assigned Teacher/Class Teacher/Headmaster teaching account.' } as any;
    }
    const comm:any = await loadTeacherCommunicationScopes(activeUser);
    const scopes:any[] = (comm.scopes || []).filter((row:any) => row.scopeType === 'subject');
    if (!scopes.length) return { status:'not_found', message:'No active Headmaster-assigned teaching subject was found for this account.' } as any;
    const assignmentId = safePublicText(args?.assignmentId, 140);
    const requestedSubject = mariaAcademicNorm(args?.subjectName);
    const requestedClass = mariaAcademicNorm(args?.className);
    const requestedDivision = mariaAcademicNorm(args?.division);
    let candidates = scopes.filter((scope:any) => {
      if (assignmentId && String(scope.assignmentId || '') !== assignmentId) return false;
      const subject = mariaAcademicNorm(scope.subjectName);
      const className = mariaAcademicNorm(scope.className);
      const division = mariaAcademicNorm(scope.division);
      if (requestedSubject && !(subject === requestedSubject || subject.includes(requestedSubject) || requestedSubject.includes(subject))) return false;
      if (requestedClass && !(className === requestedClass || className.includes(requestedClass) || requestedClass.includes(className))) return false;
      if (requestedDivision && !(division === requestedDivision || division.includes(requestedDivision) || requestedDivision.includes(division))) return false;
      return true;
    });
    if (!assignmentId && !requestedSubject && !requestedClass && !requestedDivision) candidates = scopes;
    if (!candidates.length) return { status:'not_found', message:"That Class / Division / Subject is not in this account's current Headmaster-assigned teaching scope." } as any;
    if (candidates.length > 1) {
      return { status:'ambiguous', message:'More than one assigned subject matches. Ask the user which Class/Division they mean.', candidates:candidates.slice(0,8).map((scope:any)=>({assignmentId:String(scope.assignmentId||''),className:String(scope.className||''),division:String(scope.division||''),subjectName:String(scope.subjectName||'')})) } as any;
    }
    const scope=candidates[0];
    return { status:'ready', assignmentId:String(scope.assignmentId||''), className:String(scope.className||''), division:String(scope.division||''), subjectName:String(scope.subjectName||''), subjectId:String(scope.subjectId||'') } as any;
  }

  function normalizeMariaMarkValue(raw: unknown) {
    const original = String(raw ?? '').trim();
    if (!original) return '';
    const asciiDigits = original
      .replace(/[०-९]/g, (ch) => String('०१२३४५६७८९'.indexOf(ch)))
      .replace(/[٠-٩]/g, (ch) => String('٠١٢٣٤٥٦٧٨٩'.indexOf(ch)))
      .replace(/[۰-۹]/g, (ch) => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(ch)));
    const n = mariaAcademicNorm(asciiDigits);
    if (['absent','ab','abs','gair hazir','gairhazir','गैरहाजिर','गैर हाजिर','अनुपस्थित','غیر حاضر','غائب'].includes(n)) return 'AB';
    if (['medical leave','ml'].includes(n)) return 'ML';
    if (['exempt','ex'].includes(n)) return 'EX';
    if (['withheld','wh'].includes(n)) return 'WH';
    if (['not applicable','na'].includes(n)) return 'NA';
    if (/^-?\d+(?:\.\d+)?$/.test(asciiDigits)) return asciiDigits;

    // Safety net for common dictated Hindi/Hinglish/Urdu number words. Gemini is
    // instructed to send digits, but this prevents a harmless STT spelling variant
    // (for example panch/aath/chhe/tera) from interrupting fast mark entry.
    const wordNumbers: Record<string,string> = {
      zero:'0', shunya:'0', sunya:'0', sifar:'0', shoonya:'0',
      ek:'1', one:'1', do:'2', two:'2', teen:'3', tin:'3', three:'3', char:'4', chaar:'4', four:'4',
      panch:'5', paanch:'5', five:'5', chhe:'6', chhah:'6', chha:'6', che:'6', six:'6',
      sat:'7', saat:'7', seven:'7', aath:'8', aanth:'8', ath:'8', eight:'8', nau:'9', nao:'9', nine:'9',
      das:'10', dus:'10', ten:'10', gyarah:'11', gyaarah:'11', eleven:'11', barah:'12', baarah:'12', twelve:'12',
      tera:'13', terah:'13', thirteen:'13', chaudah:'14', choudah:'14', fourteen:'14', pandrah:'15', fifteen:'15',
      solah:'16', sixteen:'16', satrah:'17', seventeen:'17', atharah:'18', attharah:'18', eighteen:'18',
      unnis:'19', unees:'19', nineteen:'19', bees:'20', bis:'20', twenty:'20',
      ikkis:'21', ikkees:'21', bais:'22', baees:'22', teis:'23', teees:'23', chaubis:'24', chaubees:'24',
      pachis:'25', pachees:'25', chhabbis:'26', chhabbees:'26', sattais:'27', sattaees:'27',
      atthais:'28', atthaees:'28', untis:'29', untees:'29', tees:'30'
    };
    if (wordNumbers[n] != null) return wordNumbers[n];
    return asciiDigits.toUpperCase().slice(0,20);
  }

  async function mariaFeatureSummary(activeUser: ActiveUserContext, rawFeature: string, args: any = {}) {
    if (!supabaseAdmin) throw new Error('Classtago data service is unavailable.');
    const feature = String(rawFeature || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
    const role = String(activeUser.role || '').toLowerCase();
    const today = edunixoSchoolDateKey();
    try {
      if (feature === 'attendance') {
        if (role === 'student' || role === 'parent') {
          const ctx = await resolveStudentPortalContext(activeUser, role === 'parent' ? safePublicText(args?.studentId, 120) || null : null);
          const read = await supabaseAdmin.from('edunixo_attendance_entries').select('attendance_date,status').eq('school_id',activeUser.schoolId).eq('student_id',ctx.studentId).order('attendance_date',{ascending:false}).limit(40);
          if (read.error) throw read.error;
          const rows:any[] = read.data || []; const counts:any = {};
          for (const row of rows) { const k=String(row.status||'Unknown').toUpperCase(); counts[k]=(counts[k]||0)+1; }
          return { status:'ok', student:{id:ctx.studentId,name:ctx.profile.fullName,className:ctx.className,division:ctx.divisionName}, recentDays:rows.length, counts, latest:rows.slice(0,10) };
        }
        let q:any = supabaseAdmin.from('edunixo_attendance_entries').select('student_id,status,class_id,division_id,attendance_date').eq('school_id',activeUser.schoolId).eq('attendance_date',today).limit(20000);
        if (role === 'teacher' || role === 'class_teacher') {
          const comm:any = await loadTeacherCommunicationScopes(activeUser);
          const classScopes=(comm.scopes||[]).filter((x:any)=>x.scopeType==='class_teacher');
          const classIds=[...new Set(classScopes.map((x:any)=>String(x.classId||'')).filter(Boolean))];
          if (!classIds.length) return { status:'not_class_teacher', date:today, message:'Daily attendance is available only for the Headmaster-assigned Class Teacher scope.' };
          q=q.in('class_id',classIds);
        }
        const read=await q; if(read.error) throw read.error;
        const rows:any[]=read.data||[]; const counts:any={};
        for(const row of rows){const k=String(row.status||'Unknown').toUpperCase();counts[k]=(counts[k]||0)+1;}
        return {status:'ok',date:today,total:rows.length,counts};
      }

      if (feature === 'timetable') {
        if (['teacher','class_teacher','headmaster'].includes(role)) {
          const teacher=await resolveTeacherRecordForActiveUser(activeUser); if(!teacher?.id) return {status:'unavailable',message:'Teacher Master record is not linked to this login.'};
          const read=await supabaseAdmin.from('edunixo_published_timetable_entries').select('*').eq('school_id',activeUser.schoolId).limit(5000); if(read.error) throw read.error;
          const teacherNorm=normalizeServerPersonName(teacher.full_name);
          const rows=(read.data||[]).filter((row:any)=>(row.teacher_user_id&&String(row.teacher_user_id)===activeUser.userId)||(row.teacher_record_id&&String(row.teacher_record_id)===String(teacher.id))||(teacherNorm&&normalizeServerPersonName(row.teacher_name)===teacherNorm));
          const weekday=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Kolkata',weekday:'long'}).format(new Date());
          return {status:'ok',today:weekday,todayRows:rows.filter((r:any)=>String(r.day_name||r.day||'').toLowerCase()===weekday.toLowerCase()).slice(0,20).map((r:any)=>({period:Number(r.period_no||r.period||0),startTime:r.start_time||null,endTime:r.end_time||null,className:r.class_name||'',division:r.division_name||r.division||'',subject:r.subject_name||''})),weekCount:rows.length};
        }
        if (role==='student'||role==='parent') {
          const ctx=await resolveStudentPortalContext(activeUser,role==='parent'?safePublicText(args?.studentId,120)||null:null);
          let q:any=supabaseAdmin.from('edunixo_published_timetable_entries').select('*').eq('school_id',activeUser.schoolId).limit(1000);
          if(ctx.classId)q=q.eq('class_id',ctx.classId); if(ctx.divisionId)q=q.eq('division_id',ctx.divisionId);
          const read=await q; if(read.error) throw read.error;
          const weekday=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Kolkata',weekday:'long'}).format(new Date());
          const rows:any[]=read.data||[];
          return {status:'ok',student:{id:ctx.studentId,name:ctx.profile.fullName},today:weekday,todayRows:rows.filter((r:any)=>String(r.day_name||r.day||'').toLowerCase()===weekday.toLowerCase()).slice(0,20).map((r:any)=>({period:Number(r.period_no||r.period||0),startTime:r.start_time||null,endTime:r.end_time||null,subject:r.subject_name||'',teacher:r.teacher_name||''})),weekCount:rows.length};
        }
      }

      if (feature === 'study_material') {
        if (!['teacher','class_teacher','headmaster'].includes(role)) return {status:'open_module',message:'Use the Student/Parent Study Material module for published material.'};
        const read=await supabaseAdmin.from('edunixo_study_materials').select('id,title,category,kind,subject_name,class_name,archived,extraction_status,updated_at').eq('school_id',activeUser.schoolId).eq('owner_teacher_id',activeUser.userId).order('updated_at',{ascending:false}).limit(120); if(read.error) throw read.error;
        const rows:any[]=(read.data||[]).filter((x:any)=>!x.archived); const byCategory:any={}; for(const r of rows){const k=String(r.category||r.kind||'other');byCategory[k]=(byCategory[k]||0)+1;}
        return {status:'ok',total:rows.length,byCategory,recent:rows.slice(0,8)};
      }

      if (feature === 'academic_plans' || feature === 'homework') {
        if (!['teacher','class_teacher','headmaster'].includes(role)) return {status:'forbidden',message:'Teacher academic work is not available to this role.'};
        const kinds=feature==='homework'?['homework']:['year-plan','daily-teaching-plan','lesson-plan','teaching-diary-assist','classwork-assignment'];
        const read=await supabaseAdmin.from('edunixo_academic_records').select('id,kind,title,status,class_name,division_name,subject_name,updated_at').eq('school_id',activeUser.schoolId).eq('owner_teacher_id',activeUser.userId).in('kind',kinds).order('updated_at',{ascending:false}).limit(120); if(read.error) throw read.error;
        const rows:any[]=read.data||[]; const byKind:any={}; const byStatus:any={}; for(const r of rows){byKind[r.kind]=(byKind[r.kind]||0)+1;byStatus[r.status||'unknown']=(byStatus[r.status||'unknown']||0)+1;}
        return {status:'ok',total:rows.length,byKind,byStatus,recent:rows.slice(0,10)};
      }

      if (feature === 'question_paper') {
        if (!['teacher','class_teacher','headmaster'].includes(role)) return {status:'forbidden',message:'Question Paper tools require an assigned teaching role.'};
        const read=await supabaseAdmin.from('edunixo_question_papers').select('id,title,exam,total_marks,duration_minutes,review_status,updated_at,owner_teacher_id').eq('owner_teacher_id',activeUser.userId).order('updated_at',{ascending:false}).limit(80); if(read.error) throw read.error;
        return {status:'ok',total:(read.data||[]).length,recent:(read.data||[]).slice(0,10)};
      }

      if (feature === 'results') {
        if (['teacher','class_teacher','headmaster'].includes(role)) {
          let q:any=supabaseAdmin.from('edunixo_result_subject_lists').select('id,term,status,subject_name,class_id,division_id,updated_at,teacher_user_id').eq('school_id',activeUser.schoolId).order('updated_at',{ascending:false}).limit(5000);
          if(role!=='headmaster')q=q.eq('teacher_user_id',activeUser.userId);
          const read=await q; if(read.error) throw read.error; const rows:any[]=read.data||[];const byStatus:any={};for(const r of rows){const k=String(r.status||'unknown');byStatus[k]=(byStatus[k]||0)+1;}
          return {status:'ok',total:rows.length,byStatus,recent:rows.slice(0,10)};
        }
        if(role==='student'||role==='parent') {
          const ctx=await resolveStudentPortalContext(activeUser,role==='parent'?safePublicText(args?.studentId,120)||null:null);
          const read=await supabaseAdmin.from('edunixo_progress_card_batches').select('id,term,status,updated_at,payload').eq('school_id',activeUser.schoolId).eq('status','final').order('updated_at',{ascending:false}).limit(300); if(read.error) throw read.error;
          const rows=(read.data||[]).filter((r:any)=>r?.payload?.rows&&Object.prototype.hasOwnProperty.call(r.payload.rows,ctx.studentId));
          return {status:'ok',student:{id:ctx.studentId,name:ctx.profile.fullName},publishedProgressCards:rows.length,latest:rows.slice(0,4).map((r:any)=>({id:r.id,term:r.term,updatedAt:r.updated_at}))};
        }
      }

      if (feature === 'my_students') {
        if (!['teacher','class_teacher','headmaster'].includes(role)) return {status:'forbidden',message:'My Students is available to assigned teaching roles only.'};
        const comm:any=await loadTeacherCommunicationScopes(activeUser); const scopes=(comm.scopes||[]).filter((x:any)=>x.scopeType==='subject').slice(0,40); const summaries=[];
        for(const scope of scopes.slice(0,12)){
          try{const roster:any=await loadTeacherAuthorizedRoster(activeUser,{classId:scope.classId,className:scope.className,divisionId:scope.divisionId||null,divisionName:scope.division||'',subjectId:scope.subjectId,academicYearId:scope.academicYearId||null});summaries.push({className:scope.className,division:scope.division,subject:scope.subjectName,students:(roster.students||[]).length});}catch{}
        }
        return {status:'ok',scopes:summaries,totalAcrossScopes:summaries.reduce((n:number,x:any)=>n+Number(x.students||0),0)};
      }

      if (feature === 'communication' || feature === 'notices') {
        const read=await supabaseAdmin.from('edunixo_user_notifications').select('title,body,notification_type,is_read,created_at').eq('school_id',activeUser.schoolId).eq('recipient_user_id',activeUser.userId).order('created_at',{ascending:false}).limit(20); if(read.error) throw read.error;
        const rows:any[]=read.data||[]; return {status:'ok',unread:rows.filter(r=>!r.is_read).length,recent:rows.slice(0,10)};
      }

      if (feature === 'leave') {
        const requested=await supabaseAdmin.from('audit_logs').select('id,action,summary,metadata,created_at').eq('school_id',activeUser.schoolId).eq('actor_user_id',activeUser.userId).in('action',['leave.application.requested','staff.leave.requested','teacher.leave.requested']).order('created_at',{ascending:false}).limit(50);
        if(requested.error) throw requested.error; return {status:'ok',requests:(requested.data||[]).slice(0,12)};
      }

      if (feature === 'admissions') {
        if (role==='headmaster'||role==='clerk') {
          const read=await supabaseAdmin.from('school_admission_applications').select('id,reference_code,student_name,class_applying,status,created_at').eq('school_id',activeUser.schoolId).order('created_at',{ascending:false}).limit(1000); if(read.error) throw read.error; const rows:any[]=read.data||[];const byStatus:any={};for(const r of rows){const k=String(r.status||'unknown').toLowerCase();byStatus[k]=(byStatus[k]||0)+1;}return {status:'ok',total:rows.length,byStatus,recent:rows.slice(0,10)};
        }
        if(role==='student'||role==='parent') {
          const ctx=await resolveStudentPortalContext(activeUser,role==='parent'?safePublicText(args?.studentId,120)||null:null); if(!ctx.admissionApplicationId)return {status:'none',message:'No linked confirmed admission application was found for this Student.'};
          const read=await supabaseAdmin.from('school_admission_applications').select('reference_code,status,class_applying,created_at').eq('id',ctx.admissionApplicationId).eq('school_id',activeUser.schoolId).maybeSingle(); if(read.error)throw read.error; return {status:'ok',student:{id:ctx.studentId,name:ctx.profile.fullName},application:read.data||null};
        }
      }

      if (feature === 'fees') {
        if(role==='student'||role==='parent') {
          const ctx=await resolveStudentPortalContext(activeUser,role==='parent'?safePublicText(args?.studentId,120)||null:null);
          const read=await supabaseAdmin.from('edunixo_fee_transactions').select('id,receipt_no,amount,payment_date,status').eq('school_id',activeUser.schoolId).eq('student_id',ctx.studentId).order('payment_date',{ascending:false}).limit(200); if(read.error) throw read.error; const rows:any[]=read.data||[]; const paid=rows.filter(r=>String(r.status||'active')!=='cancelled').reduce((n,r)=>n+Number(r.amount||0),0); return {status:'ok',student:{id:ctx.studentId,name:ctx.profile.fullName},receiptCount:rows.length,recordedPaidAmount:paid,recent:rows.slice(0,10),note:'Outstanding dues are not inferred unless the canonical fee profile explicitly supplies them.'};
        }
        if(role==='headmaster'||role==='clerk') {
          const read=await supabaseAdmin.from('edunixo_fee_transactions').select('id,amount,status,payment_date').eq('school_id',activeUser.schoolId).order('payment_date',{ascending:false}).limit(10000); if(read.error) throw read.error; const rows:any[]=read.data||[]; return {status:'ok',receiptCount:rows.length,activeAmount:rows.filter(r=>String(r.status||'active')!=='cancelled').reduce((n,r)=>n+Number(r.amount||0),0),cancellationPending:rows.filter(r=>String(r.status)==='cancellation_pending').length};
        }
      }

      if (feature === 'parent_portal' && role === 'parent') {
        const approvedIds = await loadApprovedParentStudentIds(activeUser.schoolId, activeUser.userId);
        const students = approvedIds.length
          ? await supabaseAdmin.from('students').select('id,full_name,name_en,name,gr_number,current_class_name,class_name,current_division_name,division_name,division,status,is_active').eq('school_id', activeUser.schoolId).in('id', approvedIds)
          : ({ data: [], error: null } as any);
        if (students.error) throw students.error;
        return {
          status:'ok',
          linkedChildren:(students.data||[]).length,
          children:(students.data||[]).map((row:any)=>({
            id:String(row.id),
            name:safePublicText(row.full_name||row.name_en||row.name,180)||'Student',
            grNumber:safePublicText(row.gr_number,80),
            className:safePublicText(row.current_class_name||row.class_name,80),
            division:safePublicText(row.current_division_name||row.division_name||row.division,80),
            status:safePublicText(row.status||(row.is_active===false?'Inactive':'Active'),60)
          }))
        };
      }

      if (feature === 'receptionist') {
        const school=await loadUniversalAssistantContext(activeUser);
        const campaign=await supabaseAdmin.from('school_admission_campaigns').select('id,title,session_name,status,start_date,end_date').eq('school_id',activeUser.schoolId).eq('status','active').order('created_at',{ascending:false}).limit(1).maybeSingle();
        return {status:'ok',school:school.school,admissionCampaign:campaign.error?null:campaign.data||null,note:'Maria must answer only from verified school data; missing fees/timings/policies must not be invented.'};
      }

      return {status:'open_module',message:'This feature is available through its existing Classtago module.',route:mariaFeatureRoute(activeUser,feature)};
    } catch (error:any) {
      return {status:'unavailable',feature,message:safePublicText(error?.message,300)||'This live ERP summary is not available right now.',route:mariaFeatureRoute(activeUser,feature)};
    }
  }

  // R2.5.86 — Maria confirmation-gated operational action layer.
  // Prepared actions are persisted in audit_logs and expire quickly. The action
  // must be confirmed in a later user turn (or from the explicit Confirm button)
  // before any communication write is executed.
  const MARIA_ACTION_TTL_MS = 10 * 60 * 1000;
  const mariaActionExecutionLocks = new Set<string>();
  const MARIA_OPERATIONAL_CHANNELS = new Set(['website','whatsapp','email']);

  function mariaSpokenNameInstruction() {
    return 'NAME PRONUNCIATION: Your visible name is Maria. Whenever you say your own name aloud, pronounce it as “Maa-ree-yaa” (मारिया), three clear syllables with a long Maa. Never pronounce it as “मरिया”, “Mariya”, “Mar-ya” or “mə-RYE-ə”. Keep the written/displayed name as Maria.';
  }

  function mariaNormalizeChannel(raw: unknown) {
    const channel = String(raw || '').trim().toLowerCase().replace(/app|in[- ]?app/g,'website');
    return MARIA_OPERATIONAL_CHANNELS.has(channel) ? channel : '';
  }

  function mariaResolveByNameOrGr(rows: any[], args: any) {
    const studentId = safePublicText(args?.studentId, 120);
    const gr = normalizeAssistantContactName(safePublicText(args?.grNumber, 100));
    const name = normalizeAssistantContactName(safePublicText(args?.studentName, 180));
    if (studentId) {
      const row = rows.find((item: any) => String(item.id || item.studentId || '') === studentId);
      return row ? { row } : { status:'not_found', message:'That Student record is not available in your authorised school scope.' };
    }
    if (gr) {
      const matches = rows.filter((item: any) => normalizeAssistantContactName(item.grNumber || item.gr_number || '') === gr);
      if (matches.length === 1) return { row: matches[0] };
      if (matches.length > 1) return { status:'ambiguous', candidates:matches.slice(0,8).map((x:any)=>({id:String(x.id||x.studentId||''),name:String(x.name||x.studentName||x.full_name||'Student'),grNumber:String(x.grNumber||x.gr_number||'')})) };
    }
    if (!name) return { status:'needs_student', message:'Please say the Student name or GR number.' };
    const targetTokens = name.split(' ').filter(Boolean);
    const scored = rows.map((row: any) => {
      const displayName = String(row.name || row.studentName || row.full_name || row.name_en || '').trim();
      const normalized = normalizeAssistantContactName(displayName);
      const candidateTokens = new Set(normalized.split(' ').filter(Boolean));
      const overlap = targetTokens.filter((token: string) => candidateTokens.has(token)).length;
      let score = 0;
      if (normalized === name) score = 100;
      else if (normalized.startsWith(name) || name.startsWith(normalized)) score = 90;
      else if (normalized.includes(name) || name.includes(normalized)) score = 82;
      else if (targetTokens.length && overlap === targetTokens.length) score = 76;
      else if (overlap > 0) score = 45 + overlap * 8;
      return { row, displayName, score };
    }).filter((item: any) => item.displayName && item.score >= 60)
      .sort((a: any,b: any) => b.score - a.score || a.displayName.localeCompare(b.displayName));
    if (!scored.length) return { status:'not_found', message:`No authorised Student match was found for ${safePublicText(args?.studentName,180) || 'that name'}.` };
    const best = scored[0].score;
    const close = scored.filter((item: any) => item.score >= best - 4).slice(0,8);
    if (close.length > 1) return { status:'ambiguous', candidates:close.map((item:any)=>({id:String(item.row.id||item.row.studentId||''),name:item.displayName,grNumber:String(item.row.grNumber||item.row.gr_number||'')})) };
    return { row: close[0].row };
  }

  function mariaAbsenceMessage(languageCode: string, date: string) {
    const lang = String(languageCode || 'en').toLowerCase();
    if (lang === 'hi') return `प्रिय अभिभावक, आपके बच्चे को आज ${date} को स्कूल उपस्थिति में अनुपस्थित दर्ज किया गया है। यदि कोई कारण या जानकारी स्कूल/कक्षा शिक्षक को बतानी हो तो कृपया संपर्क करें। धन्यवाद।`;
    if (lang === 'ur') return `محترم والدین/سرپرست، آج ${date} کو آپ کے بچے کی اسکول حاضری غیر حاضر درج ہوئی ہے۔ اگر کوئی وجہ یا ضروری اطلاع اسکول یا کلاس ٹیچر کو دینی ہو تو براہِ کرم رابطہ کریں۔ شکریہ۔`;
    if (lang === 'mr') return `आदरणीय पालक, आज ${date} रोजी आपल्या मुलाची/मुलीची शाळेतील उपस्थिती अनुपस्थित नोंदली आहे. काही कारण किंवा माहिती शाळेला/वर्गशिक्षकांना कळवायची असल्यास कृपया संपर्क करा. धन्यवाद.`;
    return `Dear Parent/Guardian, your child is marked absent in the school attendance record today (${date}). If there is any reason or information the school/class teacher should know, please contact us. Thank you.`;
  }

  function mariaFeeMessage(languageCode: string, schoolName: string, studentName: string, balance: number, academicYear: string) {
    const amount = `₹${Number(balance || 0).toLocaleString('en-IN',{maximumFractionDigits:2})}`;
    const lang = String(languageCode || 'en').toLowerCase();
    if (lang === 'hi') return `प्रिय अभिभावक, ${schoolName} के रिकॉर्ड के अनुसार ${studentName} के लिए शैक्षणिक वर्ष ${academicYear} में ${amount} स्कूल फीस शेष है। यदि भुगतान पहले ही किया जा चुका है या किसी स्पष्टीकरण की आवश्यकता है, तो कृपया स्कूल कार्यालय से संपर्क करें। धन्यवाद।`;
    if (lang === 'ur') return `محترم والدین/سرپرست، ${schoolName} کے ریکارڈ کے مطابق ${studentName} کے لیے تعلیمی سال ${academicYear} میں ${amount} اسکول فیس بقایا ہے۔ اگر ادائیگی پہلے ہو چکی ہے یا وضاحت درکار ہے تو براہِ کرم اسکول آفس سے رابطہ کریں۔ شکریہ۔`;
    if (lang === 'mr') return `आदरणीय पालक, ${schoolName} च्या नोंदीनुसार ${studentName} यांची शैक्षणिक वर्ष ${academicYear} साठी ${amount} शाळा फी बाकी आहे. पेमेंट आधीच केले असल्यास किंवा स्पष्टीकरण हवे असल्यास कृपया शाळेच्या कार्यालयाशी संपर्क करा. धन्यवाद.`;
    return `Dear Parent/Guardian, according to ${schoolName}'s records, ${studentName} has an outstanding school fee balance of ${amount} for academic year ${academicYear}. If payment has already been made or you need clarification, please contact the school office. Thank you.`;
  }

  function mariaAdmissionMessage(languageCode: string, schoolName: string, guardianName: string, studentName: string, referenceCode: string, status: string) {
    const lang = String(languageCode || 'en').toLowerCase();
    if (lang === 'hi') return `प्रिय ${guardianName || 'अभिभावक'}, ${schoolName} से ${studentName} के प्रवेश आवेदन ${referenceCode} के संबंध में संपर्क किया जा रहा है। हमारे रिकॉर्ड में वर्तमान स्थिति “${status}” है। यदि किसी दस्तावेज़, जानकारी या सहायता की आवश्यकता हो तो कृपया स्कूल से संपर्क करें।`;
    if (lang === 'ur') return `محترم ${guardianName || 'والدین/سرپرست'}، ${schoolName} کی طرف سے ${studentName} کی داخلہ درخواست ${referenceCode} کے سلسلے میں رابطہ کیا جا رہا ہے۔ ہمارے ریکارڈ میں موجودہ حیثیت “${status}” ہے۔ کسی دستاویز، معلومات یا مدد کی ضرورت ہو تو براہِ کرم اسکول سے رابطہ کریں۔`;
    if (lang === 'mr') return `आदरणीय ${guardianName || 'पालक'}, ${schoolName} कडून ${studentName} यांच्या प्रवेश अर्ज ${referenceCode} संदर्भात हा फॉलो-अप आहे. आमच्या नोंदीनुसार सध्याची स्थिती “${status}” आहे. कोणतेही कागदपत्र, माहिती किंवा मदत आवश्यक असल्यास कृपया शाळेशी संपर्क करा.`;
    return `Dear ${guardianName || 'Parent/Guardian'}, this is a follow-up from ${schoolName} regarding admission application ${referenceCode} for ${studentName}. The current status in our records is “${status}”. Please contact the school if you need help with any document or information.`;
  }

  async function mariaStorePreparedAction(activeUser: ActiveUserContext, actionType: string, payload: any, summary: string, confirmationLabel: string) {
    if (!supabaseAdmin) throw new Error('Maria action service is unavailable.');
    const expiresAt = new Date(Date.now() + MARIA_ACTION_TTL_MS).toISOString();
    const write = await supabaseAdmin.from('audit_logs').insert({
      school_id: activeUser.schoolId,
      actor_user_id: activeUser.userId,
      actor_kind: 'school_user',
      action: 'ai.maria.action.prepared',
      entity_type: 'maria_action',
      entity_id: null,
      summary: safePublicText(summary, 600),
      metadata: { action_type: actionType, status:'pending', expires_at:expiresAt, payload }
    }).select('id,created_at').single();
    if (write.error) throw write.error;
    const actionId = String(write.data?.id || '');
    return {
      result: {
        status:'confirmation_required', actionId, actionType, summary:safePublicText(summary,600), expiresAt,
        message:'The action is prepared but has not been sent or published. Wait for the user to explicitly confirm before completing it.'
      },
      clientAction: { type:'confirm', label:confirmationLabel || 'Confirm action', actionId, title:'Confirm Maria action', summary:safePublicText(summary,600) }
    };
  }

  async function mariaActionState(activeUser: ActiveUserContext, actionId: string) {
    if (!supabaseAdmin) throw new Error('Maria action service is unavailable.');
    const prepared = await supabaseAdmin.from('audit_logs').select('*')
      .eq('id', actionId).eq('school_id', activeUser.schoolId).eq('actor_user_id', activeUser.userId)
      .eq('action','ai.maria.action.prepared').maybeSingle();
    if (prepared.error) throw prepared.error;
    if (!prepared.data) return { status:'not_found', prepared:null, completed:null };
    const [completed, cancelled] = await Promise.all([
      supabaseAdmin.from('audit_logs').select('id,summary,metadata,created_at')
        .eq('school_id', activeUser.schoolId).eq('actor_user_id', activeUser.userId)
        .eq('action','ai.maria.action.completed').eq('entity_id',actionId).order('created_at',{ascending:false}).limit(1).maybeSingle(),
      supabaseAdmin.from('audit_logs').select('id,summary,metadata,created_at')
        .eq('school_id', activeUser.schoolId).eq('actor_user_id', activeUser.userId)
        .eq('action','ai.maria.action.cancelled').eq('entity_id',actionId).order('created_at',{ascending:false}).limit(1).maybeSingle()
    ]);
    if (completed.error) throw completed.error;
    if (cancelled.error) throw cancelled.error;
    return { status:completed.data?'completed':cancelled.data?'cancelled':'pending', prepared:prepared.data, completed:completed.data || null, cancelled:cancelled.data || null };
  }

  async function mariaLatestPendingAction(activeUser: ActiveUserContext) {
    if (!supabaseAdmin) return null;
    const preparedRead = await supabaseAdmin.from('audit_logs')
      .select('id,summary,metadata,created_at')
      .eq('school_id', activeUser.schoolId)
      .eq('actor_user_id', activeUser.userId)
      .eq('action', 'ai.maria.action.prepared')
      .order('created_at', { ascending: false })
      .limit(8);
    if (preparedRead.error) throw preparedRead.error;
    const rows: any[] = preparedRead.data || [];
    if (!rows.length) return null;
    const ids = rows.map((row: any) => String(row.id || '')).filter(Boolean);
    const terminalRead = ids.length ? await supabaseAdmin.from('audit_logs')
      .select('entity_id,action')
      .eq('school_id', activeUser.schoolId)
      .eq('actor_user_id', activeUser.userId)
      .in('action', ['ai.maria.action.completed','ai.maria.action.cancelled'])
      .in('entity_id', ids) : { data: [], error: null } as any;
    if (terminalRead.error) throw terminalRead.error;
    const terminal = new Set((terminalRead.data || []).map((row: any) => String(row.entity_id || '')));
    for (const row of rows) {
      const actionId = String(row.id || '');
      const metadata: any = row.metadata || {};
      const expiresAt = Date.parse(String(metadata.expires_at || ''));
      if (!actionId || terminal.has(actionId) || !Number.isFinite(expiresAt) || expiresAt <= Date.now()) continue;
      return {
        actionId,
        actionType: safePublicText(metadata.action_type, 100),
        summary: safePublicText(row.summary, 600),
        expiresAt: new Date(expiresAt).toISOString()
      };
    }
    return null;
  }

  async function mariaSendHeadmasterTargetedCommunication(activeUser: ActiveUserContext, input: any) {
    if (!supabaseAdmin) throw new Error('Communication service is unavailable.');
    if (activeUser.role !== 'headmaster') throw new Error('Only an authorised Headmaster can send this Maria communication.');
    const title = safePublicText(input?.title, 300);
    const body = safePublicText(input?.body, 12000);
    const channels = Array.from(new Set((Array.isArray(input?.channels)?input.channels:[]).map(mariaNormalizeChannel).filter(Boolean)));
    const recipients = Array.isArray(input?.recipients) ? input.recipients : [];
    if (!title || !body || !channels.length || !recipients.length) throw new Error('Maria communication title, message, channel and recipient are required.');
    const readiness: any = await readHeadmasterChannelReadiness(activeUser.schoolId);
    const unavailable = channels.filter((channel:string)=>readiness[channel] !== true);
    if (unavailable.length) throw new Error(`${unavailable.join(', ')} is not configured for this school/server yet.`);
    const usableRecipients = recipients.filter((row:any)=>channels.some((channel:string)=>channel==='website'?Boolean(row.recipientUserId):channel==='email'?Boolean(row.recipientEmail):Boolean(row.recipientMobile)));
    if (!usableRecipients.length) throw new Error('The selected communication channel has no reachable recipient record.');
    let academicYear:any=null; try { academicYear=await resolveClerkAcademicYear(activeUser.schoolId,null); } catch {}
    const created = await supabaseAdmin.from('edunixo_communication_messages').insert({
      school_id:activeUser.schoolId, academic_year_id:academicYear?.id||null, academic_year:academicYear?.year||null,
      created_by:activeUser.userId, created_by_teacher_record_id:null, created_by_name:'Headmaster', system_generated:true,
      message_type:'announcement', title, body, channels, recipient_count:usableRecipients.length,
      source_key:`maria-communication:${activeUser.schoolId}:${randomUUID()}`, status:'queued', audience_type:safePublicText(input?.audienceType,100)||'parent',
      language_code:safePublicText(input?.languageCode,20)||'en', language_name:safePublicText(input?.languageName,80)||'Maria',
      priority:['normal','high','urgent'].includes(String(input?.priority||'').toLowerCase())?String(input.priority).toLowerCase():'normal',
      metadata:{headmaster_owned:true,maria_generated:true,maria_purpose:safePublicText(input?.purpose,80)||'operational_followup',schedule_state:'ready'}
    }).select('id').single();
    if (created.error) throw created.error;
    const messageId=String(created.data.id);
    const recipientRows=usableRecipients.map((row:any)=>({
      message_id:messageId, school_id:activeUser.schoolId, recipient_student_id:row.recipientStudentId||null,
      recipient_teacher_record_id:row.recipientTeacherRecordId||null, recipient_user_id:row.recipientUserId||null,
      recipient_name:safePublicText(row.recipientName,240)||'Recipient', recipient_mobile:safePublicText(row.recipientMobile,80)||null,
      recipient_email:safePublicText(row.recipientEmail,320)||null, audience_kind:safePublicText(row.audienceKind,80)||'parent_guardian', preferred_language:row.preferredLanguage||null
    }));
    for(let i=0;i<recipientRows.length;i+=500){const write=await supabaseAdmin.from('edunixo_communication_recipients').insert(recipientRows.slice(i,i+500));if(write.error)throw write.error;}
    const dispatch=await dispatchHeadmasterCommunication(activeUser.schoolId,messageId);
    return {messageId,recipientCount:usableRecipients.length,dispatch};
  }

  async function prepareMariaAbsenceFollowup(activeUser: ActiveUserContext, args: any) {
    if (!supabaseAdmin) throw new Error('Attendance follow-up service is unavailable.');
    const role=String(activeUser.role||'').toLowerCase();
    if (!['teacher','class_teacher','headmaster'].includes(role)) return {result:{status:'forbidden',message:'Absence parent follow-up is available only to an authorised Class Teacher or Headmaster.'}};
    const date=edunixoSchoolDateKey();
    const channel=mariaNormalizeChannel(args?.channel) || 'website';
    const languageCode=safePublicText(args?.languageCode,20).toLowerCase()||'en';
    const title=languageCode==='hi'?'आज की अनुपस्थिति सूचना':languageCode==='ur'?'آج کی غیر حاضری کی اطلاع':languageCode==='mr'?'आजची अनुपस्थिती सूचना':'Attendance follow-up';
    const body=mariaAbsenceMessage(languageCode,date);

    if(role==='headmaster'){
      const attendance=await supabaseAdmin.from('edunixo_attendance_entries').select('student_id,status').eq('school_id',activeUser.schoolId).eq('attendance_date',date).limit(20000);
      if(attendance.error)throw attendance.error;
      const absentIds=new Set((attendance.data||[]).filter((r:any)=>['a','absent'].includes(String(r.status||'').trim().toLowerCase())).map((r:any)=>String(r.student_id||'')).filter(Boolean));
      if(!absentIds.size)return {result:{status:'none',date,message:'No Student is currently marked absent for today.'}};
      const master=await loadClerkStudentMaster(activeUser.schoolId);
      let students=(master.students||[]).filter((s:any)=>absentIds.has(String(s.id)));
      if(args?.studentId||args?.grNumber||args?.studentName){const resolved=mariaResolveByNameOrGr(students,args);if(!resolved.row)return {result:resolved};students=[resolved.row];}
      const ids=new Set(students.map((s:any)=>String(s.id)));
      const allParents=await loadHeadmasterCommunicationAudience(activeUser.schoolId,['parent']);
      const recipients=(allParents||[]).filter((r:any)=>ids.has(String(r.recipientStudentId||'')));
      const reachable=recipients.filter((r:any)=>channel==='website'?Boolean(r.recipientUserId):channel==='email'?Boolean(r.recipientEmail):Boolean(r.recipientMobile));
      if(!reachable.length)return {result:{status:'unreachable',channel,studentCount:students.length,message:`No selected absent Student has a reachable Parent/Guardian on ${channel}.`}};
      const summary=`Send ${channel} attendance follow-up to ${reachable.length} Parent/Guardian recipient(s) for ${students.length} Student(s) marked absent on ${date}.`;
      return mariaStorePreparedAction(activeUser,'absence_followup_headmaster',{date,channel,languageCode,title,body,studentIds:students.map((s:any)=>String(s.id))},summary,'Confirm & send absence follow-up');
    }

    const comm:any=await loadTeacherCommunicationScopes(activeUser);
    const classScopes=(comm.scopes||[]).filter((s:any)=>s.scopeType==='class_teacher');
    if(!classScopes.length)return {result:{status:'forbidden',message:'No active Headmaster-assigned Class Teacher scope is available for this login.'}};
    const groups:any[]=[]; const allScoped:any[]=[];
    for(const scope of classScopes){
      const recipientData:any=await loadTeacherCommunicationRecipients(activeUser,String(scope.id));
      const candidates=(recipientData.recipients||[]).map((r:any)=>({...r,id:r.studentId,name:r.studentName,scopeId:String(scope.id)}));
      const ids=candidates.map((r:any)=>String(r.studentId)).filter(Boolean);
      if(!ids.length)continue;
      const attendance=await supabaseAdmin.from('edunixo_attendance_entries').select('student_id,status').eq('school_id',activeUser.schoolId).eq('attendance_date',date).in('student_id',ids);
      if(attendance.error)throw attendance.error;
      const absent=new Set((attendance.data||[]).filter((r:any)=>['a','absent'].includes(String(r.status||'').trim().toLowerCase())).map((r:any)=>String(r.student_id||'')));
      const rows=candidates.filter((r:any)=>absent.has(String(r.studentId)));
      if(rows.length){groups.push({scopeId:String(scope.id),studentIds:rows.map((r:any)=>String(r.studentId))});allScoped.push(...rows);}
    }
    if(!allScoped.length)return {result:{status:'none',date,message:'No Student in your Class Teacher scope is currently marked absent today.'}};
    let selected=allScoped;
    if(args?.studentId||args?.grNumber||args?.studentName){const resolved=mariaResolveByNameOrGr(allScoped,args);if(!resolved.row)return {result:resolved};selected=[resolved.row];}
    const readiness:any=comm.channelReadiness||{};
    if(readiness[channel]!==true)return {result:{status:'unavailable',channel,message:`${channel} is not configured for this school/server yet.`}};
    selected=selected.filter((r:any)=>channel==='website'?Boolean(r.parentUserId):channel==='email'?Boolean(r.parentEmail):Boolean(r.parentMobile));
    if(!selected.length)return {result:{status:'unreachable',channel,message:`No selected absent Student has a reachable Parent/Guardian on ${channel}.`}};
    const selectedIds=new Set(selected.map((r:any)=>String(r.studentId)));
    const selectedGroups=groups.map((g:any)=>({...g,studentIds:g.studentIds.filter((id:string)=>selectedIds.has(id))})).filter((g:any)=>g.studentIds.length);
    const summary=`Send ${channel} attendance follow-up to Parent/Guardian for ${selected.length} reachable Student(s) marked absent in your Class Teacher scope on ${date}.`;
    return mariaStorePreparedAction(activeUser,'absence_followup_teacher',{date,channel,languageCode,title,body,groups:selectedGroups},summary,'Confirm & send absence follow-up');
  }

  async function prepareMariaFeeReminder(activeUser: ActiveUserContext, args: any) {
    if (activeUser.role !== 'headmaster') return {result:{status:'forbidden',message:'Direct fee reminders from Maria require an authorised Headmaster. Clerk can use Fees + Communication draft workflow for Headmaster approval.'}};
    const snapshot:any=await buildClerkFeeSnapshot(activeUser.schoolId,null);
    const resolved=mariaResolveByNameOrGr(snapshot.profiles||[],args);
    if(!resolved.row)return {result:resolved};
    const student:any=resolved.row; const balance=Number(student.balance||0);
    if(balance<=0)return {result:{status:'no_due',studentName:student.name,balance:0,message:'The canonical Fee ledger does not show an outstanding balance for this Student.'}};
    const context=await loadUniversalAssistantContext(activeUser);
    const parents=await loadHeadmasterCommunicationAudience(activeUser.schoolId,['parent']);
    const recipients=(parents||[]).filter((r:any)=>String(r.recipientStudentId||'')===String(student.id));
    const readiness:any=await readHeadmasterChannelReadiness(activeUser.schoolId);
    let channel=mariaNormalizeChannel(args?.channel);
    if(!channel){
      if(recipients.some((r:any)=>r.recipientUserId))channel='website';
      else if(readiness.whatsapp&&recipients.some((r:any)=>r.recipientMobile))channel='whatsapp';
      else if(readiness.email&&recipients.some((r:any)=>r.recipientEmail))channel='email';
    }
    if(!channel)return {result:{status:'needs_channel',studentName:student.name,balance,available:{website:recipients.some((r:any)=>Boolean(r.recipientUserId)),whatsapp:Boolean(readiness.whatsapp&&recipients.some((r:any)=>r.recipientMobile)),email:Boolean(readiness.email&&recipients.some((r:any)=>r.recipientEmail))},message:'Choose a reachable channel: Website/App, WhatsApp or Email.'}};
    const reachable=recipients.filter((r:any)=>channel==='website'?Boolean(r.recipientUserId):channel==='email'?Boolean(r.recipientEmail):Boolean(r.recipientMobile));
    if(!readiness[channel]||!reachable.length)return {result:{status:'unreachable',channel,message:`${channel} is not configured or no reachable Parent/Guardian contact is stored for this Student.`}};
    const languageCode=safePublicText(args?.languageCode,20).toLowerCase()||'en';
    const academicYear=String(snapshot.academicYear?.year||snapshot.academicYear?.year_code||'Current Academic Year');
    const body=mariaFeeMessage(languageCode,context.school.name,student.name,balance,academicYear);
    const title=languageCode==='hi'?'स्कूल फीस रिमाइंडर':languageCode==='ur'?'اسکول فیس یاد دہانی':languageCode==='mr'?'शाळा फी स्मरणपत्र':'School fee reminder';
    const summary=`Send a ${channel} fee reminder to Parent/Guardian of ${student.name} for the canonical outstanding balance ${Number(balance).toLocaleString('en-IN')} in ${academicYear}.`;
    return mariaStorePreparedAction(activeUser,'fee_reminder',{studentId:String(student.id),balance,academicYear,channel,languageCode,title,body},summary,'Confirm & send fee reminder');
  }

  async function prepareMariaAdmissionFollowup(activeUser: ActiveUserContext, args: any) {
    if (activeUser.role !== 'headmaster') return {result:{status:'forbidden',message:'Direct applicant follow-up from Maria requires an authorised Headmaster. Clerk can continue through Admission/Communication workflow.'}};
    if(!supabaseAdmin)throw new Error('Admission service is unavailable.');
    const read=await supabaseAdmin.from('school_admission_applications').select('id,reference_code,student_name,guardian_name,mobile,email,class_applying,status,application_payload,created_at').eq('school_id',activeUser.schoolId).order('created_at',{ascending:false}).limit(1500);
    if(read.error)throw read.error;
    const rows:any[]=(read.data||[]).map((r:any)=>({...r,name:r.student_name,grNumber:''}));
    let application:any=null;
    const applicationId=safePublicText(args?.applicationId,120), reference=normalizeAssistantContactName(safePublicText(args?.referenceCode,120));
    if(applicationId)application=rows.find((r:any)=>String(r.id)===applicationId)||null;
    else if(reference)application=rows.find((r:any)=>normalizeAssistantContactName(r.reference_code)===reference)||null;
    else {const resolved=mariaResolveByNameOrGr(rows,args);if(!resolved.row)return {result:resolved};application=resolved.row;}
    if(!application)return {result:{status:'not_found',message:'Admission application was not found in this school.'}};
    const readiness:any=await readHeadmasterChannelReadiness(activeUser.schoolId);
    let channel=mariaNormalizeChannel(args?.channel);
    const mobile=safePublicText(application.mobile||application.application_payload?.guardian?.mobile,80);
    const email=safePublicText(application.email||application.application_payload?.guardian?.email,320);
    if(!channel){if(readiness.whatsapp&&mobile)channel='whatsapp';else if(readiness.email&&email)channel='email';}
    if(!channel)return {result:{status:'needs_channel',referenceCode:application.reference_code,available:{whatsapp:Boolean(readiness.whatsapp&&mobile),email:Boolean(readiness.email&&email),call:Boolean(mobile)},message:'Choose WhatsApp or Email for a message. A device call handoff is also available when a mobile number exists.'}};
    if(channel==='website')return {result:{status:'unreachable',message:'Admission applicants do not have an authenticated Website/App recipient yet. Choose WhatsApp or Email.'}};
    if(!readiness[channel]||(channel==='whatsapp'&&!mobile)||(channel==='email'&&!email))return {result:{status:'unreachable',channel,message:`${channel} is not configured or the applicant has no stored ${channel==='email'?'email':'mobile number'}.`}};
    const context=await loadUniversalAssistantContext(activeUser); const languageCode=safePublicText(args?.languageCode,20).toLowerCase()||'en';
    const body=mariaAdmissionMessage(languageCode,context.school.name,safePublicText(application.guardian_name,180),safePublicText(application.student_name,180)||'Student',safePublicText(application.reference_code,120),safePublicText(application.status,80)||'new');
    const title=languageCode==='hi'?'प्रवेश आवेदन फॉलो-अप':languageCode==='ur'?'داخلہ درخواست فالو اپ':languageCode==='mr'?'प्रवेश अर्ज फॉलो-अप':'Admission application follow-up';
    const summary=`Send ${channel} admission follow-up for ${application.student_name} (${application.reference_code}); current canonical status is ${application.status}.`;
    return mariaStorePreparedAction(activeUser,'admission_followup',{applicationId:String(application.id),referenceCode:String(application.reference_code||''),status:String(application.status||''),channel,languageCode,title,body},summary,'Confirm & send admission follow-up');
  }

  async function prepareMariaSchoolNotice(activeUser: ActiveUserContext, args: any) {
    const role=String(activeUser.role||'').toLowerCase();
    if(!['headmaster','clerk'].includes(role))return {result:{status:'forbidden',message:'School-wide Maria notice preparation is available to Headmaster/Clerk only.'}};
    const title=safePublicText(args?.title,300), body=safePublicText(args?.body,6000);
    if(!title||!body)return {result:{status:'needs_content',message:'Please provide both the notice title and message.'}};
    const rawRoles=Array.isArray(args?.audienceRoles)?args.audienceRoles:[args?.audienceRole].filter(Boolean);
    const audienceRoles=Array.from(new Set(rawRoles.map((v:any)=>safePublicText(v,40).toLowerCase()).flatMap((v:string)=>v==='all'?['student','parent','teacher','clerk','peon']:[v]).filter((v:string)=>['student','parent','teacher','clerk','peon'].includes(v))));
    if(!audienceRoles.length)return {result:{status:'needs_audience',message:'Choose the audience: Student, Parent, Teacher, Clerk, Peon or All.'}};
    const rawChannels=Array.isArray(args?.channels)?args.channels:[args?.channel].filter(Boolean);
    const channels=Array.from(new Set(rawChannels.map(mariaNormalizeChannel).filter(Boolean)));
    if(role==='headmaster'&&!channels.length)channels.push('website');
    const languageCode=safePublicText(args?.languageCode,20).toLowerCase()||'en';
    if(role==='clerk'){
      const summary=`Submit Clerk notice draft “${title}” for Headmaster approval; audience: ${audienceRoles.join(', ')}. No notice will be published until Headmaster approval.`;
      return mariaStorePreparedAction(activeUser,'clerk_notice_draft',{title,body,audienceRoles,languageCode},summary,'Confirm & submit draft');
    }
    const readiness:any=await readHeadmasterChannelReadiness(activeUser.schoolId); const unavailable=channels.filter((c:string)=>!readiness[c]);
    if(unavailable.length)return {result:{status:'unavailable',message:`${unavailable.join(', ')} is not configured for this school/server yet.`}};
    const summary=`Send school notice “${title}” to ${audienceRoles.join(', ')} via ${channels.join(', ')}.`;
    return mariaStorePreparedAction(activeUser,'headmaster_notice',{title,body,audienceRoles,channels,languageCode},summary,'Confirm & send school notice');
  }

  async function confirmMariaPreparedActionUnlocked(activeUser: ActiveUserContext, actionIdRaw: string) {
    if(!supabaseAdmin)throw new Error('Maria action service is unavailable.');
    const actionId=safePublicText(actionIdRaw,120); if(!actionId)return {result:{status:'needs_action_id',message:'No prepared Maria action was supplied.'}};
    const state:any=await mariaActionState(activeUser,actionId);
    if(!state.prepared)return {result:{status:'not_found',message:'This prepared Maria action is unavailable or does not belong to your login.'}};
    if(state.completed)return {result:{status:'already_completed',message:safePublicText(state.completed.summary,500)||'This Maria action was already completed.'}};
    if(state.cancelled)return {result:{status:'cancelled',message:'This prepared Maria action was cancelled. Nothing will be sent.'}};
    const metadata:any=state.prepared.metadata||{}; const payload:any=metadata.payload||{}; const actionType=String(metadata.action_type||'');
    const expiresAt=Date.parse(String(metadata.expires_at||'')); if(!Number.isFinite(expiresAt)||expiresAt<Date.now())return {result:{status:'expired',message:'This prepared action expired. Ask Maria to prepare it again using current school data.'}};
    let outcome:any={}; let resultSummary='Maria action completed.'; let clientAction:any=null;

    if(actionType==='absence_followup_teacher'){
      if(!['teacher','class_teacher','headmaster'].includes(activeUser.role))throw new Error('Class Teacher permission is no longer available.');
      const groups=Array.isArray(payload.groups)?payload.groups:[]; let sentStudents=0,recipientCount=0,websiteCreated=0,externalQueued=0;
      for(const group of groups){const ids=Array.isArray(group.studentIds)?group.studentIds.map(String):[];if(!ids.length)continue;const send:any=await sendTeacherCommunicationServer(activeUser,{scopeId:String(group.scopeId||''),recipientStudentIds:ids,title:payload.title,body:payload.body,messageType:ids.length===1?'direct':'announcement',audience:'parents',channels:[payload.channel],languageCode:payload.languageCode||'en',languageName:'Maria',priority:'normal'});sentStudents+=Number(send.studentCount||0);recipientCount+=Number(send.recipientCount||0);websiteCreated+=Number(send.websiteCreated||0);externalQueued+=Number(send.externalQueued||0);}
      outcome={status:'sent',studentCount:sentStudents,recipientCount,websiteCreated,externalQueued}; resultSummary=`Maria sent the confirmed attendance follow-up for ${sentStudents} Student(s).`;
    } else if(actionType==='absence_followup_headmaster'){
      if(activeUser.role!=='headmaster')throw new Error('Headmaster permission is no longer available.');
      const attendance=await supabaseAdmin.from('edunixo_attendance_entries').select('student_id,status').eq('school_id',activeUser.schoolId).eq('attendance_date',String(payload.date||'')).in('student_id',Array.isArray(payload.studentIds)?payload.studentIds:[]);
      if(attendance.error)throw attendance.error; const stillAbsent=new Set((attendance.data||[]).filter((r:any)=>['a','absent'].includes(String(r.status||'').trim().toLowerCase())).map((r:any)=>String(r.student_id||'')));
      const intended=(Array.isArray(payload.studentIds)?payload.studentIds:[]).map(String); if(stillAbsent.size!==intended.length)return {result:{status:'stale',message:'Attendance changed after this follow-up was prepared. Ask Maria to prepare it again before sending.'}};
      const parents=await loadHeadmasterCommunicationAudience(activeUser.schoolId,['parent']); const recipients=(parents||[]).filter((r:any)=>stillAbsent.has(String(r.recipientStudentId||'')));
      const send:any=await mariaSendHeadmasterTargetedCommunication(activeUser,{title:payload.title,body:payload.body,channels:[payload.channel],recipients,languageCode:payload.languageCode,audienceType:'parent',purpose:'absence_followup'});
      outcome={status:'sent',studentCount:intended.length,recipientCount:send.recipientCount,dispatch:send.dispatch}; resultSummary=`Maria sent the confirmed attendance follow-up for ${intended.length} absent Student(s).`;
    } else if(actionType==='fee_reminder'){
      if(activeUser.role!=='headmaster')throw new Error('Headmaster permission is no longer available.');
      const snapshot:any=await buildClerkFeeSnapshot(activeUser.schoolId,null); const student=(snapshot.profiles||[]).find((s:any)=>String(s.id)===String(payload.studentId||''));
      if(!student)return {result:{status:'stale',message:'The Student fee profile is no longer available. Prepare the reminder again.'}};
      if(Math.abs(Number(student.balance||0)-Number(payload.balance||0))>0.009)return {result:{status:'stale',message:'The Student fee balance changed after the reminder was prepared. Ask Maria to prepare a fresh reminder.'}};
      const parents=await loadHeadmasterCommunicationAudience(activeUser.schoolId,['parent']); const recipients=(parents||[]).filter((r:any)=>String(r.recipientStudentId||'')===String(student.id));
      const send:any=await mariaSendHeadmasterTargetedCommunication(activeUser,{title:payload.title,body:payload.body,channels:[payload.channel],recipients,languageCode:payload.languageCode,audienceType:'parent',purpose:'fee_reminder'});
      outcome={status:'sent',studentName:student.name,balance:Number(student.balance||0),recipientCount:send.recipientCount,dispatch:send.dispatch}; resultSummary=`Maria sent the confirmed fee reminder for ${student.name}.`;
    } else if(actionType==='admission_followup'){
      if(activeUser.role!=='headmaster')throw new Error('Headmaster permission is no longer available.');
      const appRead=await supabaseAdmin.from('school_admission_applications').select('id,reference_code,student_name,guardian_name,mobile,email,status,application_payload').eq('school_id',activeUser.schoolId).eq('id',String(payload.applicationId||'')).maybeSingle(); if(appRead.error)throw appRead.error;
      const app:any=appRead.data; if(!app)return {result:{status:'stale',message:'The admission application is no longer available.'}};
      if(String(app.status||'')!==String(payload.status||''))return {result:{status:'stale',message:'The admission status changed after the follow-up was prepared. Ask Maria to prepare a fresh follow-up.'}};
      const recipient={recipientStudentId:null,recipientTeacherRecordId:null,recipientUserId:null,recipientName:safePublicText(app.guardian_name,240)||`Parent/Guardian of ${safePublicText(app.student_name,180)||'Applicant'}`,recipientMobile:safePublicText(app.mobile||app.application_payload?.guardian?.mobile,80)||null,recipientEmail:safePublicText(app.email||app.application_payload?.guardian?.email,320)||null,audienceKind:'admission_guardian',preferredLanguage:null};
      const send:any=await mariaSendHeadmasterTargetedCommunication(activeUser,{title:payload.title,body:payload.body,channels:[payload.channel],recipients:[recipient],languageCode:payload.languageCode,audienceType:'admission_guardian',purpose:'admission_followup'});
      outcome={status:'sent',referenceCode:app.reference_code,recipientCount:send.recipientCount,dispatch:send.dispatch}; resultSummary=`Maria sent the confirmed admission follow-up for ${app.student_name} (${app.reference_code}).`;
    } else if(actionType==='headmaster_notice'){
      if(activeUser.role!=='headmaster')throw new Error('Headmaster permission is no longer available.');
      const recipients=await loadHeadmasterCommunicationAudience(activeUser.schoolId,payload.audienceRoles||[]);
      const send:any=await mariaSendHeadmasterTargetedCommunication(activeUser,{title:payload.title,body:payload.body,channels:payload.channels,recipients,languageCode:payload.languageCode,audienceType:(payload.audienceRoles||[]).join(','),purpose:'school_notice'});
      outcome={status:'sent',recipientCount:send.recipientCount,dispatch:send.dispatch}; resultSummary=`Maria sent the confirmed school notice “${safePublicText(payload.title,200)}”.`;
    } else if(actionType==='clerk_notice_draft'){
      if(activeUser.role!=='clerk')throw new Error('Clerk permission is no longer available.');
      const userRead=await supabaseAdmin.from('users').select('full_name').eq('id',activeUser.userId).maybeSingle();
      const draft={title:safePublicText(payload.title,300),titleHi:safePublicText(payload.title,300),titleUr:safePublicText(payload.title,300),content:safePublicText(payload.body,6000),contentHi:safePublicText(payload.body,6000),contentUr:safePublicText(payload.body,6000),category:'General',targetRoles:Array.isArray(payload.audienceRoles)?payload.audienceRoles:[],preparedBy:safePublicText(userRead.data?.full_name,200)||'Clerk'};
      const write=await supabaseAdmin.from('audit_logs').insert({school_id:activeUser.schoolId,actor_user_id:activeUser.userId,actor_kind:'school_user',action:'communication.notice.requested',entity_type:'communication_notice',entity_id:null,summary:`Clerk prepared notice draft: ${draft.title}.`,metadata:{workflow:'communication_notice',request_status:'pending',draft,maria_generated:true}}).select('id').single(); if(write.error)throw write.error;
      outcome={status:'submitted_for_approval',requestId:String(write.data?.id||'')}; resultSummary=`Maria submitted the confirmed Clerk notice draft “${draft.title}” for Headmaster approval.`;
      const route=mariaFeatureRoute(activeUser,'communication'); if(route)clientAction={type:'navigate',label:'Open Communication',moduleId:route.moduleId,featureId:route.featureId,feature:'communication'};
    } else return {result:{status:'unsupported',message:'This prepared Maria action type is no longer supported.'}};

    const completion=await supabaseAdmin.from('audit_logs').insert({school_id:activeUser.schoolId,actor_user_id:activeUser.userId,actor_kind:'school_user',action:'ai.maria.action.completed',entity_type:'maria_action',entity_id:actionId,summary:safePublicText(resultSummary,600),metadata:{prepared_action_id:actionId,action_type:actionType,status:'completed',outcome:{status:outcome?.status||'completed',recipientCount:Number(outcome?.recipientCount||0),studentCount:Number(outcome?.studentCount||0)}}});
    if(completion.error)throw completion.error;
    return {result:{...outcome,message:resultSummary},clientAction};
  }

  async function confirmMariaPreparedAction(activeUser: ActiveUserContext, actionIdRaw: string) {
    const actionId = safePublicText(actionIdRaw, 120);
    if (!actionId) return { result:{ status:'needs_action_id', message:'No prepared Maria action was supplied.' } };
    const lockKey = `${activeUser.schoolId}:${activeUser.userId}:${actionId}`;
    if (mariaActionExecutionLocks.has(lockKey)) return { result:{ status:'in_progress', message:'This Maria action is already being confirmed. Please wait for the current confirmation to finish.' } };
    mariaActionExecutionLocks.add(lockKey);
    try {
      return await confirmMariaPreparedActionUnlocked(activeUser, actionId);
    } finally {
      mariaActionExecutionLocks.delete(lockKey);
    }
  }

  async function cancelMariaPreparedAction(activeUser: ActiveUserContext, actionIdRaw: string) {
    if(!supabaseAdmin)throw new Error('Maria action service is unavailable.'); const actionId=safePublicText(actionIdRaw,120);
    const lockKey=`${activeUser.schoolId}:${activeUser.userId}:${actionId}`; if(mariaActionExecutionLocks.has(lockKey))return {result:{status:'in_progress',message:'This Maria action is already being confirmed and cannot be cancelled at the same moment.'}};
    const state:any=await mariaActionState(activeUser,actionId);
    if(!state.prepared)return {result:{status:'not_found',message:'This prepared Maria action is unavailable.'}}; if(state.completed)return {result:{status:'already_completed',message:'This Maria action was already completed and cannot be cancelled here.'}}; if(state.cancelled)return {result:{status:'already_cancelled',message:'This Maria action is already cancelled.'}};
    const write=await supabaseAdmin.from('audit_logs').insert({school_id:activeUser.schoolId,actor_user_id:activeUser.userId,actor_kind:'school_user',action:'ai.maria.action.cancelled',entity_type:'maria_action',entity_id:actionId,summary:'User cancelled a prepared Maria action.',metadata:{prepared_action_id:actionId,status:'cancelled'}}); if(write.error)throw write.error;
    return {result:{status:'cancelled',message:'The prepared action was cancelled. Nothing was sent.'}};
  }

  async function prepareMariaSchoolDial(activeUser: ActiveUserContext) {
    const context=await loadUniversalAssistantContext(activeUser); const phone=String(context.school.phone||'').replace(/[^+0-9]/g,'');
    if(!phone||phone.replace(/\D/g,'').length<7)return {result:{status:'missing_number',message:'No active school phone number is stored in School Profile.'}};
    return {result:{status:'ready',schoolName:context.school.name,action:'open_device_dialer'},clientAction:{type:'dial',label:`Call ${context.school.name}`,uri:`tel:${phone}`,contactName:context.school.name}};
  }

  async function resolveMariaParentChild(activeUser: ActiveUserContext, args: any) {
    if (!supabaseAdmin || activeUser.role !== 'parent') return { status:'forbidden', message:'A Parent login is required.' };
    const approvedIds=await loadApprovedParentStudentIds(activeUser.schoolId,activeUser.userId);
    if(!approvedIds.length)return {status:'none',message:'No Headmaster-approved child link is available.'};
    const read=await supabaseAdmin.from('students').select('id,full_name,name_en,name,gr_number,current_class_name,class_name,current_division_name,division_name,division,status,is_active').eq('school_id',activeUser.schoolId).in('id',approvedIds);
    if(read.error)throw read.error;
    const rows=(read.data||[]).map((row:any)=>({id:String(row.id),name:safePublicText(row.full_name||row.name_en||row.name,180)||'Student',grNumber:safePublicText(row.gr_number,80),className:safePublicText(row.current_class_name||row.class_name,80),division:safePublicText(row.current_division_name||row.division_name||row.division,80)}));
    const requestedId=safePublicText(args?.studentId,120);
    if(requestedId){const row=rows.find((r:any)=>r.id===requestedId);return row?{status:'ready',row}:{status:'not_found',message:'That child is not linked to this Parent login.'};}
    const name=normalizeAssistantContactName(safePublicText(args?.studentName,180));
    if(name){const exact=rows.filter((r:any)=>normalizeAssistantContactName(r.name)===name);const loose=exact.length?exact:rows.filter((r:any)=>normalizeAssistantContactName(r.name).includes(name)||name.includes(normalizeAssistantContactName(r.name)));if(loose.length===1)return {status:'ready',row:loose[0]};if(loose.length>1)return {status:'ambiguous',candidates:loose.slice(0,6).map((r:any)=>({id:r.id,name:r.name,className:r.className,division:r.division}))};return {status:'not_found',message:'That child is not linked to this Parent login.'};}
    if(rows.length===1)return {status:'ready',row:rows[0]};
    return {status:'needs_child',children:rows.map((r:any)=>({id:r.id,name:r.name,className:r.className,division:r.division})),message:'Please say which linked child you mean.'};
  }

  async function prepareMariaParentPortalForm(activeUser: ActiveUserContext,args:any) {
    const resolved:any=await resolveMariaParentChild(activeUser,args||{});if(resolved.status!=='ready')return {result:resolved};
    const student=resolved.row;const kind=String(args?.kind||'').trim().toLowerCase();
    if(kind==='leave'){
      const startDate=safePublicText(args?.startDate,20),endDate=safePublicText(args?.endDate,20),reason=safePublicText(args?.reason,1500);
      return {result:{status:'ready',student,message:'Maria prepared the existing child leave form. The Parent must review and press Submit Child Leave.'},clientAction:{type:'maria_parent_portal',commandId:randomUUID(),command:'prefill_leave',moduleId:'pa-leave',featureId:'pa-submit-child-leave',studentId:student.id,studentName:student.name,startDate,endDate,reason,statusMessage:'Maria prepared the existing Parent leave form. Nothing was submitted.'}};
    }
    if(kind==='service_request'||kind==='certificate'){
      const rawType=String(args?.requestType||'certificate').trim().toLowerCase();const allowed=new Set(['certificate','library','profile_correction','support']);const requestType=allowed.has(rawType)?rawType:'certificate';
      const title=safePublicText(args?.title,300),details=safePublicText(args?.details,2500);
      return {result:{status:'ready',student,requestType,message:'Maria prepared the existing Parent service-request form. The Parent must review and press the existing Submit button.'},clientAction:{type:'maria_parent_portal',commandId:randomUUID(),command:'prefill_service_request',moduleId:'pa-certificate-requests',featureId:'pa-request-child-certificate',studentId:student.id,studentName:student.name,requestType,title,details,statusMessage:'Maria prepared the existing Parent request form. Nothing was submitted.'}};
    }
    return {result:{status:'needs_kind',message:'Say whether you want a child leave form or a service/certificate request form.'}};
  }

  async function prepareMariaParentDial(activeUser: ActiveUserContext,args:any) {
    if(!supabaseAdmin)return {result:{status:'unavailable',message:'Parent contact service is unavailable.'}};
    const role=String(activeUser.role||'').toLowerCase();if(!['teacher','class_teacher','headmaster'].includes(role))return {result:{status:'forbidden',message:'Parent dial handoff is available only to authorised teaching/Headmaster roles.'}};
    let candidates:any[]=[];
    if(role==='headmaster'){
      const master:any=await loadClerkStudentMaster(activeUser.schoolId);const parents:any[]=await loadHeadmasterCommunicationAudience(activeUser.schoolId,['parent']);const parentByStudent=new Map<string,any[]>();for(const r of parents){const key=String(r.recipientStudentId||'');if(key)parentByStudent.set(key,[...(parentByStudent.get(key)||[]),r]);}
      candidates=(master.students||[]).map((student:any)=>{const recs=parentByStudent.get(String(student.id))||[];const contact=recs.find((r:any)=>r.recipientMobile)||recs[0]||{};return {...student,id:String(student.id),name:safePublicText(student.name||student.fullName||student.full_name,180)||'Student',parentMobile:safePublicText(contact.recipientMobile,80),parentName:safePublicText(contact.recipientName,180)};});
    }else{
      const comm:any=await loadTeacherCommunicationScopes(activeUser);const scopes=(comm.scopes||[]).filter((scope:any)=>scope.scopeType==='class_teacher');
      for(const scope of scopes){try{const data:any=await loadTeacherCommunicationRecipients(activeUser,String(scope.id));for(const r of data.recipients||[])candidates.push({id:String(r.studentId||''),name:safePublicText(r.studentName,180)||'Student',grNumber:safePublicText(r.grNumber,80),parentMobile:safePublicText(r.parentMobile,80),parentName:safePublicText(r.parentName,180)});}catch{}}
    }
    const resolved:any=mariaResolveByNameOrGr(candidates,args||{});if(!resolved.row)return {result:resolved};const student=resolved.row;const dialable=String(student.parentMobile||'').replace(/[^+0-9]/g,'');
    if(!dialable||dialable.replace(/\D/g,'').length<7)return {result:{status:'missing_number',studentName:student.name,message:'No reachable Parent/Guardian mobile number is stored for this Student in your authorised scope.'}};
    const contactName=safePublicText(student.parentName,180)||`Parent/Guardian of ${student.name}`;
    return {result:{status:'ready',studentName:student.name,contactName,action:'open_device_dialer',note:'Android/carrier audio remains outside Maria; this only opens the user-controlled dialer.'},clientAction:{type:'dial',label:`Call ${contactName}`,uri:`tel:${dialable}`,contactName}};
  }

