  async function executeUniversalLiveToolWithTimeout(activeUser:ActiveUserContext,name:string,args:any) {
    let timer:ReturnType<typeof setTimeout>|null=null;
    try {
      return await Promise.race([
        executeUniversalLiveTool(activeUser,name,args),
        new Promise<any>((_resolve,reject)=>{timer=setTimeout(()=>reject(new Error('Maria tool timed out safely. Please try the request again.')),15000);})
      ]);
    } finally { if(timer)clearTimeout(timer); }
  }

  function sanitizeRealtimeClientPayload(payload: any) {
    const input = payload?.realtimeInput;
    if (!input || typeof input !== 'object') return null;
    const realtimeInput: any = {};
    if (input.audio && typeof input.audio === 'object') {
      const data = String(input.audio.data || '');
      const mimeType = String(input.audio.mimeType || '');
      if (!data || data.length > 350_000 || mimeType !== 'audio/pcm;rate=16000') return null;
      realtimeInput.audio = { data, mimeType };
    }
    if (typeof input.text === 'string') {
      const text = safePublicText(input.text, 4000);
      if (text) realtimeInput.text = text;
    }
    if (input.audioStreamEnd === true) realtimeInput.audioStreamEnd = true;
    return Object.keys(realtimeInput).length ? { realtimeInput } : null;
  }

  function publicMariaSystemInstruction(school:any,uiLanguage:string) {
    const published={
      schoolName:safePublicText(school?.schoolName,220),schoolCode:safePublicText(school?.schoolCode,100),tagline:safePublicText(school?.tagline,500),heroTitle:safePublicText(school?.heroTitle,500),heroSubtitle:safePublicText(school?.heroSubtitle,1200),
      admissionsEnabled:school?.admissionsEnabled!==false,admissionsOpen:school?.admissionsOpen===true,admissionSession:safePublicText(school?.admissionSession,120),admissionTitle:safePublicText(school?.admissionTitle,400),admissionDescription:safePublicText(school?.admissionDescription,2500),
      contactDetails:school?.contactDetails&&typeof school.contactDetails==='object'?Object.fromEntries(Object.entries(school.contactDetails).slice(0,30).map(([k,v])=>[safePublicText(k,80),safePublicText(v,800)]).filter(([k,v])=>Boolean(k)&&Boolean(v))):{},
      sections:Array.isArray(school?.sections)?school.sections.filter((x:any)=>x?.enabled!==false).slice(0,24).map((x:any)=>({key:safePublicText(x?.key,60),title:safePublicText(x?.title,400),body:safePublicText(x?.body,3000),items:Array.isArray(x?.items)?x.items.slice(0,20).map((v:any)=>safePublicText(v,600)).filter(Boolean):[]})):[],
      admissionCampaign:school?.admissionCampaign?{title:safePublicText(school.admissionCampaign.title,400),description:safePublicText(school.admissionCampaign.description,2500),sessionName:safePublicText(school.admissionCampaign.sessionName,120),status:safePublicText(school.admissionCampaign.status,80)}:null
    };
    return `You are Maria, pronounced Maa-ree-yaa (मारिया), the public realtime receptionist for ${published.schoolName||'this school'} on its official Classtago website.

PUBLIC-ONLY SECURITY BOUNDARY:
- You are NOT signed into the ERP. You have no access to students, parents, staff private data, attendance, marks, results, fees ledgers, phone contacts, accounts, messages, internal admissions records, or any authenticated tool.
- Answer only from the PUBLISHED SCHOOL WEBSITE DATA below. Never invent a fee amount, admission decision, school timing, rule, contact detail or policy that is absent from this payload.
- If asked for private/student-specific information, explain briefly that the user must sign in through the school portal. Do not ask for passwords, OTPs, Aadhaar, marks, or other private credentials.
- For admissions, explain only published availability/instructions and guide the visitor to the visible admission form; never claim an application was submitted or approved. If the visitor asks to open Apply/Admission, Contact, About, Academics, Facilities, Notices or Gallery, use open_public_school_section. This tool only changes the visible public page; it cannot access or modify ERP data.
- Match the visitor's current language naturally, including Indian languages and code-switching. UI language hint: ${safePublicText(uiLanguage,30)||'auto'}.
- Keep spoken responses natural and concise. Respect interruption immediately.
- Whenever saying your own name, pronounce Maria as Maa-ree-yaa / मारिया, never मरिया.

PUBLISHED SCHOOL WEBSITE DATA:
${JSON.stringify(published).slice(0,42000)}`;
  }

