        socket.on('open',()=>{if(mySerial!==serial||!school)return;socket.send(JSON.stringify({setup:{model:`models/${GEMINI_LIVE_MODEL}`,generationConfig:{responseModalities:['AUDIO'],speechConfig:{voiceConfig:{prebuiltVoiceConfig:{voiceName:voice}}}},systemInstruction:{parts:[{text:publicMariaSystemInstruction(school,uiLanguage)}]},inputAudioTranscription:{},outputAudioTranscription:{},realtimeInputConfig:{automaticActivityDetection:{disabled:false,prefixPaddingMs:20,silenceDurationMs:350},activityHandling:'START_OF_ACTIVITY_INTERRUPTS'},sessionResumption:resumeHandle?{handle:resumeHandle}:{},contextWindowCompression:{slidingWindow:{}},tools:[{functionDeclarations:[{name:'open_public_school_section',description:'Open one visible section of the current published school website. This performs no ERP read/write and exposes no private data.',parameters:{type:'OBJECT',properties:{section:{type:'STRING',description:'admissions, contact, about, academics, facilities, notices or gallery'}},required:['section']}}]}]}}));sendClient({type:'event',event:isResume?'reconnecting':'provider_connected',provider:'gemini_live_public'});});
